window.IA = {"lang": "fi", "ui": {"app_title": "ClayArena Interpreter Academy", "tagline": "Haulikkoammunta tulkeille – alusta alkaen", "hero_p": "Kaksitoista tehtävää, joissa opit Parcours de Chasse – Sporting™- ja Compak® Sporting -lajien kielen: kiekot ja niiden lento, ase, ennakko ja ampumatekniikka, FITASCin säännöt, tuomarin ilmoitukset ja lajin etiketti. Harjoittele sitten kuin oikealla ampumapaikalla: käännä valmentajan sanat, tunnista kiekko, löydä ennakko ja tee tuomarin ratkaisu.", "missions": "Tehtävät", "practice": "Harjoittelu", "start": "Aloita", "continue": "Jatka", "lessons_n": "oppituntia", "min": "min", "back": "Takaisin", "back_mission": "Tehtävään", "home": "Etusivu", "key_points": "Tärkeimmät asiat", "coach_says": "Valmentaja sanoo", "listen": "Kuuntele", "reveal": "Näytä merkitys", "meaning": "Merkitys", "say_it": "Näin sanot sen", "terms": "Termit", "rules_refs": "FITASCin säännöissä", "sources": "Lähteet", "quiz": "Testaa itsesi", "correct": "Oikein!", "wrong": "Ei aivan.", "next": "Seuraava", "next_lesson": "Seuraava oppitunti", "finish_lesson": "Oppitunti suoritettu", "xp": "XP", "level": "Taso", "levels": ["Aloittelija", "Kuuntelija", "Ratatulkki", "Ampumapaikan tulkki", "Ammattitulkki"], "done_of": "suoritettu", "game_coach": "Käännä valmentaja", "game_coach_d": "Kuule valmentajan lause englanniksi ja valitse, mitä se todella tarkoittaa.", "game_flight": "Nimeä lento", "game_flight_d": "Katso kiekon lentoa ja nimeä kiekkotyyppi.", "game_lead": "Ennakkolaboratorio", "game_lead_d": "Katso, miten ennakko toimii kullakin menetelmällä – ja laukaise sitten itse.", "game_call": "Tuomarin ratkaisu", "game_call_d": "Todellisia tilanteita ampumapaikalla: mitä tuomari päättää?", "game_terms": "Termikortit", "game_terms_d": "Yhdistä englanninkielinen termi sanaan, jota ampujat käyttävät omalla kielelläsi.", "game_exam": "Loppukoe", "game_exam_d": "30 kysymystä kaikista tehtävistä. Läpäise 80 %:lla ja saat todistuksen.", "which_flight": "Mikä kiekkotyyppi tämä on?", "which_meaning": "Mitä valmentaja tarkoittaa?", "which_term": "Miten ampujat sanovat sen omalla kielelläsi?", "which_def": "Mitä tämä termi tarkoittaa?", "launch": "Lähetä", "again": "Uudelleen", "score": "Pisteet", "play_again": "Pelaa uudelleen", "method": "Menetelmä", "m_maintained": "Pysyvä ennakko", "m_swing": "Läpiveto", "m_pullaway": "Edestä irtiveto", "m_ambush": "Väijytys", "speed": "Kiekon nopeus", "distance": "Etäisyys", "demo": "Katso menetelmä", "try": "Sinun vuorosi: paina, kun ampuisit", "shoot": "Ammu", "hit": "Osuma! Kiekko hajoaa.", "behind": "Takana – laukaus meni kiekon taakse", "ahead": "Edessä – laukaus meni kiekon edelle", "perceived": "Ennakko, jonka näet päätöshetkellä", "actual": "Todellinen ennakko laukaushetkellä", "lab_note": "Hidastettu, opetusta varten yksinkertaistettu fysiikka: haulien keskinopeus noin 330 m/s ja 0,15 s päätöksestä laukaukseen. Todellinen ennakko riippuu myös ampujasta, patruunasta ja kulmasta.", "exam_pass": "Läpäisit! Voit nyt hakea todistuksesi.", "exam_fail": "Ei vielä – tarvitaan 80 %. Kertaa tehtävät ja yritä uudelleen.", "cert_name": "Nimesi todistukseen", "cert_print": "Tulosta tai tallenna PDF:nä", "cert_title": "Todistus", "cert_text": "on suorittanut ClayArena Interpreter Academy -kurssin, joka käsittelee Parcours de Chasse – Sporting™- ja Compak® Sporting -lajien terminologiaa, tekniikkaa, FITASCin sääntöjä ja etikettiä.", "cert_note": "ClayArenan itseopiskelutodistus; se ei ole FITASCin pätevyys.", "question": "Kysymys", "of": "/", "term_all": "Kaikilla ClayArenan kielillä", "term_note_anglicism": "Ampujat käyttävät usein vain englanninkielistä sanaa.", "confidence_low": "vahvistettava", "reset": "Nollaa edistyminen", "reset_confirm": "Poistetaanko kaikki edistyminen ja XP tältä laitteelta?", "saved_local": "Edistyminen tallennetaan tälle laitteelle.", "disclaimer": "ClayArenan kurssi. FITASCin säännöt esitetään omin sanoin kerrottuina ja linkitettyinä sääntösivuihin; vain FITASCin virallinen teksti on sitova. Parcours de Chasse – Sporting™ ja Compak® Sporting ovat FITASCin tavaramerkkejä.", "language": "Kieli", "all_missions_done": "Kaikki tehtävät suoritettu – loppukokeen aika!", "decision": "päätös", "shot_moment": "laukaus", "lead_word": "ennakko", "unit_m": "m", "unit_ft": "ft", "unit_ms": "m/s", "glossary_page": "Sanastosivu", "pair_report": "Laukauksesta lähtevä kaksoiskiekko (on report): 2. kiekko lähtee 1. laukauksen äänestä", "pair_sim": "Yhtäaikainen kaksoiskiekko: molemmat kiekot lähtevät yhdessä", "pair_rafale": "Rafale (peräkkäinen kaksoiskiekko): 2. kiekko samasta heittimestä heti 1. jälkeen"}, "missions": [{"id": "sport", "icon": "flag", "title": "Laji kymmenessä minuutissa", "intro": "Ennen kuin käännät yhtäkään valmennusvinkkiä, tarvitset kokonaiskuvan: mihin oikeastaan ammutaan, kuka kirjoittaa säännöt, miltä Parcours de Chasse – Sporting™ -rata ja Compak® Sporting -kenttä näyttävät ja miten kilpailupäivä etenee. Viisi lyhyttä oppituntia antaa sinulle kartan; jokainen myöhempi tehtävä täydentää yksityiskohtia.", "lessons": [{"id": "sport-what-is-clay", "minutes": 5, "title": "Kiekkoja, ei lintuja: mikä tämä laji on", "body": ["Haulikkoammunta savikiekkoihin on laji, jossa ampuja rikkoo haulikolla pieniä lentäviä kiekkoja. Kiekkoa kutsutaan englanniksi nimellä target tai clay; ampujat kutsuvat sitä usein linnuksi (bird), mutta kukaan ei ammu eläviä eläimiä. FITASCin säännöt toteavat suoraan, että eläviin eläimiin ampuminen ei ole sallittua, ja turvallisuus sekä ympäristöstä huolehtiminen ovat etusijalla.", "Jokaisen kiekon heittää kone, jota kutsutaan heittimeksi (trap). Sen reitti ilmassa (tai maata pitkin) on lentorata. Ase on sileäpiippuinen haulikko: se ampuu patruunan, joka on täynnä pieniä hauleja, ja ne leviävät pieneksi pilveksi, hauliparveksi. Siksi ampuja osoittaa aseella sinne, minne kiekko on menossa, ei sinne, missä se on nyt.", "Tämä kurssi käsittelee kahta kansainvälisen FITASC-liiton lajia. Parcours de Chasse – Sporting™ (lyhyesti Sporting™) jäljittelee metsästystä: heittimet on piilotettu pelloille ja metsiin, ja kiekot lentävät kuin peltopyy, sorsa tai fasaani tai vierivät kuin jänis. Compak® Sporting on tiivis versio: sama kiekkojen monipuolisuus, mutta yhdellä pienellä kentällä, jossa on viisi ampumapaikkaa rivissä ja kuusi heitintä.", "Kuulet myös trapista ja skeetistä. Ne ovat eri lajeja, joissa lentoradat ovat kiinteitä ja toistuvia; olympiatrap ja -skeet kuuluvat toiselle liitolle. Älä sekoita niiden sääntöjä Sporting™- tai Compak® Sporting -lajeihin.", "Osuman näkee heti: kiekko rikkoutuu tai siitä lentää ainakin näkyvä pala. Tämä selkeys tekee lajista helpon seurata ja sinulle helpon ymmärtää ensimmäisestä päivästä lähtien."], "key_points": ["Ammutaan heittimien heittämiin savikiekkoihin, ei koskaan eläviin eläimiin.", "Haulikko ampuu pilven pieniä hauleja, joten ampuja osoittaa kiekon edelle.", "Sporting™ jäljittelee metsästystä luonnonmaastossa; Compak® Sporting on sen tiivis versio yhdellä kentällä.", "Trap ja skeet ovat muita lajeja omine sääntöineen."], "terms": ["target", "trap", "trajectory", "shotgun", "cartridge", "sporting", "compak-sporting"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Clay pigeon shooting", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch1-definition", "label": "1 · What Sporting is"}, {"book": "sporting", "id": "ch1-safety-environment", "label": "1 · Safety, environment and no live animals"}, {"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak Sporting is"}], "coach_says": [{"en": "Watch this bird off trap B.", "meaning": "”Bird” on kiekko, ei oikea lintu; heitin B on B-kirjaimella merkitty kone.", "say": "Katso tätä kiekkoa heittimestä B."}, {"en": "Today we walk the Sporting course, tomorrow it's Compak.", "meaning": "Kaksi eri lajia kahtena eri päivänä.", "say": "Tänään kierretään sportingrata, huomenna on Compak."}, {"en": "Point it, don't aim it.", "meaning": "Haulikkoa liikutetaan ja osoitetaan molemmat silmät kiekossa, sillä ei tähdätä kuin kiväärillä.", "say": "Osoita, älä tähtää."}], "quiz": [{"q": "Valmentaja sanoo ”Watch the next bird.” Mitä tulet näkemään?", "options": ["Laatikosta päästetyn elävän kyyhkyn", "Heittimen heittämän savikiekon", "Lintua esittävän paperitaulun", "Droonin"], "answer": 1, "why": "”Bird” on ampujien slangia savikiekolle; FITASCin säännöt kieltävät eläviin eläimiin ampumisen."}, {"q": "Mitä haulikko ampuu?", "options": ["Yhden ainoan luodin", "Pienen nuolimaisen tikan", "Pilven pieniä hauleja", "Maalilla täytetyn kuulan"], "answer": 2, "why": "Haulit lähtevät piipunsuusta pienenä pilvenä, joten ampuja osoittaa liikkuvan kiekon edelle."}, {"q": "Mikä väite Compak® Sporting -lajista pitää paikkansa?", "options": ["Tiivis versio yhdellä kentällä, ampumapaikat rivissä", "Se on skeetin olympiaversio", "Sitä ammutaan vain eläviin riistalintuihin maastossa", "Siinä käytetään yhtä heitintä ja yhtä ampumapaikkaa"], "answer": 0, "why": "Compak® Sporting tuo Sporting™-tyyliset kiekot yhdelle pienelle kentälle, jossa on viisi ampumapaikkaa ja kuusi heitintä."}]}, {"id": "sport-fitasc", "minutes": 5, "title": "FITASC, liitot ja ClayArena", "body": ["FITASC on metsästystyyppisen kiekkoammunnan kansainvälinen liitto. Se kirjoittaa ja päivittää Parcours de Chasse – Sporting™- ja Compak® Sporting -lajien säännöt; noudattamamme painokset ovat päivätty 01/01/2025. Compak® Sporting on myös FITASCin suojaama tavaramerkki, minkä vuoksi nimi kirjoitetaan aina ®-merkillä.", "Laji on rakentunut kuin pyramidi. Alimpana ovat seurat ja ampumaradat, niiden yläpuolella kansalliset liitot, ja kansalliset liitot ovat FITASCin jäseniä. Kansallisten kilpailujen rataosuudet hyväksyy kansallinen liitto, kansainvälisten kilpailujen FITASC. Liitto voi antaa kilpailun seuran järjestettäväksi, mutta se vastaa edelleen sääntöjen soveltamisesta.", "Radalla sääntöjä soveltavat tuomarit. Jokaisella tuomarilla on kansallisen liiton myöntämä todistus, ja päätuomari tarvitsee FITASCin kansainvälisen todistuksen. Jury käsittelee kansainvälisissä kilpailuissa protestit, rangaistukset ja tekniset ongelmat. Käännät heille kaikille, joten opettele nimikkeet: tuomari (referee), päätuomari (chief referee), jury.", "Myös muita toimijoita on. Britanniassa ja Yhdysvalloissa kansalliset järjestöt ylläpitävät omia versioitaan lajista, kuten English Sportingia, eri säännöin ja sanoin. Brittiläinen tai amerikkalainen valmentaja voi käyttää näitä sanoja FITASCin kilpailussa; myöhemmät tehtävät näyttävät, miten toimia silloin.", "ClayArena on tämän kurssin takana oleva alusta. Se julkaisee kilpailukalentereita, sanastoa ja selkokielisen tiivistelmän FITASCin säännöistä, ja ClayAwayn kautta se järjestää harjoitusmatkoja. Muista: vain FITASCin virallinen teksti on sitova; tiivistelmä on opas, ei itse sääntö."], "key_points": ["FITASC kirjoittaa Sporting™- ja Compak® Sporting -lajien säännöt (painokset 01/01/2025).", "Seura, kansallinen liitto, FITASC: kansalliset rataosuudet hyväksyy liitto, kansainväliset FITASC.", "Tuomareilla on kansallinen todistus; päätuomarilla FITASCin kansainvälinen; jury käsittelee protestit.", "Vain FITASCin virallinen teksti on sitova; ClayArena tarjoaa tiivistelmän."], "terms": ["fitasc", "national-federation", "referee", "chief-referee", "jury"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak Sporting is"}, {"book": "sporting", "id": "ch15-layout-approval", "label": "15 · Who approves layouts"}, {"book": "sporting", "id": "ch15-delegation", "label": "15 · Delegating to a club"}, {"book": "sporting", "id": "ch5-referee-certificate", "label": "5 · Referee certificates"}, {"book": "sporting", "id": "ch15-jury-role", "label": "15 · Duties of the jury"}, {"book": "compak", "id": "ch19-referee-qualification", "label": "19 · Referee approval and qualifications"}], "coach_says": [{"en": "That's a CPSA term — under FITASC it's a simultaneous double.", "meaning": "Valmentaja vaihtaa brittiläisestä sanastosta FITASCin nimitykseen.", "say": "Tuo on CPSA:n termi – FITASCissa se on yhtäaikainen kaksoiskiekko."}, {"en": "Ask the chief referee, not the stand referee.", "meaning": "Kysymys kuuluu kilpailun ylimmälle toimitsijalle.", "say": "Kysy päätuomarilta, älä ampumapaikan tuomarilta."}, {"en": "The jury will decide this one.", "meaning": "Asia menee ampumapaikan tuomaria pidemmälle, kilpailun jurylle.", "say": "Tämän ratkaisee jury."}], "quiz": [{"q": "Kuka hyväksyy kansainvälisen Sporting™-kilpailun rataosuudet?", "options": ["Paikallinen seura", "Kansallinen liitto", "Päivän tuomari", "FITASC"], "answer": 3, "why": "Kansalliset rataosuudet hyväksyy kansallinen liitto, kansainväliset FITASC."}, {"q": "Mikä todistus päätuomarilla on oltava?", "options": ["FITASCin kansainvälinen todistus", "Seuran jäsenkortti, ei muuta", "Seuransa kansallinen valmentajalisenssi", "Ei mitään: kuka tahansa kokenut ampuja voi toimia"], "answer": 0, "why": "Ampumapaikkojen tuomarit tarvitsevat kansallisen todistuksen; päätuomari tarvitsee FITASCin kansainvälisen todistuksen."}, {"q": "Asiakas näyttää sinulle riidan aikana ClayArenan sääntötiivistelmää. Mikä sen asema on?", "options": ["Se kumoaa FITASCin virallisen tekstin", "Vain opas; FITASCin teksti on sitova", "Se on sitova, mutta vain Compak® Sporting -lajissa", "Se korvaa tuomarin ratkaisun ampumapaikalla"], "answer": 1, "why": "Tiivistelmä auttaa ymmärtämään sääntöjä, mutta tuomari ja jury soveltavat FITASCin virallista tekstiä."}]}, {"id": "sport-sporting-layout", "minutes": 5, "title": "Sporting™-rata: rataosuudet, ampumapaikat ja heittimet", "body": ["Parcours de Chasse – Sporting™ -lajissa rata jaetaan rataosuuksiin (layout). Rataosuus on ryhmä ampumapaikkoja, jotka yhdessä antavat 25 kiekkoa: 15 yksittäiskiekkoa ja 5 kaksoiskiekkoa. Järjestelmästä riippuen rataosuudella on kolme, neljä tai viisi ampumapaikkaa, kullakin omat heittimensä.", "Ampumapaikka (shooting stand) on paikka, jossa ampuja seisoo: 1 m:n neliö tai halkaisijaltaan 1 m:n ympyrä, tasainen ja liukumaton. Varo sanaa ”stand”: sanakirja tarjoaa sille merkityksiä kuten ”teline” tai ”katsomo”, mutta tässä se on aina ampumapaikka. Muu erä odottaa lähellä, riittävän lähellä seuratakseen mutta häiritsemättä koskaan ampujaa.", "Heittimet sijoitetaan maaston mukaan, usein osin pensaiden tai puiden taakse piiloon, jotta kiekot näyttävät oikealta riistalta: sivu-, vasta-, perä- ja viistokiekkoja, korkeita tai matalia, avoimessa maastossa tai puiden läpi. Ampumapaikan heittimet merkitään kirjaimin A, B, C, D vasemmalta oikealle ampumapaikalta katsottuna.", "Jokaisen ampumapaikan edessä on kiekkoluettelo (target menu): siinä luetellaan heittimet ampumajärjestyksessä ja näytetään erikoiskiekot, kuten 90 mm:n, 70 mm:n tai 60 mm:n kiekko, battue-kiekko tai jäniskiekko. Ampuja lukee sen ennen kuin astuu ampumapaikalle, ja niin sinunkin pitäisi.", "Lentoradat luokitellaan vaikeuden mukaan. Luokan A kiekon keskitason ampuja rikkoo yli 80 % kerroista, luokan B 60–80 %, luokan C 40–60 %. Luokan C kiekko on siis tarkoitettu vaikeaksi; ohilaukaus siinä ei ole katastrofi."], "key_points": ["Rataosuus antaa 25 kiekkoa: 15 yksittäiskiekkoa ja 5 kaksoiskiekkoa.", "Ampumapaikka on 1 m:n neliö tai 1 m:n ympyrä; käännä ”stand” sanalla ampumapaikka, ei ”teline”.", "Heittimet merkitään kirjaimin A, B, C, D vasemmalta oikealle ampumapaikalta katsottuna.", "Kiekkoluettelo näyttää heittimien järjestyksen ja mahdolliset erikoiskiekot.", "Vaikeusluokat: A yli 80 %, B 60–80 %, C 40–60 %."], "terms": ["layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "difficulty-class"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}], "coach_says": [{"en": "Layout three is the hard one today — lots of minis in the trees.", "meaning": "Kolmannella rataosuudella on paljon pieniä kiekkoja, jotka lentävät puiden läpi.", "say": "Rataosuus kolme on tänään se vaikea – paljon minikiekkoja puiden seassa."}, {"en": "On this stand, read the menu before you step in.", "meaning": "Tarkista ensin heittimien järjestys ja erikoiskiekot.", "say": "Tällä ampumapaikalla lue kiekkoluettelo ennen kuin astut paikalle."}, {"en": "Stand two is a class C target, don't worry about it.", "meaning": "Kiekko on luokiteltu vaikeaksi; ohilaukaus on odotettavissa.", "say": "Ampumapaikalla kaksi on C-luokan kiekko, älä murehdi sitä."}], "quiz": [{"q": "Montako kiekkoa yksi Sporting™-rataosuus antaa?", "options": ["10", "20", "25", "50"], "answer": 2, "why": "Jokainen rataosuustyyppi antaa 25 kiekkoa: 15 yksittäiskiekkoa ja 5 kaksoiskiekkoa."}, {"q": "Valmentaja sanoo ”Go to stand two.” Miten käännät sanan ”stand”?", "options": ["”ampumarata” (koko rata)", "”ampumapaikka”", "”katsomo”", "”aseteline”"], "answer": 1, "why": "Sporting™-lajissa stand on 1 m:n ampumapaikka; sanakirjamerkitykset kuten teline tai katsomo johtavat harhaan."}, {"q": "Miten Sporting™-ampumapaikan heittimet tunnistetaan?", "options": ["Numeroin 1–6 oikealta laskien", "Kuhunkin koneeseen maalatuin värein", "Kirjaimin A, B, C, D vasemmalta oikealle", "Niitä laukaisevan henkilön nimen mukaan"], "answer": 2, "why": "Kirjaimet A, B, C, D luetaan vasemmalta oikealle ampumapaikalta katsottuna, ja kiekkoluettelo ja tulospöytäkirja käyttävät niitä."}]}, {"id": "sport-compak-layout", "minutes": 5, "title": "Compak® Sporting -kenttä: viisi ampumapaikkaa, kuusi heitintä", "body": ["Compak® Sporting mahtuu yhdelle kentälle. Ampujien edessä on pakollinen suorakaide, 35–40 m leveä ja 25 m syvä, jonka neljä kulmapaalua on merkitty lipuin. Tyynessä säässä jokaisen kiekon on lennettävä sen yli jossakin vaiheessa.", "Viisi ampumapaikkaa, kukin 1 m:n neliö, ovat rivissä, ja niiden keskipisteiden väli on 2–5 m. Ne numeroidaan 1–5 vasemmalta oikealle (ampumapaikka 1, ampumapaikka 2 jne.). Jokaisella ampumapaikalla on ampumakulman rajoitin (Firing Angle Limiter), putkista tehty kehikko, joka estää asetta kääntymästä liian kauas sivulle tai ylös ja estää ampujaa astumasta eteenpäin.", "Kuudessa heittimessä, A–F vasemmalta oikealle, on kussakin kirjaimensa kyltti. Ne voivat olla edessä, sivuilla, ampujien takana tai tornissa; linjan takana olevan heittimen on oltava vähintään 4 m sen yläpuolella. Jokaisessa Compak-radassa on kolme pakollista kiekkoa: vasemmalta oikealle lentävä sivukiekko, oikealta vasemmalle lentävä sivukiekko ja peräkiekko.", "Kierros on 25 kiekkoa, viisi kultakin ampumapaikalta. Kun kuuden ampujan erä ampuu, viisi ampujaa seisoo ampumapaikoilla ja kuudes odottaa ampumapaikan 1 takana. Kukin ampuja ampuu vuorollaan ampumapaikan kiekkoluettelon viisi kiekkoa ampumapaikalta 1 alkaen. Kun ampumapaikka 5 on valmis, sen ampuja menee odottamaan ampumapaikan 1 taakse, kaikki muut siirtyvät yhden ampumapaikan oikealle, ja odottanut ampuja astuu ampumapaikalle 1.", "Joissakin kilpailuissa Compak® Sporting ammutaan sen sijaan linjassa (in line): jokainen ampuja aloittaa ampumapaikalta 1 ja lopettaa ampumapaikalle 5. Kysy järjestäjältä, kumpaa järjestelmää käytetään, koska menettely eroaa."], "key_points": ["35–40 m × 25 m:n suorakaide, jonka jokaisen kiekon on ylitettävä.", "Viisi 1 m:n ampumapaikkaa rivissä 2–5 m:n välein, kussakin ampumakulman rajoitin.", "Kuusi heitintä A–F vasemmalta oikealle; linjan takana oleva heitin on vähintään 4 m korkeassa tornissa.", "25 kiekkoa kierroksella, viisi ampumapaikkaa kohden; erä kiertää yhden ampumapaikan oikealle.", "Compak® Sporting voidaan ampua erissä tai linjassa."], "terms": ["fly-over-rectangle", "firing-angle-limiter", "shooting-stand", "trap", "tower", "rotation", "waiting-position", "line"], "sources": [{"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Everybody move one to the right. Number five, to the waiting position.", "meaning": "Erä kiertää; ampumapaikan 5 ampuja menee ampumapaikan 1 taakse.", "say": "Kaikki yksi paikka oikealle. Numero viisi, odotuspaikalle."}, {"en": "Trap E is the tower — it comes over your head.", "meaning": "Heittimen E kiekko heitetään korkeasta tornista ja kulkee pään yli.", "say": "Heitin E on torni – se tulee pääsi yli."}, {"en": "Mind the frame — don't swing past the post.", "meaning": "Kunnioita ampumakulman rajoitinta; älä vie asetta sen ohi.", "say": "Varo kehikkoa – älä heilauta tolpan ohi."}], "quiz": [{"q": "Montako heitintä ja ampumapaikkaa yhdellä Compak® Sporting -kentällä on?", "options": ["4 heitintä, 3 ampumapaikkaa", "6 heitintä, 5 ampumapaikkaa", "5 heitintä, 6 ampumapaikkaa", "8 heitintä, 8 ampumapaikkaa"], "answer": 1, "why": "Heittimet A–F ja ampumapaikat 1–5."}, {"q": "Kuuden ampujan erässä, missä kuudes ampuja on muiden ampuessa?", "options": ["Klubitalolla", "Tuomarin vieressä ampumapaikalla 5", "Heittimen F takana", "Odottamassa ampumapaikan 1 takana"], "answer": 3, "why": "Odottava ampuja seisoo ampumapaikan 1 takana ja astuu sille jokaisen kierron jälkeen."}, {"q": "Mihin ampumakulman rajoitinta tarvitaan?", "options": ["Se rajoittaa aseen liikettä ja estää astumasta eteenpäin", "Se mittaa jokaisen heitetyn kiekon nopeuden", "Se säilyttää patruunat koko kierroksen ajan", "Se lähettää kiekot ampujan pyynnöstä"], "answer": 0, "why": "Se on jokaisella ampumapaikalla oleva turvakehikko, joka rajoittaa aseen sivuttaista ja pystysuuntaista liikettä."}]}, {"id": "sport-competition-day", "minutes": 5, "title": "Kilpailupäivä alusta loppuun", "body": ["Päivä alkaa ilmoittautumisella: ampuja vahvistaa osallistumisensa, saa kilpailunumeron ja kiinnittää sen yläselkään kokonaan näkyviin. Sitten kaikki tarkistavat erälistat ja ampumisajat. Aikataulussa pysyminen on ampujan omalla vastuulla.", "Erä (squad) on enintään kuuden arvalla valitun ampujan ryhmä, joka ampuu yhdessä. ClayAwayssa sana tarkoittaa myös matkan alaryhmää, joten tee selväksi, kumpaa tarkoitat. Parcours de Chasse – Sporting™ -lajissa erä ampuu ensin ampumapaikan kaikki yksittäiskiekot ja sitten kaksoiskiekot, ja ampumajärjestys kiertää ampumapaikalta toiselle. Erän ensimmäinen ampuja näkee näytekiekot ennen kuin kukaan ampuu.", "Kierros on 25 kiekkoa: yksi rataosuus Sporting™-lajissa, yksi kenttä Compak® Sporting -lajissa. Kansainvälinen kilpailu on 200 kiekkoa, eli kahdeksan kierrosta useana päivänä. Tuomari merkitsee jokaisen kiekon tulospöytäkirjaan, yleensä X osumasta ja O ohilaukauksesta. Ampujat tarkistavat tuloksensa poistuessaan ampumapaikalta Sporting™-lajissa ja allekirjoittavat pöytäkirjan Compak® Sporting -kierroksen lopussa.", "Myöhästyminen tulee kalliiksi. Sporting™-lajissa tuomari kutsuu nimeä kolme kertaa yhden minuutin aikana; vuoronsa menettävä ampuja saa ampumatta jääneistä kiekoista nollat. Compak® Sporting -lajissa ampuja, joka saapuu sen jälkeen, kun erän ensimmäinen ampuja on pyytänyt kiekkoa, saa kierrokselta 25 nollaa.", "Jos ampujat ovat tasapisteissä kolmesta parhaasta sijasta, ammutaan uusintakierros: 25 kiekkoa, sitten sudden death. Alemmat tasatilanteet ratkaistaan Count Back -säännöllä, jossa verrataan ensin viimeistä kierrosta. Päivä päättyy tulostauluun ja palkintojenjakoon."], "key_points": ["Ilmoittautuminen, kilpailunumero selkään, erälistat ja ajat.", "Erä on enintään kuusi arvalla valittua ampujaa; Sporting™-lajissa ensin yksittäis-, sitten kaksoiskiekot, kiertävä järjestys.", "Kierros on 25 kiekkoa; kansainväliset kilpailut ovat 200 kiekkoa.", "Myöhästyminen maksaa nollia; Compak® Sporting -lajissa 25 nollaa kierrokselta.", "Kolmen parhaan tasatilanne: 25 kiekon uusinta, sitten sudden death; alemmat: Count Back."], "terms": ["entry", "competitor-number", "squad", "round", "rotation", "score-sheet", "shoot-off", "countback", "prize-giving"], "sources": [{"title": "Let's Go Shooting — NSCA beginner's guide to sporting clays", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}], "coach_says": [{"en": "You're in squad twelve, starting on layout five at nine-thirty.", "meaning": "Erän numero, aloitusrataosuus ja aloitusaika.", "say": "Olet erässä kaksitoista, aloitat rataosuudelta viisi klo 9.30."}, {"en": "Check your card before you leave the stand.", "meaning": "Varmista nyt, että tuomari kirjasi tuloksesi oikein; myöhemmin on liian myöhäistä.", "say": "Tarkista pöytäkirjasi ennen kuin lähdet ampumapaikalta."}, {"en": "Twenty-two in the first round is fine — seven more to go.", "meaning": "22/25 ensimmäisellä kierroksella; 200 kiekon kilpailussa on jäljellä seitsemän kierrosta.", "say": "Kaksikymmentäkaksi ensimmäisellä kierroksella on hyvä – seitsemän vielä jäljellä."}, {"en": "Stay close — if it's a tie, you shoot within fifteen minutes of the call.", "meaning": "Mahdolliseen uusintaan joutuvan ampujan on oltava valmiina pian kutsun jälkeen.", "say": "Pysy lähellä – jos tulee tasapisteet, ammut viidentoista minuutin kuluessa kutsusta."}], "quiz": [{"q": "Montako kiekkoa kansainvälisessä FITASCin kilpailussa on?", "options": ["50", "100", "150", "200"], "answer": 3, "why": "200 kiekkoa 25 kiekon kierroksina."}, {"q": "Erissä ammuttavassa Compak® Sporting -kilpailussa ampuja saapuu sen jälkeen, kun ensimmäinen ampuja on pyytänyt ensimmäistä kiekkoa. Mitä tapahtuu?", "options": ["Ei mitään, hän liittyy mukaan", "Hän saa kierrokselta 25 nollaa", "Hän ampuu kierroksen myöhemmin yksin ilman rangaistusta", "Hän menettää yhden kiekon"], "answer": 1, "why": "Erissä ammuttavassa Compak® Sporting -lajissa ensimmäisen pyynnön jälkeen saapunut merkitään 25 nollalla; vetoomus juryyn on mahdollinen pätevästä syystä."}, {"q": "Kaksi ampujaa on tasapisteissä 5. sijasta. Miten heidät erotetaan?", "options": ["25 kiekon uusintakierroksella", "Arpomalla kilpailun jälkeen", "Count Back -säännöllä viimeisestä kierroksesta alkaen", "Iän mukaan, nuorempi ensin"], "answer": 2, "why": "Uusintakierrokset ammutaan vain kolmesta parhaasta sijasta; sen alapuolella Count Back vertaa 8. kierrosta, sitten 7. ja niin edelleen."}]}]}, {"id": "gear", "icon": "tool", "title": "Ase ja varusteet", "intro": "Valmentajat puhuvat aseesta koko päivän: ”raise the comb”, ”check your selector”, ”change chokes”, ”nines in the bottom”. Tässä tehtävässä saat sanat aseelle, sen osille, supistajille, patruunoille ja suojavarusteille sekä ne muutamat varustesäännöt, jotka jokaisen tulkin on tiedettävä.", "lessons": [{"id": "gear-gun-types", "minutes": 5, "title": "Haulikkotyypit ja mitä säännöt sallivat", "body": ["Jokainen ampumapaikalla näkemäsi ase on sileäpiippuinen haulikko. Lähes jokaisella kilpailun ampumapaikalla se on päällekkäispiippuinen haulikko (over-and-under, O/U, puheessa ”päällekkäinen”): kaksi piippua päällekkäin, ja ase avataan ”taittamalla” se saranastaan. Kummassakin piipussa voi olla oma supistajansa, millä on merkitystä kaksoiskiekoissa.", "Rinnakkaispiippuisessa haulikossa (side-by-side, ”rinnakkainen”) on kaksi piippua vierekkäin. Se on klassinen metsästysase ja sallittu, mutta kilpailuissa harvinainen. Älä käännä over-and-under pelkäksi ”kaksipiippuiseksi”: se sana kattaa molemmat tyypit.", "Puoliautomaattihaulikossa (semi-automatic, itselataava haulikko) on yksi piippu, ja se lataa itsensä jokaisen laukauksen jälkeen ja heittää tyhjän hylsyn sivulle. FITASC sallii sen ehdoin: aseessa enintään kaksi patruunaa, lukko auki aina kannettaessa, ja Compak® Sporting -lajissa laite, joka estää poistettuja hylsyjä osumasta viereiseen ampujaan.", "Pumppuhaulikot, jotka ladataan liu'uttamalla etutukkia käsin, eivät ole sallittuja Parcours de Chasse – Sporting™- eikä Compak® Sporting -lajissa. Sääntökirjat vain toteavat kiellon antamatta syytä, joten älä keksi syytä, kun asiakas kysyy; sano vain, että se on sääntö. Compak® Sporting kieltää myös drillingit, aseet, joissa on sekä haulikon että kiväärin piippuja.", "Kaksi muuta rajaa koskee molempia lajeja: kaliiperi saa olla enintään 12 (joten kaliiperi 20 käy), ja piippujen on oltava vähintään 66 cm pitkiä. Kantohihnat, aseeseen kiinnitetyt kamerat ja kaikki keinotekoiset tähtäinlaitteet ovat kiellettyjä."], "key_points": ["Useimmat kilpailijat ampuvat päällekkäispiippuisella haulikolla.", "Puoliautomaatit ovat sallittuja: enintään kaksi patruunaa, lukko auki kannettaessa, hylsynsieppari Compak® Sporting -lajissa.", "Pumppuhaulikot on kielletty molemmissa lajeissa; säännöt eivät anna syytä.", "Kaliiperi enintään 12, piiput vähintään 66 cm, ei kantohihnoja eikä tähtäinlaitteita."], "terms": ["shotgun", "over-and-under", "side-by-side", "semi-automatic", "pump-action", "gauge", "barrel-length", "shell-catcher"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-semi-auto", "label": "18 · Semi-automatics: shell catcher and two cartridges"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}], "coach_says": [{"en": "Bring your over-and-under and a spare set of chokes.", "meaning": "Kaksipiippuinen kilpailuase ja ylimääräiset supistajat.", "say": "Ota päällekkäispiippuisesi ja varasupistajat mukaan."}, {"en": "With a semi-auto, keep the bolt open until you're on the stand.", "meaning": "Turvallisuussääntö: puoliautomaattia kannetaan lukko auki.", "say": "Puoliautomaatilla pidä lukko auki, kunnes olet ampumapaikalla."}, {"en": "No pumps on this ground.", "meaning": "Pumppuhaulikoita ei hyväksytä.", "say": "Tällä radalla ei pumppuja."}], "quiz": [{"q": "Mikä ase EI ole sallittu FITASCin Sporting™- ja Compak® Sporting -lajeissa?", "options": ["Kaliiperin 20 päällekkäispiippuinen haulikko", "Rinnakkaispiippuinen haulikko", "Pumppuhaulikko", "Puoliautomaatti kahdella patruunalla"], "answer": 2, "why": "Pumppuhaulikot on kielletty; muut ovat sallittuja, jos ne täyttävät kaliiperi- ja piippurajat."}, {"q": "Montako patruunaa puoliautomaatissa saa olla?", "options": ["Yksi", "Kaksi", "Kolme", "Niin monta kuin lippaaseen mahtuu"], "answer": 1, "why": "Molemmat sääntökirjat rajoittavat puoliautomaatin kahteen patruunaan."}, {"q": "Asiakas kysyy, miksi pumppuhaulikot on kielletty. Mikä on rehellinen vastaus?", "options": ["Säännöt toteavat kiellon selittämättä sitä", "Sääntökirjan mukaan ne ovat liian hitaita kaksoiskiekkoihin", "Sääntökirjan mukaan ne ovat vähemmän turvallisia", "Ne ovat itse asiassa sallittuja Compak® Sporting -lajissa"], "answer": 0, "why": "Sääntökirjat eivät anna syytä; tulkkina kerro sääntö äläkä keksi selityksiä."}]}, {"id": "gear-gun-parts", "minutes": 5, "title": "Aseen osat olalta piipunsuuhun", "body": ["Valmentajat nimeävät aseen osia jatkuvasti, joten opettele ne takaa eteen. Tukki (stock, puheessa myös ”perä”) asettuu olkaa vasten. Sen yläreuna, jolla poski lepää, on poskipakka (comb); ”raise the comb” tai ”drop the comb” liittyy aseen sopivuuteen. Kapea osa, josta liipaisinkäsi pitää kiinni, on pistoolikahva (grip), ja päädyn kumityyny on perälevy (recoil pad).", "Aseen metallinen keskiosa on lukonkehys (receiver tai action). Sen päällä on avausvipu (top lever): työnnä se sivuun, niin ase aukeaa. Sen takana on varmistin (safety catch), usein yhdistettynä piipunvalitsimeen (barrel selector, ”selector”), joka määrää, kumpi piippu laukeaa ensin. Alapuolella on liipaisin (trigger) liipaisinkaaren sisällä.", "Päästöliipaisin (release trigger) laukaisee, kun siitä päästetään irti, ei kun sitä painetaan. Tällaisessa aseessa on oltava varoituksena tukin ulkosivulla tarra, jossa on suuri ”R” fluoresoivalla pohjalla.", "Piippujen alla toinen käsi pitää etutukista (fore-end). Piipuissa (barrels) on takana patruunapesät (chambers) patruunoille ja edessä piipunsuut (muzzles), joihin supistajat kierretään. Päällä kulkee kisko (rib), jonka päässä on jyvä (bead). Jyvä on viitepiste, ei tähtäin: ”look at the target, not the bead” – katso kiekkoa, älä jyvää.", "Kaksi harhaanjohtavaa sanaa: rib ei ole ”kylkiluu” vaan kisko, ja ”break the gun” tarkoittaa aseen avaamista (taittamista), ei sen rikkomista. Ja yksi osiin liittyvä turvallisuussääntö: laukeamattoman patruunan tai minkä tahansa muun ase- tai patruunahäiriön jälkeen ampuja ei saa avata asetta eikä koskea varmistimeen ennen kuin tuomari on katsonut sen."], "key_points": ["Tukki, poskipakka, pistoolikahva, perälevy; lukonkehys, jossa avausvipu, varmistin ja valitsin; liipaisin.", "Etutukki, piiput patruunapesineen ja piipunsuineen, kisko ja jyvä.", "Päästöliipaisimella varustetussa aseessa on oltava ”R”-tarra tukissa.", "Rib ≠ kylkiluu; break the gun = avaa (taita) ase.", "Laukeamattoman patruunan jälkeen: älä avaa asetta tai koske varmistimeen ennen tuomarin tarkastusta."], "terms": ["stock", "comb", "grip", "recoil-pad", "receiver", "top-lever", "safety-catch", "barrel-selector", "trigger", "release-trigger", "fore-end", "barrel", "chamber", "muzzle", "rib", "bead"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-release-trigger-marking", "label": "7 · Release trigger: mandatory 'R' sticker"}, {"book": "compak", "id": "ch18-release-trigger-marking", "label": "18 · Release trigger: the 'R' sticker"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}], "coach_says": [{"en": "You're seeing too much rib — your head is up.", "meaning": "Silmä on liian korkealla kiskon yläpuolella, yleensä siksi, että pää nousee poskipakalta.", "say": "Näet liikaa kiskoa – pääsi on ylhäällä."}, {"en": "Check your selector — you fired the top barrel first.", "meaning": "Piipunvalitsin on väärin päin.", "say": "Tarkista valitsin – ammuit ylemmällä piipulla ensin."}, {"en": "Break your gun and show me it's clear.", "meaning": "Avaa ase ja näytä tyhjät patruunapesät.", "say": "Taita ase ja näytä, että se on tyhjä."}, {"en": "Forget the bead — look at the target.", "meaning": "Keskity kiekkoon, älä piipun päähän.", "say": "Unohda jyvä – katso kiekkoa."}], "quiz": [{"q": "Valmentaja sanoo ”Raise the comb”. Mitä osaa hän tarkoittaa?", "options": ["Tukin yläosaa, jolla poski lepää", "Pientä jyvää kiskon päässä", "Liipaisimen ympärillä olevaa kaarta", "Piipunsuun supistajaa"], "answer": 0, "why": "Poskipakka on tukin yläosa; sen nostaminen nostaa silmää kiskon yläpuolelle."}, {"q": "Mitä päästöliipaisimella varustetussa aseessa on oltava?", "options": ["Punaiseksi maalattu piippu muiden varoittamiseksi", "Suuri ”R”-tarra tukissa", "Toinen, erillinen varmistin", "Ei mitään: merkintää ei vaadita"], "answer": 1, "why": "Molemmat sääntökirjat vaativat ”R”-varoitustarran fluoresoivalla pohjalla tukin ulkosivulla."}, {"q": "Miten käännät ”Break your gun”?", "options": ["”Riko aseesi”", "”Pura ase osiin”", "”Avaa (taita) ase”", "”Puhdista aseen piiput”"], "answer": 2, "why": "Ampumaradalla ”break” tarkoittaa aseen avaamista saranastaan, jotta se ei voi laueta."}]}, {"id": "gear-chokes", "minutes": 5, "title": "Supistajat: mitä ne tekevät ja miten valmentajat puhuvat niistä", "body": ["Supistus (choke) on piipun lievä kaventuma piipunsuulla. Se säätelee, kuinka nopeasti hauliparvi leviää. Suurempi supistus pitää haulit koossa pidempään ja antaa tiiviimmän osumakuvion kaukaisille kiekoille; pienempi supistus levittää ne aikaisemmin ja antaa leveämmän, anteeksiantavamman osumakuvion läheisille kiekoille.", "Useimmissa kilpailuaseissa on vaihtosupistajat: lyhyitä putkia, jotka kierretään piipunsuuhun supistaja-avaimella. Vanhemmissa aseissa voi olla piippuun koneistettu kiinteä supistus. Eri valmistajien supistajat eivät usein sovi toisiinsa, ja valmistajat varoittavat, ettei vaihtosupistaja-asetta saa koskaan ampua ilman supistajia.", "Nimet tulevat englannista, avoimimmasta tiukimpaan: cylinder, skeet, improved cylinder, light modified, modified, improved modified, full. Eurooppalaiset sanovat ne usein murtolukuina: neljännes (1/4, improved cylinder), puolikas (1/2, modified), kolme neljäsosaa (3/4, improved modified) ja täysi (1/1, full). Monissa italialaisissa aseissa supistajat merkitään tähdillä, ja siellä sääntö on päinvastainen: enemmän tähtiä tarkoittaa avoimempaa supistusta.", "Valmentajat sanovat esimerkiksi ”quarter and half”, ”open up the bottom barrel”, ”go tighter in the top” tai ”change chokes for this stand”. Säilytä nimet täsmälleen niin kuin valmentaja ne sanoo; älä muunna niitä millimetreiksi, jotka vaihtelevat valmistajittain.", "Säännöt eroavat lajeittain. Parcours de Chasse – Sporting™ -lajissa supistajia saa vaihtaa ampumapaikkojen välillä tai yksittäis- ja kaksoiskiekkojen välillä, jos se ei aiheuta viivytystä, mutta ei koskaan sen jälkeen, kun ampuja on astunut ampumapaikalle. Compak® Sporting -lajissa asetta, piippuja ja supistajia ei saa vaihtaa kierroksen aikana lainkaan, vain kierrosten välillä, paitsi rikkoutumisen jälkeen."], "key_points": ["Supistus kaventaa piipunsuuta: tiukempi kaukaisille kiekoille, avoimempi läheisille.", "Vaihtosupistajat kierretään supistaja-avaimella; valmistajat varoittavat ampumasta ilman niitä.", "Murtoluvut: neljännes = improved cylinder, puolikas = modified, kolme neljäsosaa = improved modified, täysi = full.", "Säilytä supistajien nimet sellaisinaan; älä muunna millimetreiksi.", "Sporting™: vaihto ampumapaikkojen välillä, ei koskaan ampumapaikalla; Compak®: ei vaihtoa kierroksen aikana."], "terms": ["choke", "multichoke", "fixed-choke", "choke-key", "cylinder", "skeet-choke", "improved-cylinder", "modified", "improved-modified", "full-choke", "pattern"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Beretta — Choke tubes identification", "url": "https://estore.beretta.com/en-gb/utility/choke-tubes-identification"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}], "coach_says": [{"en": "What chokes are you using? — Quarter and half.", "meaning": "Toisessa piipussa improved cylinder, toisessa modified.", "say": "Mitkä supistajat sinulla on? – Neljännes ja puolikas."}, {"en": "Put quarter in the bottom and half in the top — the second bird is longer.", "meaning": "Avoimempi supistus ensimmäiselle, lähemmälle kiekolle; tiukempi toiselle, kauemmalle.", "say": "Laita neljännes alempaan ja puolikas ylempään – toinen kiekko on kauempana."}, {"en": "Open up — these are all close.", "meaning": "Vaihda avoimemmat supistajat, koska kiekot ovat lähellä.", "say": "Avaa supistusta – nämä ovat kaikki lähellä."}, {"en": "Check your tubes are tight before the round.", "meaning": "Varmista, etteivät supistajat ole löystyneet.", "say": "Tarkista ennen kierrosta, että supistajat ovat kireällä."}], "quiz": [{"q": "Mikä supistus antaa leveimmän osumakuvion?", "options": ["Täysi (full)", "3/4-suppea (improved modified)", "Puolisuppea (modified)", "Sylinteri (cylinder)"], "answer": 3, "why": "Sylinterissä ei ole supistusta, joten haulit leviävät aikaisimmin."}, {"q": "Sporting™-lajissa jo ampumapaikalla seisova ampuja haluaa vaihtaa supistajan. Onko se sallittua?", "options": ["Kyllä, kunhan se ei aiheuta viivytystä", "Ei, ei enää kun hän on ampumapaikalla", "Kyllä, mutta vain ennen kaksoiskiekkoja", "Vain juryn luvalla"], "answer": 1, "why": "Vaihdot ovat sallittuja ampumapaikkojen välillä tai yksittäis- ja kaksoiskiekkojen välillä ilman viivytystä, mutta ei koskaan sen jälkeen, kun ampuja on astunut ampumapaikalle."}, {"q": "Italialaisessa aseessa viiden tähden supistaja on…", "options": ["avoimin", "tiukin", "rikkinäinen supistaja", "kiväärin piippu"], "answer": 0, "why": "Tähtimerkinnöissä useampi tähti tarkoittaa avoimempaa supistusta."}]}, {"id": "gear-cartridges", "minutes": 5, "title": "Patruunat: kaliiperi, haulikoko ja rajat", "body": ["Patruuna (cartridge) sisältää kaiken yhteen laukaukseen: hylsyn (hull) metallisine pohjineen, nallin (primer), ruudin (powder), välitulpan (wad) ja haulit (shot). Ampujat sanovat myös shell. ”Empties” ovat ammuttuja hylsyjä.", "Kaliiperi (gauge) lasketaan vanhalla tavalla: mitä pienempi luku, sitä leveämpi piippu, joten kaliiperi 12 on leveämpi kuin 20. FITASC sallii enintään kaliiperin 12 aseet, ja useimmat ampujat käyttävät kaliiperia 12. Älä koskaan käännä ”12 gauge” muotoon ”12 mm”.", "Haulikokokin on ”väärinpäin”: mitä suurempi numero, sitä pienempi hauli, joten nro 9 on hienompi kuin nro 7½. Sama numero voi tarkoittaa hieman eri kokoa Britanniassa, Manner-Euroopassa ja Yhdysvalloissa, joten sano numero sellaisenaan ja tarkista millimetrit pakkauksesta. ”Nines” ja ”seven-and-a-halfs” ovat valmentajien yleisiä sanoja.", "Parcours de Chasse – Sporting™- ja Compak® Sporting -lajien säännöt ovat samat: enintään 28 g lyijyhauleja +2 %:n toleranssilla; pyöreät haulit 2,0–2,5 mm (±0,1 mm). Jälleenladatut patruunat, hajottimet, sekahaulikoot, mustaruuti ja valojuovat ovat kiellettyjä. Sporting™-lajissa tuomari voi ottaa tarkastettavaksi kaksi patruunaa, yhden kummastakin liivin taskusta; Compak® Sporting -lajissa sääntöjen vastaisilla patruunoilla ennen tarkastusta ammutut laukaukset lasketaan nolliksi.", "Jotkin radat lisäävät harjoituksiin omia ympäristösääntöjään, esimerkiksi vain huopatulpat tai vain teräshaulit: tarkista radan säännöt ennen matkaa. Tyhjät hylsyt laitetaan ampumapaikan astiaan, ja puoliautomaatilla ampuvat keräävät poistuessaan aseensa heittämät hylsyt."], "key_points": ["Patruuna = hylsy, nalli, ruuti, välitulppa, haulit.", "Kaliiperi: pienempi luku, leveämpi piippu; FITASCin enimmäiskaliiperi on 12.", "Haulikoko: suurempi numero, pienempi hauli; numerointi vaihtelee maittain, tarkista millimetrit.", "Rajat: 28 g lyijyä (+2 %), haulit 2,0–2,5 mm; ei jälleenlatauksia, sekahauleja, mustaruutia eikä valojuovia.", "Hylsyt astiaan; puoliautomaatin käyttäjät keräävät hylsynsä."], "terms": ["cartridge", "hull", "primer", "powder", "wad", "shot-size", "load-weight", "gauge", "lead-shot", "steel-shot", "empties"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}, {"book": "compak", "id": "ch18-cartridge-bans", "label": "18 · Prohibited ammunition"}, {"book": "sporting", "id": "ch7-cartridge-check", "label": "7 · Cartridge checks by the referee"}, {"book": "compak", "id": "ch23-noncompliant-equipment", "label": "23 · Shots with non-compliant guns or ammunition"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "compak", "id": "ch18-empty-cases", "label": "18 · Disposing of empty cases"}], "coach_says": [{"en": "Nines for the close stuff, seven-and-a-halfs for the long crossers.", "meaning": "Hienompaa nro 9:n haulia läheisille kiekoille, isompaa nro 7½:n haulia kaukaisille sivukiekoille.", "say": "Ysejä lähikiekkoihin, seitsemän ja puolta pitkiin sivukiekkoihin."}, {"en": "Maximum twenty-eight grams on this shoot.", "meaning": "Kilpailun haulilatauksen raja, kuten FITASCin säännöissä.", "say": "Tässä kilpailussa enintään kaksikymmentäkahdeksan grammaa."}, {"en": "Empties in the bin, please, not on the grass.", "meaning": "Laita ammutut hylsyt astiaan.", "say": "Hylsyt astiaan, kiitos, ei nurmikolle."}, {"en": "Steel only on this ground.", "meaning": "Lyijyhaulit eivät ole sallittuja tällä radalla (radan oma sääntö, ei FITASCin).", "say": "Tällä radalla vain teräshauleja."}], "quiz": [{"q": "Mikä on hienointa haulia?", "options": ["Nro 7", "Nro 7½", "Nro 8", "Nro 9"], "answer": 3, "why": "Mitä suurempi haulinumero, sitä pienempi hauli."}, {"q": "Mikä on suurin sallittu haulilataus FITASCin säännöissä?", "options": ["24 g ilman toleranssia", "28 g, toleranssi +2 %", "32 g vain kaukaisille kiekoille", "Ei rajaa, mikä tahansa lataus on sallittu"], "answer": 1, "why": "Molemmat lajit sallivat enintään 28 g lyijyhauleja, +2 %."}, {"q": "Asiakas sanoo aseensa olevan ”12 gauge”. Mitä se tarkoittaa?", "options": ["Piipun kokoa: leveämpi kuin kaliiperi 20", "Piipun halkaisija on 12 millimetriä", "Lippaaseen mahtuu kaksitoista patruunaa", "Piiput ovat 12 tuumaa pitkät"], "answer": 0, "why": "Kaliiperi on vanha yksikkö: mitä pienempi luku, sitä leveämpi piippu. Se ei ole millimetrejä."}]}, {"id": "gear-protection-clothes", "minutes": 5, "title": "Suojaimet, liivi ja pukeutumissäännöt", "body": ["Kuulosuojaimet ovat pakolliset kaikille rataosuudella tai sen lähellä oleville: ampujille, tuomareille, henkilökunnalle ja katsojille, ja se koskee myös sinua. Sekä korvatulpat (earplugs) että kuulosuojaimet (ear muffs) käyvät; aktiivikuulosuojaimet vahvistavat puhetta ja vaimentavat pamauksen, mikä auttaa kuulemaan valmentajaa ja tuomaria. Ampuja, joka tulee ampumapaikalle ilman suojaimia, katsotaan poissaolevaksi.", "Ampumalasit (safety glasses) ovat myös pakolliset ampujille, tuomareille ja henkilökunnalle, ja Parcours de Chasse – Sporting™ -lajissa kaikille ampumapaikan lähellä oleville. Linssejä on eri värisinä (keltainen, oranssi, violetti, savunharmaa), jotta kiekot erottuvat erilaisessa valossa.", "Ampumaliivissä (shooting vest) on patruunoille kaksi etutaskua ja olkapehmuste. Sporting™-lajia varten siinä on kontrastivärinen vaakaviiva 25 cm olkapäiden linjan alapuolella: ennen kiekon pyytämistä tukin yläreunan on pysyttävä sen alapuolella, ja tuomari valvoo tätä. Compak® Sporting -lajissa tällaista viivaa ei ole, koska aseen asento kiekkoa pyydettäessä on vapaa.", "Pukeutumissäännöt ovat molemmissa lajeissa samat: ei lyhyitä shortseja (vain pitkät shortsit, jotka päättyvät enintään 5 cm polven yläpuolelle), paidoissa vähintään lyhyet hihat, ei liiviä paljaan rinnan päällä eikä sandaaleja turvallisuussyistä. Kilpailunumero pidetään selässä kokonaan näkyvissä. Rikkeestä seuraa ensin varoitus, sitten muita rangaistuksia.", "Monet ampujat käyttävät myös lippalakkia auringolta ja sateelta suojaksi, käsineitä, ja kantavat patruunalaukkua päivän tarpeiksi. Nämä ovat tapoja, eivät sääntöjä."], "key_points": ["Kuulosuojaimet ovat pakolliset kaikille rataosuuden lähellä, myös tulkeille.", "Ampumalasit ovat pakolliset; ilman suojaimia ampuja katsotaan poissaolevaksi.", "Sporting™-liivi: kontrastiviiva 25 cm olkapäiden linjan alapuolella; Compak®-lajissa ei viivaa.", "Pukeutuminen: shortsit enintään 5 cm polven yläpuolelle, hihat, ei paljasta rintaa liivin alla, ei sandaaleja.", "Kilpailunumero selässä kokonaan näkyvissä."], "terms": ["hearing-protection", "earplugs", "electronic-ear-muffs", "safety-glasses", "shooting-vest", "jacket-line", "dress-code", "competitor-number", "cartridge-bag"], "sources": [], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}], "coach_says": [{"en": "Ears and eyes on before you walk up.", "meaning": "Laita kuulosuojaimet ja lasit ennen kuin menet ampumapaikalle.", "say": "Kuulosuojaimet ja lasit päähän ennen kuin menet paikalle."}, {"en": "Butt under the tape until you see the target.", "meaning": "Sporting™-lajin ase alhaalla -sääntö: tukki pysyy liivin merkkiviivan alapuolella, kunnes kiekko ilmestyy.", "say": "Perä nauhan alapuolella, kunnes näet kiekon."}, {"en": "No marker needed here — it's Compak.", "meaning": "Compak®-lajissa ei ole liivin merkkiviivaa koskevaa vaatimusta.", "say": "Merkkiä ei tarvita täällä – tämä on Compak."}], "quiz": [{"q": "Olet tulkkina ampumapaikan lähellä. Onko sinun käytettävä kuulosuojaimia?", "options": ["Ei, vain ampumapaikalla olevien ampujien", "Vain finaaleissa ja uusintakierroksilla", "Kyllä, kaikkien rataosuudella tai sen lähellä olevien", "Vain jos tuomari pyytää"], "answer": 2, "why": "Kuulosuojaimet ovat pakolliset ampujille, tuomareille, henkilökunnalle ja katsojille."}, {"q": "Missä liivin merkkiviiva on Sporting™-lajissa?", "options": ["25 cm olkapäiden linjan alapuolella", "Vyötäröllä, vyön kohdalla", "Ampumakäden hihassa", "Sporting™-lajissa sitä ei ole"], "answer": 0, "why": "Kontrastiviiva on 25 cm olkapäiden linjan alapuolella ja sen suuntainen; tukin on pysyttävä sen alapuolella, kunnes kiekko ilmestyy."}, {"q": "Mitkä jalkineet on kielletty molemmissa lajeissa?", "options": ["Maastojuoksukengät", "Sandaalit", "Saappaat", "Lenkkarit"], "answer": 1, "why": "Sandaalit on kielletty turvallisuussyistä."}]}]}, {"id": "targets", "icon": "target", "title": "Kiekot", "intro": "Valmentaja, joka sanoo ”it's a midi off the tower, then a rabbit on report”, olettaa sinun pystyvän kuvittelemaan sen. Tässä tehtävässä opit kiekkotyypit, miten väri ja valo muuttavat ampujan näkemää, miten heittimet lähettävät kiekot, miten kiekkoluetteloa luetaan ja sen yhden pisteytyskysymyksen, joka ratkaisee kaiken: osuma vai ohi.", "lessons": [{"id": "targets-types", "minutes": 5, "title": "Kiekkotyypit: tavallinen, midi, mini, battue, jänis, pöly, ZZ", "body": ["FITASCin Parcours de Chasse – Sporting™ -lajin luettelo nimeää seitsemän kiekkotyyppiä: tavallinen (standard), midi, super mini, battue, jäniskiekko (rabbit), pölykiekko (flash) ja ZZ. Compak® Sporting sallii minkä tahansa tavallisen tai erikoiskiekon, ja sen luettelossa mainitaan myös rocket-kiekko. Jokainen tyyppi lentää eri tavalla.", "Tavallinen kiekko, yleisin kiekko, on kupumainen ja halkaisijaltaan noin 108–110 mm. Midikiekko on 90 mm: se säilyttää nopeutensa hyvin ja näyttää olevan kauempana kuin onkaan. Minikiekko on 60 mm: se lähtee heittimestä nopeasti ja hidastuu nopeasti, joten ampujat antavat sille helposti liikaa ennakkoa. Sporting™-luettelo kutsuu pientä kiekkoa nimellä ”super mini”, ja kiekkoluettelosääntö mainitsee sekä 70 mm:n että 60 mm:n koot; nimiä ei käytetä johdonmukaisesti, joten luota aina kiekkoluetteloon kirjoitettuihin millimetreihin.", "Battue-kiekko on litteä, ohut 110 mm:n kiekko. Se lentää syrjä edellä, lähes näkymättömänä, kääntyy sitten näyttämään pintansa ja putoaa nopeasti. Jäniskiekko on 110 mm:n kiekko, jossa on paksu, vahva reuna, ja se vieritetään syrjällään maata pitkin; se pomppii ja voi hypätä kohoumien yli. Suomeksi puhutaan jäniskiekosta; tällä kurssilla käytetään sanaa jäniskiekko.", "Pölykiekko (flash) on täytetty värillisellä jauheella, joka jättää osuman jälkeen kirkkaan pilven; se pisteytetään kuten mikä tahansa muu kiekko. ZZ-kiekko, jota kutsutaan myös nimellä helice, on muovinen potkuri, jossa on valkoinen keskikupu ja joka lentää arvaamattomasti. Rocket-kiekko on erikoiskiekko, joka mainitaan vain Compak® Sporting -luettelossa; emme anna sille teknisiä tietoja.", "Sporting™-lajissa väärän värinen, kokoinen tai tyyppinen kiekko on No Bird (uusi kiekko) ja uusitaan."], "key_points": ["Sporting™-luettelo: tavallinen, midi, super mini, battue, jänis, pöly, ZZ; Compak® sallii minkä tahansa tyypin, myös rocketin.", "Tavallinen noin 108–110 mm, midi 90 mm, mini 60 mm; kiekkoluettelossa voi näkyä myös 70 mm – luota millimetreihin.", "Battue: litteä, syrjä edellä, kääntyy ja putoaa; jäniskiekko: paksu reuna, vierii ja pomppii.", "Pölykiekko jättää jauhepilven; ZZ on potkurikiekko.", "Sporting™: väärä väri, koko tai tyyppi = No Bird."], "terms": ["standard-target", "midi", "mini", "super-mini", "battue", "rabbit", "flash-target", "zz-target", "rocket-target", "no-bird"], "sources": [{"title": "Shooting UK — Clay pigeon sizes: knowing what they are will help you improve your score", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}, {"title": "Let's Go Shooting — Types of clay targets", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/types-of-clay-targets/"}, {"title": "GUNS Magazine — Helice", "url": "https://gunsmagazine.com/discover/helice/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}], "coach_says": [{"en": "The midi looks far but it isn't — don't give it too much.", "meaning": "90 mm:n kiekko näyttää olevan kauempana kuin onkaan, joten se tarvitsee vähemmän ennakkoa kuin ampuja luulee.", "say": "Midi näyttää kaukaiselta, mutta ei ole – älä anna sille liikaa."}, {"en": "The battue will turn and drop at the end — take it when it shows its belly.", "meaning": "Ammu battue-kiekko, kun se kääntää litteän pintansa sinua kohti.", "say": "Battue kääntyy ja putoaa lopussa – ota se, kun se näyttää vatsansa."}, {"en": "The mini is dying fast — shoot it early.", "meaning": "Pieni kiekko menettää nopeuttaan nopeasti; älä odota.", "say": "Mini hiipuu nopeasti – ammu se aikaisin."}, {"en": "The rabbit will hop on that bump — stay under it.", "meaning": "Pidä piipunsuut matalalla vierivän kiekon kohdalla, jotta pomppukin osuu hauliparveen.", "say": "Jänis pomppaa tuosta kohoumasta – pysy sen alla."}], "quiz": [{"q": "Mikä kiekko vierii maata pitkin?", "options": ["Midikiekko", "Battue-kiekko", "Jäniskiekko", "Pölykiekko"], "answer": 2, "why": "Jäniskiekossa on paksu reuna, ja se heitetään syrjällään maata pitkin."}, {"q": "Kiekkoluettelossa lukee ”70 mm”. Valmentaja kutsuu sitä miniksi. Mitä sinun pitäisi kääntää?", "options": ["Korjata se 60 mm:ksi, koska mini on 60 mm", "Säilyttää valmentajan sana ja kiekkoluettelon 70 mm", "Kutsua sitä midiksi, koska se on yli 60 mm", "Pyytää valmentajaa sanomaan sen sijaan ”super mini”"], "answer": 1, "why": "Säännöt mainitsevat 70 mm:n ja 60 mm:n koot sekä nimen ”super mini”; luota kiekkoluettelon millimetreihin äläkä korjaa valmentajaa."}, {"q": "Sporting™-ampumapaikalla heitin heittää midikiekon kiekkoluettelossa näytetyn tavallisen kiekon sijaan. Mitä tapahtuu?", "options": ["No Bird, kiekko uusitaan", "Se lasketaan osumaksi", "Ampuja menettää kiekon", "Kierros mitätöidään"], "answer": 0, "why": "Sporting™-lajissa väärän värinen, kokoinen tai tyyppinen kiekko on No Bird ja uusitaan."}]}, {"id": "targets-colours-visibility", "minutes": 5, "title": "Värit, valo ja näkyvyys", "body": ["Molemmat sääntökirjat vaativat saman: kiekon värin on erotuttava selvästi taustasta. Kaksivärisiä kiekkoja ei suositella. Väri on siis radan rakentajan valinta, joka tehdään jokaiselle lentoradalle, ei erillinen kiekkotyyppi.", "Kuulet mustista, oransseista, valkoisista, keltaisista ja vaaleanpunaisista kiekoista. Monet radan rakentajat käyttävät mustaa taivasta vasten ja oranssia puita ja nurmikkoa vasten. ”Blazed”-kiekossa on kirkkaan oranssiksi maalattu kupu. Varo: kun valmentaja sanoo ”the orange one”, hän tarkoittaa väriä, ei kokoa. Musta midikiekko ja oranssi tavallinen kiekko voivat tulla samalta ampumapaikalta.", "Jos heitetään väärän värinen kiekko, tuomari ilmoittaa No Bird, ja kiekko uusitaan. Compak® Sporting -säännöt lisäävät, että huono sää ei ole koskaan syy No Birdiin: rikottu kiekko lasketaan ja ohi ammuttu on menetetty olosuhteista riippumatta. Parcours de Chasse – Sporting™ -lajissa tuomari voi keskeyttää ammunnan lyhyen, rajun myrskyn tai rankkasateen ajaksi.", "Valo muuttaa kaiken. Valmentajat puhuvat vastavalosta (aurinko kiekon takana), latteasta valosta harmaina päivinä, varjoista puiden alla ja kiekon takana olevasta taustasta: taivas, puurivi tai maa. Kiekko voi ”kadota” tummia puita vasten ja ”ponnahtaa esiin” taivasta vasten. Siksi ampujat vaihtavat linssien väriä päivän mittaan.", "Kun käännät, pidä väri- ja valosanat tarkkoina ja lyhyinä: ”it's coming out of the dark trees” (se tulee tummien puiden edestä), ”you lose it in the sun” (kadotat sen aurinkoon). Ne selittävät, miksi ampuja ampui ohi, joten niillä on merkitystä."], "key_points": ["Kiekon värin on erotuttava taustasta; kaksivärisiä kiekkoja ei suositella.", "Väri ei ole tyyppi: ”the orange one” on väri, ei koko.", "Väärä väri = No Bird.", "Compak®: huono sää ei koskaan oikeuta No Birdiin; Sporting™-tuomarit voivat keskeyttää lyhyen myrskyn ajaksi.", "Vastavalo, latea valo, tausta: käännä valosanat tarkasti."], "terms": ["target", "no-bird", "blazed-target", "background"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch20-bad-weather", "label": "20 · No NO BIRD for bad weather"}, {"book": "sporting", "id": "ch5-weather-interruption", "label": "5 · Interrupting shooting for bad weather"}], "coach_says": [{"en": "The black one is the midi, the orange one is the standard — don't mix them up.", "meaning": "Ampumapaikan kaksi kiekkoa eroavat väriltään ja kooltaan.", "say": "Musta on midi, oranssi on tavallinen – älä sekoita niitä."}, {"en": "You lose it against the trees — pick it up later, in the sky.", "meaning": "Kiekkoa on vaikea nähdä puiden edessä; aloita seuraaminen siitä, missä sen takana on taivas.", "say": "Kadotat sen puita vasten – ota se myöhemmin, taivasta vasten."}, {"en": "Flat light today — put the yellow lens in.", "meaning": "Harmaa, kontrastiton valo; keltainen linssi parantaa kontrastia.", "say": "Tänään latea valo – vaihda keltainen linssi."}], "quiz": [{"q": "Mitä säännöt vaativat kiekon väriltä?", "options": ["Sen on oltava aina oranssi", "Sen on erotuttava selvästi taustasta", "Sen on oltava kaksivärinen", "Mikä tahansa väri: säännöt eivät sano mitään"], "answer": 1, "why": "Vaatimus on näkyvyys taustaa vasten; kaksivärisiä kiekkoja ei suositella."}, {"q": "Compak® Sporting -lajissa alkaa sataa rankasti, ja ampuja ampuu ohi. Voiko hän pyytää säästä johtuvaa No Birdiä?", "options": ["Kyllä, sää oikeuttaa siihen aina", "Vain kaksoiskiekon ensimmäisessä kiekossa", "Vain jos jury suostuu siihen", "Ei, sää ei koskaan oikeuta No Birdiin"], "answer": 3, "why": "Compak® Sporting -säännöt toteavat, että sää ei ole koskaan syy No Birdiin."}, {"q": "Valmentaja sanoo ”Watch the orange one.” Mitä hän kuvaa?", "options": ["Kiekon väriä", "90 mm:n kiekkokokoa", "Jäniskiekkoa", "Rikkoutunutta kiekkoa"], "answer": 0, "why": "Väri valitaan näkyvyyden mukaan, eikä se kerro mitään koosta tai tyypistä."}]}, {"id": "targets-traps", "minutes": 5, "title": "Heittimet, kiekon lähetys ja heittäjä", "body": ["Heitin (trap) on kone, joka heittää kiekot. Heittimet voivat olla käsikäyttöisiä tai automaattisia (Compak® Sporting -säännöt mainitsevat myös puoliautomaattiset). Parcours de Chasse – Sporting™ -lajissa ampumapaikan heittimet merkitään kirjaimin A, B, C, D vasemmalta oikealle ampumapaikalta katsottuna; Compak® Sporting -lajissa kuusi heitintä ovat A–F, kussakin kirjainkyltti. Säilytä latinalaiset kirjaimet kääntäessäsi: kiekkoluettelo käyttää niitä.", "Ampuja lähettää kiekon pyynnöllä: säännöt mainitsevat sanat ”pull” tai ”ready”, vaikka käytännössä ampujien pyyntösanat vaihtelevat. Sporting™-lajissa tuomari välittää käskyn heittäjälle (heitinten operaattori, kiekon laukaisija) äänimerkillä, ja kiekon on lähdettävä kolmen sekunnin kuluessa. Älä käännä itse pyyntösanaa: se on käsky koneelle, ei lause.", "Compak® Sporting -lajissa kiekot voidaan lähettää käsin, kauko-ohjaimella tai äänellä toimivalla mikrofonilähdöllä (sonopull). Käsilähdössä kiekko lähtee 0–3 sekuntia pyynnön jälkeen; mikrofonilähdössä on kiinteä 0,5 sekunnin viive. Kansainvälisessä in-line Compak® Sporting -kilpailussa käytetään vain mikrofonilähtöä ja elektronista tuomarointia.", "Äänilähdössä ampumapaikalla on mikrofoni. Oma äänesi voi laukaista sen. Tällaisella ampumapaikalla älä koskaan puhu ääneen, kun ampuja on valmiina: kuiskaa kiekkojen välillä tai astu taaksepäin.", "Heitinvirheet ovat No Birdejä: kiekko, joka lähtee yli kolme sekuntia pyynnön jälkeen, kiekko väärästä heittimestä, ilman pyyntöä heitetty kiekko, Sporting™-lajissa kaksi kiekkoa saman ampumapaikan heittimistä, tai saman Compak-radan koneen vahingossa heittämä kiekko."], "key_points": ["Heittimet: A–D Sporting™-ampumapaikkaa kohden, A–F Compak®-kentällä; säilytä latinalaiset kirjaimet.", "Pyyntö (”pull”, ”ready”) lähettää kiekon; älä käännä sitä.", "Sporting™: tuomari antaa heittäjälle merkin; kiekko 3 sekunnin kuluessa.", "Compak®: käsin 0–3 s, kauko-ohjain tai mikrofonilähtö kiinteällä 0,5 s:n viiveellä.", "Myöhäiset, väärästä heittimestä tulevat tai pyytämättömät kiekot ovat No Birdejä; mikrofoni voi kuulla sinut."], "terms": ["trap", "trapper", "call", "sonopull", "manual-release", "tower", "no-bird"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch16-terms", "label": "16 · Other basic terms"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Trap B is throwing lower than in the showing — tell the referee.", "meaning": "Koneen lentorata on muuttunut; ampujan pitäisi ilmoittaa siitä ennen ampumista.", "say": "Heitin B heittää matalammalta kuin näytössä – kerro tuomarille."}, {"en": "It's voice release here — don't chat on the stand.", "meaning": "Mikrofoni lähettää kiekot; puhuminen voi laukaista kiekon.", "say": "Täällä on äänilähtö – älä juttele ampumapaikalla."}, {"en": "The trapper was late on that one — that's a no bird.", "meaning": "Kiekko lähti yli kolme sekuntia pyynnön jälkeen.", "say": "Heittäjä oli myöhässä tuossa – se on no bird."}], "quiz": [{"q": "Kuinka kauan Sporting™-lajissa kiekon lähtö saa kestää tuomarin merkistä?", "options": ["Enintään 1 sekunnin", "Enintään 3 sekuntia", "Enintään 10 sekuntia", "Kuinka kauan tahansa"], "answer": 1, "why": "Yli kolme sekuntia myöhemmin lähtevä kiekko on No Bird."}, {"q": "Mikä on Compak®-lajin mikrofonilähdön kiinteä viive?", "options": ["0 sekuntia", "3 sekuntia", "0,5 sekuntia", "Kukin ampuja säätää sen itse"], "answer": 2, "why": "Mikrofonilähdön on käytettävä kiinteää, muuttumatonta 0,5 sekunnin viivettä."}, {"q": "Olet ampumapaikalla, jossa on äänilähtö, ja ampuja on valmiina. Mitä teet?", "options": ["Käännän kovaa, jotta hän kuulee minut", "Pyydän heittäjää odottamaan hetken", "Toistan pyyntösanan hänen puolestaan", "Olen hiljaa; kuiskaan vain kiekkojen välillä"], "answer": 3, "why": "Äänesi voi laukaista mikrofonin ja lähettää kiekon, jota kukaan ei pyytänyt."}]}, {"id": "targets-menu", "minutes": 5, "title": "Kiekkoluettelon lukeminen", "body": ["Kiekkoluettelo (target menu) on ampumapaikan taulu, joka kertoo ampujalle, mitä on tulossa. Ampujat sanovat todella ”menu” (myös ”luettelo” tai ”taulu”), joten voit käyttää näitä sanoja.", "Parcours de Chasse – Sporting™ -lajissa kiekkoluettelo luettelee heittimet ampumajärjestyksessä, ja siinä on näytettävä mahdolliset erikoiskiekot: 90 mm, 70 mm, 60 mm, battue tai jäniskiekko. Tuomarit tarkistavat etukäteen, että koneet vastaavat kiekkoluetteloa. Rataosuus antaa 15 yksittäiskiekkoa ja 5 kaksoiskiekkoa, ja kaksoiskiekoissa saa käyttää vain kiekkoja, jotka on jo näytetty yksittäiskiekkoina samalta ampumapaikalta. Erä ampuu ensin yksittäiskiekot ja sitten kaksoiskiekot.", "Kaksoiskiekko merkitään sen tyypillä: laukauksesta lähtevä (on report, toinen kiekko lähtee ensimmäisen laukauksen äänestä), yhtäaikainen (simultaneous, molemmat yhdessä) tai rafale (kaksi samasta heittimestä peräkkäin; vain Sporting™). Kiekkoluettelot näyttävät erilaisilta radasta riippuen, joten lue sanat, älä pelkkiä kirjaimia. Esimerkki kolmen heittimen ampumapaikalta: yksittäiskiekot A, B, C; kaksoiskiekot A + B yhtäaikainen ja C + C rafale (tällaisella ampumapaikalla kaksi laukauksesta lähtevää kaksoiskiekkoa ei ole sallittu).", "Compak® Sporting -lajissa kiekkoluettelo on nähtävillä jokaisella viidellä ampumapaikalla. Jokaisella ampumapaikalla on viisi kiekkoa: viisi yksittäiskiekkoa, kolme yksittäiskiekkoa ja yksi kaksoiskiekko tai yksi yksittäiskiekko ja kaksi kaksoiskiekkoa. Kaksoiskiekon tyyppi on sama Compak-radan kaikilla viidellä ampumapaikalla, ja jokaisen kaksoiskiekon ensimmäinen kiekko on edellisen ampumapaikan viimeinen kiekko. FITASC tarjoaa kilpailuihin 40 valmista kiekkoluetteloa.", "Ennen kuin ampujasi astuu paikalle, lue kiekkoluettelo hänelle ääneen hänen kielellään, kirjain kirjaimelta: ”A, sitten F, sitten laukauksesta lähtevä pari C ja E.”"], "key_points": ["Ampujat sanovat ”menu”; suomeksi kiekkoluettelo.", "Sporting™-kiekkoluettelo: heittimet järjestyksessä sekä erikoiskiekot (90, 70, 60 mm, battue, jänis).", "15 yksittäis- + 5 kaksoiskiekkoa; kaksoiskiekoissa jo yksittäisinä näytetyt kiekot; ensin yksittäiset.", "Kaksoiskiekot: laukauksesta lähtevä, yhtäaikainen, rafale (vain Sporting™).", "Compak®: viisi kiekkoa ampumapaikkaa kohden, sama kaksoiskiekkotyyppi kaikilla paikoilla, jokainen kaksoiskiekko alkaa edellisen paikan viimeisellä kiekolla."], "terms": ["target-menu", "single-target", "double", "double-on-report", "simultaneous-double", "rafale-double"], "sources": [{"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch2-doubles-three-traps", "label": "2 · Doubles at a position with 3 machines"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-annex3-tables", "label": "17 · The 40 pre-established trajectory setting tables"}], "coach_says": [{"en": "Read the menu: on station three you have A, then F, then the pair C and E on report.", "meaning": "Kiekkojen järjestys ampumapaikalla 3, lopuksi laukauksesta lähtevä kaksoiskiekko.", "say": "Lue kiekkoluettelo: ampumapaikalla kolme sinulla on A, sitten F, sitten laukauksesta lähtevä pari C ja E."}, {"en": "Same traps, new menu — don't shoot from memory.", "meaning": "Järjestys on muuttunut edellisen kierroksen jälkeen.", "say": "Samat heittimet, uusi kiekkoluettelo – älä ammu muistin varassa."}, {"en": "Three singles, then a simo pair.", "meaning": "”Simo” on lyhenne yhtäaikaisesta kaksoiskiekosta.", "say": "Kolme yksittäistä, sitten yhtäaikainen pari."}], "quiz": [{"q": "Mitkä erikoiskiekot Sporting™-kiekkoluettelossa on näytettävä?", "options": ["Vain kiekkojen värit", "90 mm, 70 mm, 60 mm, battue tai jäniskiekko", "Vain jänis- ja battue-kiekot", "Ei mitään; tuomari ilmoittaa ne"], "answer": 1, "why": "Kiekkoluettelossa on lueteltava heittimet järjestyksessä ja mahdolliset erikoiskiekkotyypit."}, {"q": "Millä kiekolla Compak® Sporting -lajissa jokainen kaksoiskiekko alkaa?", "options": ["Aina heittimellä A", "Kiekolla, jota ei ole nähty aiemmin", "Edellisen ampumapaikan viimeisenä ammutulla kiekolla", "Millä tahansa ampujan valitsemalla kiekolla"], "answer": 2, "why": "Kaksoiskiekot ketjuttuvat ampumapaikalta toiselle: jokainen alkaa edellisen ampumapaikan viimeisellä kiekolla."}, {"q": "Mikä kaksoiskiekkotyyppi on olemassa vain Sporting™-lajissa?", "options": ["Rafale", "Laukauksesta lähtevä", "Yhtäaikainen", "Ei mikään"], "answer": 0, "why": "Compak®-kaksoiskiekot ovat laukauksesta lähteviä tai yhtäaikaisia; rafale on Sporting™-lajin kaksoiskiekko."}]}, {"id": "targets-hit-or-lost", "minutes": 5, "title": "Osuma vai ohi: näkyvä pala ja ”savun” ansa", "body": ["Kiekko merkitään ”one” (osuma), kun se on heitetty oikein, ampuja ampui sääntöjen mukaan ja siitä irtosi ainakin yksi näkyvä pala tai kiekko tuhoutui kokonaan tai osittain. Pölykiekkoja koskee sama sääntö. Kiekko on ”zero” (ohi), kun siitä ei irtoa näkyvää palaa ja on vain pölyä tai savua.", "Sääntö kääntyy siis yhden kuvan varaan: näkyvä pala. Pieni irtoava sirpale lasketaan osumaksi. Pölypilvi, jonka jälkeen kiekko lentää eteenpäin yhtenä kappaleena, on ohi. Tulospöytäkirjaan osuma merkitään yleensä X:llä ja ohilaukaus O:lla.", "Vain tuomari ratkaisee. Erän jäsenet eivät saa esittää mielipiteitään, eikä kukaan saa nostaa kiekkoa tarkistaakseen sen. Compak® Sporting -lajissa tuomari ilmoittaa jokaisen nollan kovaa tai äänimerkillä. Parcours de Chasse – Sporting™ -lajissa ampujan on rikottava kiekot paikassa, jossa tuomari näkee ne. Pyytämällä seuraavaa kiekkoa ampuja hyväksyy edellistä koskevan ratkaisun, joten vastalauseen on tultava heti.", "Nyt tulkkien ansa. Valmentajat kehuvat täydellistä osumaa sanoilla ”smoked it”, ”inked it” tai ”powdered it”: kiekko muuttui mustaksi pilveksi. Se on paras mahdollinen osuma, ei nolla. Mutta säännöissä ”only dust or smoke” (vain pölyä tai savua) tarkoittaa ohilaukausta. ”Dusted it” on riskialtis: se tarkoittaa yleensä, että irtosi vain pölyä, eli kiekko on ohi, mutta jotkut puhujat käyttävät sitä kehuna. Jos et ole varma, kysy, koska merkitykset ovat vastakkaiset.", "Lisäksi: ”dead” tarkoittaa osumaa (ei ”kuollut”), ”lost” ohilaukausta (ei ”kadonnut”)."], "key_points": ["Osuma = ainakin yksi näkyvä pala irtosi tai kiekko tuhoutui kokonaan tai osittain.", "Nolla = ei näkyvää palaa, vain pölyä tai savua.", "Vain tuomari ratkaisee; kiekkoja ei nosteta; seuraavan kiekon pyytäminen hyväksyy ratkaisun.", "Valmentajien slangi ”smoked it” = täydellinen osuma; sääntöjen ”vain savua” = ohi.", "”Dead” = osuma, ”lost” = ohi; kysy, jos ”dusted” on epäselvä."], "terms": ["one", "zero", "visible-piece", "referee", "score-sheet", "smoked-it", "chip"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "Smoked it! That's the picture.", "meaning": "Täydellinen osuma: kiekko muuttui pölyksi; ampujan pitäisi muistaa tämä ennakkokuva.", "say": "Pölyksi! Tuo on oikea kuva."}, {"en": "Dead — only a chip, but it counts.", "meaning": "Pieni näkyvä pala irtosi, joten se on osuma.", "say": "Osuma – vain sirpale, mutta se lasketaan."}, {"en": "Lost — you were just behind it.", "meaning": "Ohi; laukaus meni kiekon taakse.", "say": "Ohi – olit juuri sen takana."}, {"en": "Don't argue with me later — say it now, before you call.", "meaning": "Vastalause on tehtävä heti; seuraavan kiekon pyytäminen hyväksyy ratkaisun.", "say": "Älä väittele kanssani myöhemmin – sano se nyt, ennen kuin pyydät."}], "quiz": [{"q": "Kiekko lentää eteenpäin ehjänä, mutta siitä tulee pölypilvi. Mikä on tulos?", "options": ["Nolla (ohi)", "Osuma", "No Bird", "Puoli pistettä"], "answer": 0, "why": "Pelkkä pöly tai savu ilman näkyvää palaa on ohi."}, {"q": "Valmentaja huudahtaa ”Smoked it!” Miten käännät merkityksen?", "options": ["Siitä tuli vain savua, joten kiekko on ohi", "Piiput ylikuumenevat", "Täydellinen osuma: kiekko muuttui pölyksi", "Heitinkone on tulessa"], "answer": 2, "why": "Valmentajien slangissa ”smoked it” on kehu täydellisestä rikosta; sääntöjen ilmaus ”only smoke” tarkoittaa päinvastaista."}, {"q": "Erän jäsen sanoo, että viimeinen kiekko oli osuma. Kuka ratkaisee?", "options": ["Erän äänestys", "Valmentaja", "Tulkki", "Tuomari yksin"], "answer": 3, "why": "Kiekkoja koskevat ratkaisut kuuluvat tuomarille; erän jäsenet eivät saa puuttua niihin."}]}]}, {"id": "flight", "icon": "trajectory", "title": "Miten kiekot lentävät (kiekkotyypit)", "intro": "Valmentajat nimeävät jokaisen kiekon sen lennon mukaan: crosser, incomer, teal, looper, rabbit, report pair. Kuudessa lyhyessä oppitunnissa opit, mitä kukin nimi tarkoittaa, mitä ampujan on sen kanssa tehtävä ja mitkä sanat on helppo kääntää väärin.", "lessons": [{"id": "flight-crosser", "minutes": 5, "title": "Sivukiekko: poikki lentävä kiekko", "body": ["Crosser (sivukiekko) lentää ampujan edestä poikittain, suunnilleen suorassa kulmassa katselinjaan nähden: vasemmalta oikealle (merkitään V→O, englanniksi L→R) tai oikealta vasemmalle (O→V, R→L). Parcours de Chasse – Sporting™ -rataosuudella säännöt edellyttävät sekoitusta sivu-, viisto-, vasta- ja peräkiekkoja. Compak® Sporting -lajissa vasemmalta oikealle ja oikealta vasemmalle lentävä sivukiekko ovat kaksi kolmesta pakollisesta lentoradasta, joten jokaisessa Compak-radassa ne ovat.", "Sivukiekko näyttää koko sivuttaisnopeutensa, joten se tarvitsee kaikista kiekkotyypeistä eniten ennakkoa (lead, ase kiekon edelle), ja mitä kauempana se on, sitä enemmän ennakkoa se tarvitsee. ”Long crosser” tarkoittaa kaukaista sivukiekkoa, ei pitkään lentävää.", "Lue sen linja ja nopeus: lentääkö se suoraan, nouseeko se vai laskeeko se jo osumapisteessä? Näyttääkö se pintansa (kuvun tai pohjan) vai vain reunansa? Hidastuuko se? Hidastuva sivukiekko tarvitsee vähemmän ennakkoa kuin täydellä vauhdilla lentävä.", "Tyypillinen suunnitelma: jalat osumapisteen mukaan, katse löytää kiekon aikaisin, sitten edestä irtiveto (pull-away) tai pysyvä ennakko (maintained lead), ase yhä liikkeessä laukaushetkellä. Hyvin yleinen valmentajan tuomio sivukiekossa on ”behind” (takana): liian vähän ennakkoa tai pysähtynyt ase.", "Suunnat annetaan ampujan näkökulmasta. Jos seisot kasvot ampujaan päin, hänen ”vasemmalta oikealle” on sinun oikealta vasemmalle, joten älä koskaan käännä sanoja toisin päin."], "key_points": ["Sivukiekko lentää poikittain noin 90°:n kulmassa katselinjaan nähden: V→O tai O→V.", "Se tarvitsee eniten ennakkoa; suurempi etäisyys tarkoittaa enemmän ennakkoa.", "”Long crosser” = kaukana, ei pitkäkestoinen.", "Compak® Sporting -lajissa on aina V→O- ja O→V-sivukiekko.", "Vasen ja oikea ovat aina ampujan näkökulmasta."], "terms": ["crosser", "lead", "trajectory", "target-line", "break-point", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["crosser-rl"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}], "coach_says": [{"en": "Long crosser, right to left — trust the lead and keep the gun moving.", "meaning": "Kiekko on kaukana ja lentää ampujan oikealta vasemmalle; anna sille suunniteltu ennakko äläkä pysäytä aseen liikettä.", "say": "Kaukainen sivukiekko oikealta vasemmalle – luota ennakkoon ja pidä ase liikkeessä."}, {"en": "You're behind it — give it more.", "meaning": "Laukaus meni kiekon taakse: tarvitaan enemmän ennakkoa.", "say": "Olet sen takana – anna lisää."}, {"en": "It's dropping at your break point — stay under the line.", "meaning": "Siinä kohdassa, jossa ampuja rikkoo sen, sivukiekko on jo laskemassa, joten aseen on kuljettava hieman sen radan alapuolella.", "say": "Se laskee osumapisteessäsi – pysy linjan alla."}, {"en": "Pick it up early, it's quick off the trap.", "meaning": "Etsi kiekko tavallista lähempää heitintä, koska se lähtee heittimestä nopeasti.", "say": "Ota se aikaisin, se lähtee nopeasti heittimestä."}], "quiz": [{"q": "Mikä kiekkotyyppi tarvitsee yleensä eniten ennakkoa?", "options": ["Suoraan poispäin lentävä kiekko", "Suoraan ampujaa kohti lentävä vastakiekko", "Samalla etäisyydellä oleva sivukiekko", "Suoraan poispäin vierivä jäniskiekko"], "answer": 2, "why": "Sivukiekko näyttää koko sivuttaisnopeutensa, joten aseen on oltava kauimpana edellä; suoraviivaiset kiekot tarvitsevat vähän sivuttaista ennakkoa."}, {"q": "Valmentaja sanoo ”long crosser”. Mitä ”long” tarkoittaa?", "options": ["Kiekko on kaukana", "Kiekko lentää pitkään", "Kiekko on pitkä, soikea kiekko", "Ampujan pitäisi odottaa pitkään"], "answer": 0, "why": "Valmennuksessa ”long” kuvaa etäisyyttä. Long crosser on kaukainen sivukiekko, joka tarvitsee enemmän ennakkoa."}, {"q": "Mikä pitää paikkansa sivukiekoista Compak® Sporting -lajissa?", "options": ["Sivukiekot eivät ole sallittuja Compak-radalla", "Vain oikealta vasemmalle lentävät sivukiekot ovat sallittuja", "Sivukiekkoja saa heittää vain jäniskiekkoina", "V→O- ja O→V-sivukiekko ovat pakollisia"], "answer": 3, "why": "Compak® Sporting -säännöt tekevät kolmesta lentoradasta pakollisia: V→O-sivukiekon, O→V-sivukiekon ja peräkiekon."}]}, {"id": "flight-incomer-going-away", "minutes": 5, "title": "Vastakiekko, peräkiekko, ylilentävä ja takaa tuleva", "body": ["Incomer (vastakiekko) lentää ampujaa kohti, usein kaukaisesta heittimestä tai tornista, ja laskee yleensä tullessaan. Se voi näyttää hidastuvan ja leijuvan, mikä houkuttelee tähtäämään. Se ammutaan tavallisesti edestä, ennen kuin se on pään päällä, ja piiput voivat peittää (”blot out”) kiekon laukaushetkellä. Se on tarkoituksellista, ei virhe.", "Going-away (peräkiekko) lähtee ampujan läheltä tai takaa ja lentää poispäin. Se tarvitsee vähän sivuttaista ennakkoa, mutta pienenee nopeasti ja usein nousee tai laskee, joten ennakko on enimmäkseen pystysuuntaista ja ajoitus ratkaisee: älä odota. Compak® Sporting -lajissa sivun BC yli lentävä peräkiekko on pakollinen; se voi tulla edessä olevasta kaivannosta tai ampumapaikkojen takana olevasta tornista vähintään 4 m niiden yläpuolelta.", "Driven target (ylilentävä vastakiekko) on vastakiekko, joka kulkee ampujan pään yli kuin ajomiesten nostama fasaani. Löydä se aikaisin, liiku sen mukana, vie ase takaa alhaalta sen läpi, laukaise kun piiput peittävät sen ja jatka liikettä. Varo: ranskan ”en battue” (italiaksi ”in battuta”) tarkoittaa ajettua riistaa, ei battue-kiekkoa.", "Overhead from behind (takaa yli tuleva kiekko) tulee ampujan selän takaa yli ja lentää poispäin. Se nähdään myöhään, joten ampuja katsoo taakse aikaisin, nostaa aseen sen mukana, laukaisee kun piipunsuu koskettaa sen etureunaa ja jatkaa saattoa.", "”Incoming” ja ”going away” kuvaavat aina kiekkoa suhteessa ampujaan."], "key_points": ["Vastakiekko: tulee ampujaa kohti, yleensä laskien; ota se edestä.", "Peräkiekko: vähän sivuttaista ennakkoa, enimmäkseen pystysuuntaista; ammu ripeästi.", "Ylilentävä: vastakiekko pään yli; vie ase takaa läpi ja peitä se.", "Takaa yli tuleva: katso taakse aikaisin, nosta sen mukana, saatto.", "Compak® Sporting -lajissa on aina peräkiekko."], "terms": ["incomer", "going-away", "driven-target", "overhead", "tower", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "ShotKam — Master incomers", "url": "https://shotkam.com/blogs/blog-collections/master-incomers"}, {"title": "Sporting Gun — How to shoot going-away targets", "url": "https://sporting-gun.com/shooting/how-to-shoot-going-away-targets/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "flight", "preset": "incomer", "also": ["going-away", "overhead"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}], "coach_says": [{"en": "Take it out in front, before it gets on top of you.", "meaning": "Riko vastakiekko, kun se on vielä edessä, ei kun se on pään päällä.", "say": "Ota se edestä, ennen kuin se tulee päällesi."}, {"en": "Blot it out and keep swinging.", "meaning": "Anna piippujen peittää kiekko laukaushetkellä äläkä pysäytä asetta.", "say": "Peitä se ja jatka liikettä."}, {"en": "Don't wait on the going-away — it's getting smaller.", "meaning": "Ammu peräkiekko ripeästi, koska se loittonee nopeasti.", "say": "Älä odota peräkiekkoa – se pienenee koko ajan."}, {"en": "It comes from behind you — look back for it early.", "meaning": "Se on takaa yli tuleva kiekko; käännä katse sitä kohti ennen kiekon pyytämistä.", "say": "Se tulee takaasi – katso taakse ajoissa."}], "quiz": [{"q": "Valmentaja sanoo: ”Blot it out.” Mitä ampujan pitäisi tehdä?", "options": ["Pyyhkiä ampumalasien linssit", "Antaa piippujen peittää kiekko laukaushetkellä", "Odottaa, kunnes kiekko katoaa näkyvistä", "Ampua vain putoavia paloja"], "answer": 1, "why": "Vasta-, ylilentävissä ja nousevissa kiekoissa ase peittää usein kiekon laukaushetkellä; valmentaja pyytää juuri sitä."}, {"q": "Miksi peräkiekkoa ei pidä jättää liian pitkäksi aikaa?", "options": ["Se loittonee ja pienenee nopeasti", "Säännöt sallivat vain kolme sekuntia", "Siitä tulee aina sivukiekko", "Tuomari huutaa No Bird lakipisteen jälkeen"], "answer": 0, "why": "Peräkiekko kasvattaa etäisyyttä nopeasti, joten mitä kauemmin odotat, sitä vaikeammaksi se käy. Kolme sekuntia on kiekon lähetysaika, ei ampumaraja."}, {"q": "Mikä erottaa ylilentävän vastakiekon tavallisesta vastakiekosta?", "options": ["Se on aina jäniskiekko", "Se tulee ampujan takaa", "Se kulkee ampujan pään yli", "Sitä heitetään vain Compak® Sporting -lajissa"], "answer": 2, "why": "Driven tarkoittaa vastakiekkoa, joka tulee pään yli kuin ajettu riista. Takaa tuleva kiekko on overhead from behind."}]}, {"id": "flight-quartering", "minutes": 5, "title": "Viistokiekot: poispäin ja vastaan", "body": ["Quartering-kiekko (viistokiekko) lentää vinossa kulmassa: osin poikittain, osin poispäin tai kohti. Quartering away (viistokiekko poispäin) loittonee ampujasta kulmassa, esimerkiksi eteen oikealle. Quartering towards (myös ”quartering in”, viistosti vastaan tuleva kiekko) tulee ampujaa kohti kulmassa ja ohittaa hänet sivulta tai laskeutuu eteen. Kulma on usein noin 45°, mutta mikä tahansa suoran kiekon ja täyden sivukiekon väliltä on mahdollinen.", "Ennakko riippuu kulmasta: enemmän kuin suoraan poispäin lentävällä kiekolla, vähemmän kuin täydellä sivukiekolla. Jyrkkä kulma tarvitsee vähän ennakkoa, lähes poikittainen melkein yhtä paljon kuin sivukiekko.", "Poispäin lentävä viistokiekko pienenee ja hidastuu nopeasti, joten ota se ripeästi. Edestä irtiveto sopii siihen hyvin, koska ase pysyy kiekon linjalla. Viistosti vastaan tuleva kiekko kasvaa ja näyttää hitaalta, mikä houkuttelee ampujan odottamaan; se voi silloin tulla liian lähelle tai pudota näkyvistä.", "Sama heitin antaa eri ampumapaikoilta erilaisia kiekkoja: yhdeltä ampumapaikalta kiekko on sivukiekko, seuraavalta viistokiekko. Siksi kiekot on luettava juuri siltä ampumapaikalta, jota ampuja käyttää.", "Suomeksi sano ”viistokiekko poispäin” ja ”viistosti vastaan tuleva kiekko” (tai ”viisto peräkiekko / viisto vastakiekko”). Sanasta ”quarter” muodostettu kirjaimellinen käännös ei tarkoita ampujalle mitään."], "key_points": ["Quartering = vinossa kulmassa lentävä, suoran ja poikittaisen välillä.", "Quartering away loittonee kulmassa; quartering towards (in) tulee kohti kulmassa.", "Ennakko kasvaa kulman mukana: vähemmän kuin sivukiekossa, enemmän kuin suorassa kiekossa.", "Sama heitin näyttää erilaiselta jokaiselta ampumapaikalta: lue se omalta paikaltasi.", "Suomeksi: ”viistokiekko poispäin / viistosti vastaan tuleva kiekko”."], "terms": ["quartering-away", "quartering-towards", "crosser", "going-away", "lead", "pull-away"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "flight", "preset": "quartering-away", "also": ["quartering-towards"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "The first one's quartering away to the left — take it quickly before it gets small.", "meaning": "Ensimmäinen kiekko loittonee kulmassa ampujan vasemmalle; riko se aikaisin.", "say": "Ensimmäinen on viistokiekko poispäin vasemmalle – ota se nopeasti, ennen kuin se pienenee."}, {"en": "Quartering in from the right — don't let it get too close.", "meaning": "Kiekko tulee ampujaa kohti kulmassa oikealta; älä odota sitä.", "say": "Viistosti vastaan oikealta – älä päästä sitä liian lähelle."}, {"en": "Less lead than you think — it's only a slight angle.", "meaning": "Kiekko on lähes suora, joten se tarvitsee vain pienen ennakon.", "say": "Vähemmän ennakkoa kuin luulet – kulma on vain pieni."}], "quiz": [{"q": "Kiekko tulee ampujaa kohti kulmassa ja ohittaa hänet sivulta. Mikä se on?", "options": ["Peräkiekko", "Viistosti vastaan tuleva kiekko", "Pystykiekko", "Rafale"], "answer": 1, "why": "Quartering towards (tai quartering in) on kulmassa vastaan tuleva kiekko; quartering away on kulmassa loittoneva kiekko."}, {"q": "Miten viistokiekon ennakko vertautuu täyteen sivukiekkoon samalla etäisyydellä ja nopeudella?", "options": ["Se on sama kuin sivukiekossa", "Se on aina nolla", "Se on suurempi kuin sivukiekossa", "Se on pienempi, kulmasta riippuen"], "answer": 3, "why": "Vain liikkeen sivuttainen osa tarvitsee sivuttaista ennakkoa, joten mitä jyrkempi kulma, sitä pienempi ennakko."}, {"q": "Miksi kiekko pitää lukea juuri siltä ampumapaikalta, jolta ammut?", "options": ["Sama heitin voi olla yhdeltä paikalta sivukiekko ja toiselta viistokiekko", "Säännöt kieltävät katsomasta mistään muualta", "Kiekot vaihtavat väriä ampumapaikalta toiselle", "Vain tuomari saa seistä muualla"], "answer": 0, "why": "Ampujan ja kiekon linjan välinen kulma muuttuu paikan mukaan, joten myös kiekkotyyppi muuttuu."}]}, {"id": "flight-teal-chandelle-looper", "minutes": 6, "title": "Pystykiekko, chandelle, kaarikiekko ja laskevat kiekot", "body": ["Näissä kiekkotyypeissä on kyse korkeudesta ja kaaresta eikä niinkään kulmasta. Niiden nimet ovat radan rakentajien sanoja, eivät sääntökirjan termejä: säännöt luettelevat kiekkotyyppejä, ja Compak® Sporting -säännöt edellyttävät vaihtelevia lentoratoja, kuten nousevia, laskevia ja korkealle heitettyjä.", "Teal (pystykiekko; springing tai rising teal, pienen sorsan mukaan) heitetään lähes suoraan ylös, se hidastuu, pysähtyy lakipisteessä ja putoaa takaisin. Se ammutaan joko nousussa, viemällä ase alhaalta sen läpi ylöspäin, tai lakipisteessä sen pysähtyessä. Tökkääminen siihen lakipisteessä on klassinen virhe. Jotkut radan rakentajat käyttävät sanaa ”springing” kiekosta, joka nousee vinossa kulmassa eikä suoraan ylös, kuin lentoon pyrähtävä lintu.", "Chandelle (ranskaa, ”kynttilä”) nousee jyrkästi loivassa kaaressa, kaartuu yli ja putoaa lähes pystysuoraan. Se on helpoin nousussa; kaarteessa ennakko menee sivulle ja alle.", "Looper (kaarikiekko) lentää leveän kaaren taivaan poikki kuin sateenkaari, usein kallistetusta heittimestä heitetty battue-kiekko: se nousee, kääntää pintansa ja putoaa. Ase seuraa kaarta, edellä ja alapuolella.", "Dropping target (laskeva kiekko) on mikä tahansa kiekko lentonsa laskevassa osassa. Ennakko on osin pystysuuntaista: alle ja eteen, ase liikkeessä.", "Varo: nimet vaihtelevat maittain. Monet ranskankieliset käyttävät sanaa ”chandelle” kiekosta, joka nousee lähes suoraan ylös ja jota englantilainen valmentaja kutsuu nimellä teal. Aina kun kuulet sanan chandelle tai candle (kynttilä), kysy: suoraan ylös vai kaarena yli?"], "key_points": ["Pystykiekko (teal): lähes pystysuoraan ylös, pysähtyy, putoaa; ota se nousussa tai lakipisteessä.", "Chandelle: jyrkkä kaartuva nousu, kaartuu yli, putoaa lähes pystysuoraan.", "Kaarikiekko (looper): leveä sateenkaarimainen kaari poikki, usein battue, joka kääntyy ja putoaa.", "Laskeva kiekko: ennakko alle ja eteen, älä koskaan pysäytä asetta.", "Nimet vaihtelevat: ranskankieliset sanovat usein ”chandelle” pystykiekosta, joten varmista."], "terms": ["teal", "springing-target", "chandelle", "looper", "dropping-target", "battue"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "Shotgun Life — How to shoot a chandelle target", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}, {"title": "ShotgunWorld — Target terminology (forum)", "url": "https://www.shotgunworld.com/threads/target-terminology.477902/"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}], "sim": {"type": "flight", "preset": "teal", "also": ["chandelle", "looper", "dropping"]}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}], "coach_says": [{"en": "Take the teal on the way up — keep the barrels moving above it.", "meaning": "Riko nouseva pystykiekko ennen lakipistettä; ase jatkaa nousuaan sen ohi.", "say": "Ota pystykiekko nousussa – pidä piiput liikkeessä sen yläpuolella."}, {"en": "Don't poke at it on the top.", "meaning": "Älä pysähdy tähtäämään kiekkoon, kun se pysähtyy lakipisteeseen.", "say": "Älä tökkää sitä lakipisteessä."}, {"en": "The looper's turning over — underneath and in front.", "meaning": "Kiekko kääntyy kaarensa lakipisteen yli ja alkaa pudota; ennakko menee sen alle ja eteen.", "say": "Kaarikiekko kääntyy – alle ja eteen."}, {"en": "Second bird's dropping — go under it and keep the gun moving.", "meaning": "Kaksoiskiekon toinen kiekko putoaa; ammu sen alapuolelle ase liikkeessä.", "say": "Toinen kiekko laskee – mene sen alle ja pidä ase liikkeessä."}], "quiz": [{"q": "Mikä kiekko heitetään lähes suoraan ylös, pysähtyy lakipisteessä ja putoaa takaisin?", "options": ["Kaarikiekko", "Viistokiekko poispäin", "Jäniskiekko", "Pystykiekko"], "answer": 3, "why": "Se on pystykiekko (teal, springing tai rising teal). Kaarikiekko lentää leveän kaaren taivaan poikki."}, {"q": "Mihin ennakko yleensä menee laskevassa kiekossa?", "options": ["Yläpuolelle ja taakse", "Alle ja eteen", "Suoraan kiekkoon", "Vain sivulle, ei koskaan alas"], "answer": 1, "why": "Putoava kiekko liikkuu sekä alas että eteenpäin, joten osa ennakosta on pystysuuntaista: alle ja edelle."}, {"q": "Ranskankielinen valmentaja sanoo ”chandelle”. Mikä on turvallisinta?", "options": ["Tarkistaa: suoraan ylös vai kaari yli?", "Kääntää se aina englannin sanalla looper", "Kääntää se aina englannin sanalla teal", "Jättää se huomiotta, koska se ei ole sääntökirjan termi"], "answer": 0, "why": "Ranskankieliset tarkoittavat usein lähes pystysuoraa kiekkoa (englannin teal), kun taas englantilaisen radan rakentajan chandelle nousee kaaressa ja kaartuu yli; nopea tarkistus estää väärän suunnitelman."}]}, {"id": "flight-rabbit", "minutes": 5, "title": "Jäniskiekko: vierivä, pomppiva ja syöksyvä", "body": ["Rabbit (jäniskiekko) on 110 mm:n kiekko, jossa on paksu, vahva reuna; se heitetään syrjälleen niin, että se vierii maata pitkin kuin juokseva jänis. Se on erikoiskiekko, joten Parcours de Chasse – Sporting™ -lajissa se on merkittävä ampumapaikan kiekkoluetteloon.", "Valmentajat kuvaavat, miten se juoksee: rolling rabbit (vierivä) kulkee tasaisesti; hopping eli bouncing rabbit (pomppiva) hyppää kohoumista ja kivistä; bolting rabbit (syöksyvä) pyrähtää esiin suojasta ja juoksee nopeasti. Jäniskiekot voivat kulkea poikittain, ampujaa kohti tai poispäin.", "Jäniskiekko on painava ja hidastuu nopeasti, joten ampujat antavat sille usein liikaa ennakkoa. Valmentajat pyytävät pitämään piipunsuun matalalla ja ampumaan alaetureunaan, jotta äkillinen pomppukin osuu hauliparveen. Usein se näkyy vain lyhyessä aukossa pensaiden välissä, joten osumapiste on suunniteltava tarkasti.", "Säännöt: jokainen kiekko, myös jäniskiekko, ammutaan ase olalla; lonkalta ampuminen ei ole sallittua kummassakaan lajissa. Erikoistapaus: jos ensimmäinen laukaus menee ohi ja jäniskiekko rikkoutuu sitten itsestään, esimerkiksi kiveen, ennen toista laukausta, tulos on No Bird. Uusinnassa lasketaan vain toisella laukauksella rikottu kiekko.", "”Fur and feather” on englantilaisen sportingin slangia jäniskiekon (”fur”, turkki) ja ilmassa lentävän kiekon (”feather”, sulka) parista. Suomeksi puhutaan jäniskiekosta; tällä kurssilla käytetään sanaa jäniskiekko."], "key_points": ["Jäniskiekko: 110 mm, paksu reuna, vierii syrjällään maata pitkin.", "Vierivä, pomppiva, syöksyvä: kuvaavat, miten se juoksee.", "Se hidastuu nopeasti: älä anna liikaa ennakkoa; pidä piipunsuu matalalla.", "Aina olalta; jäniskiekko, joka rikkoutuu itsestään ensimmäisen laukauksen ohi menon jälkeen, on No Bird.", "”Fur and feather” = jäniskiekon ja ilmakiekon pari."], "terms": ["rabbit", "bolting-rabbit", "fur-and-feather", "target-menu", "no-bird", "break-point"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Gun Tests — Rabbit target clay shooting", "url": "https://www.gun-tests.com/recreational/rabbit-target-clay-shooting/"}, {"title": "Shooting UK — Clay pigeon sizes", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}], "sim": {"type": "flight", "preset": "rabbit"}, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch6-nobird-target-single-rabbit", "label": "6 · Target No Bird on a single and on a rabbit"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}], "coach_says": [{"en": "It hops on that bump — stay under it and keep moving.", "meaning": "Jäniskiekko hyppää tunnetussa kohdassa; pidä ase matalalla ja liikkeessä.", "say": "Se pomppaa tuosta kohoumasta – pysy sen alla ja jatka liikettä."}, {"en": "Shoot its feet.", "meaning": "Ammu jäniskiekon alareunaan, älä sen yli.", "say": "Ammu jalkoihin."}, {"en": "It slows down a lot — less lead than you think.", "meaning": "Jäniskiekko menettää nopeuttaan nopeasti, joten se tarvitsee pienemmän ennakon.", "say": "Se hidastuu paljon – vähemmän ennakkoa kuin luulet."}, {"en": "Fur and feather: rabbit first, before it reaches the bushes.", "meaning": "Jänis- ja ilmakiekon parissa ammu jäniskiekko ensin, koska se katoaa suojaan.", "say": "Jänis ja lintu: jänis ensin, ennen kuin se ehtii pensaisiin."}], "quiz": [{"q": "Ensimmäinen laukaus menee jäniskiekosta ohi, ja sitten se rikkoutuu kiveen ennen toista laukausta. Mitä tapahtuu?", "options": ["Se merkitään osumaksi, koska se rikkoutui", "Se merkitään nollaksi ensimmäisen ohilaukauksen vuoksi", "No Bird: uusitaan, vain toisella laukauksella rikottu lasketaan", "Ampuja siirtyy vain seuraavaan kiekkoon"], "answer": 2, "why": "Molemmat sääntökirjat käsittelevät tämän No Birdinä; uusinnassa ampujan on ammuttava ensimmäinen laukaus tahallaan ohi."}, {"q": "Miksi valmentajat varoittavat liiasta ennakosta jäniskiekossa?", "options": ["Säännöt rajoittavat ennakkoa", "Se on painava ja hidastuu nopeasti", "Se lentää aina ylöspäin", "Se on minikiekkoa pienempi"], "answer": 1, "why": "Jäniskiekossa on paksu reuna ja se vierii maata pitkin menettäen nopeasti vauhtia, joten tavallinen sivukiekon ennakko vie laukauksen eteen."}, {"q": "Mitä ”fur and feather” tarkoittaa?", "options": ["Jäniskiekon ja ilmakiekon paria", "Metsästäjän pukeutumissääntöä", "Kiekkoa, johon on liimattu sulkia", "Kahden jäniskiekon paria"], "answer": 0, "why": "Englantilaisen sportingin slangissa ”fur” on jäniskiekko ja ”feather” lentävä kiekko."}]}, {"id": "flight-pairs", "minutes": 6, "title": "Yksittäiskiekot ja kaksoiskiekot: report, rafale, simultaneous", "body": ["Single (yksittäiskiekko) on yksi kiekko yhdestä heittimestä. Molemmissa lajeissa siihen saa ampua kaksi laukausta, joten ohilaukauksen voi pelastaa toisella piipulla. Pair eli double (kaksoiskiekko) on kaksi kiekkoa, jotka ammutaan yhtenä kokonaisuutena yhden pyynnön jälkeen.", "Report pair (double on report, laukauksesta lähtevä kaksoiskiekko): pyyntö lähettää ensimmäisen kiekon, ja siihen ammuttu laukaus lähettää toisen. Parcours de Chasse – Sporting™ -lajissa toinen kiekko tulee 0–3 sekuntia tuon laukauksen jälkeen. Järjestys on kiinteä. ”Report” tarkoittaa laukauksen ääntä, ei kirjallista raporttia.", "Following pair, jota FITASC kutsuu nimellä rafale (peräkkäinen kaksoiskiekko): kaksi kiekkoa samasta heittimestä samalla linjalla, toinen niin nopeasti kuin heitin latautuu; kumman tahansa saa ampua ensin. Sitä on vain Sporting™-lajissa: Compak® Sporting -kaksoiskiekko on laukauksesta lähtevä tai yhtäaikainen.", "Simultaneous pair (yhtäaikainen kaksoiskiekko, ”simo”; englantilaisessa sportingissa ”true pair”): molemmat kiekot lähtevät samalla hetkellä yhdestä tai kahdesta heittimestä (Compak® Sporting -lajissa aina kahdesta eri heittimestä), ja ne saa ampua kummassa järjestyksessä tahansa.", "Patruunat: Sporting™-lajissa kaksoiskiekkoon on kaksi patruunaa, ja molemmat saa ampua yhteen kiekkoon; jos yksi laukaus rikkoo molemmat, molemmat lasketaan. Compak® Sporting -lajissa sallitaan vain yksi patruuna kiekkoa kohden, ja molemmat laukaukset yhteen kiekkoon merkitään nolla-nolla; myöskään molemmat kiekot rikkovaa yhtä laukausta ei yksinkertaisesti merkitä kahdesti (Compak®-tehtävä selittää tämän).", "Sporting™-ampumapaikalla erä ampuu ensin yksittäiskiekot ja sitten kaksoiskiekot. Yhtäaikaiset ja rafale-kaksoiskiekot näytetään ennen ammuntaa; laukauksesta lähteviä kaksoiskiekkoja ei."], "key_points": ["Yksittäiskiekko: yksi kiekko, kaksi laukausta sallittu.", "Laukauksesta lähtevä: ensimmäiseen ammuttu laukaus lähettää toisen; järjestys kiinteä.", "Rafale (peräkkäinen): sama heitin, sama linja, vain Sporting™.", "Yhtäaikainen (true pair): molemmat kerralla, vapaa järjestys.", "Sporting™: molemmat patruunat saa ampua yhteen kiekkoon; Compak® Sporting: yksi kiekkoa kohden."], "terms": ["single-target", "double", "double-on-report", "rafale-double", "simultaneous-double", "true-pair", "target-presentation"], "sources": [{"title": "CPSA — English Sporting (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["teal"], "pairs": ["report", "simultaneous", "rafale"]}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}], "coach_says": [{"en": "It's on report — finish the first one properly, the second waits for your shot.", "meaning": "Toinen kiekko tulee vasta, kun ampuja ampuu ensimmäiseen, joten ensimmäisen kanssa ei tarvitse kiirehtiä.", "say": "Se lähtee laukauksesta – ammu ensimmäinen kunnolla, toinen odottaa laukaustasi."}, {"en": "Simo: take the rabbit first, the teal will wait for you.", "meaning": "Yhtäaikaisessa kaksoiskiekossa ammu jäniskiekko ensin, koska pystykiekko pysyy ilmassa pidempään.", "say": "Yhtäaikainen: jänis ensin, pystykiekko odottaa sinua."}, {"en": "Rafale — after the first, come straight back to the trap for the second.", "meaning": "Molemmat kiekot tulevat samasta heittimestä; ensimmäisen laukauksen jälkeen palauta katse ja ase heitintä kohti löytääksesi toisen.", "say": "Rafale – ensimmäisen jälkeen suoraan takaisin heittimelle toista varten."}, {"en": "True pair from the tower, five of them.", "meaning": "Viisi yhtäaikaista kaksoiskiekkoa tornista (englantilaisen sportingin ilmaus).", "say": "Yhtäaikaiset tornista, viisi paria."}], "quiz": [{"q": "Mikä lähettää toisen kiekon laukauksesta lähtevässä kaksoiskiekossa?", "options": ["Toinen pyyntö", "Tuomarin merkki", "Ensimmäiseen kiekkoon ammuttu laukaus", "Tasan 5 sekunnin ajastin"], "answer": 2, "why": "”On report” tarkoittaa laukauksen äänestä: ensimmäiseen kiekkoon ampuminen lähettää toisen."}, {"q": "Ampuja ampuu Compak® Sporting -lajissa molemmat patruunat yhtäaikaisen kaksoiskiekon ensimmäiseen kiekkoon. Tulos?", "options": ["Sallittu, kuten Sporting™-lajissa", "Nolla-nolla", "No Bird ja uusinta", "Vain toinen kiekko on nolla"], "answer": 1, "why": "Compak® Sporting sallii kaksoiskiekossa yhden patruunan kiekkoa kohden; molempien tahallinen ampuminen yhteen kiekkoon merkitään nolla-nolla. Sporting™-lajissa se olisi sallittua."}, {"q": "Brittiläinen valmentaja sanoo ”true pair”. Miten käännät sen?", "options": ["Oikea, reilu pari", "Pari oikeita lintuja", "Rafale", "Yhtäaikainen kaksoiskiekko"], "answer": 3, "why": "”True pair” on englantilaisen sportingin nimi yhtäaikaiselle kaksoiskiekolle; ”true” ei liity oikeellisuuteen."}]}]}, {"id": "basics", "icon": "stance", "title": "Laukauksen perusteet", "intro": "Ennen kuin ennakosta puhutaan sanaakaan, valmentaja laittaa perusasiat kuntoon: jalat, aseen noston, silmät, kolmen pisteen suunnitelman ja liikkeessä pysyvän aseen. Näissä viidessä oppitunnissa opit valmentajan sanat jokaiseen vaiheeseen sekä säännöt, jotka rajaavat, mitä ampuja saa tehdä.", "lessons": [{"id": "basics-stance", "minutes": 5, "title": "Ampuma-asento: jalat kohti osumapistettä", "body": ["Ampuma-asento (stance) tarkoittaa sitä, miten ampuja seisoo ennen laukausta. Tilaa on vähän: Parcours de Chasse – Sporting™ -lajissa ampumapaikka on 1 m:n neliö tai ympyrä, ja molempien jalkojen on oltava sen sisällä ennen kiekon pyytämistä. Compak® Sporting -lajissa jokainen ampumapaikka on 1 m:n neliö, jossa on ampumakulman rajoitin (Firing Angle Limiter) – kehikko, joka estää ampujaa astumasta eteenpäin ja rajoittaa aseen liikettä sivusuunnassa.", "Tavallinen perusasento: jalat suunnilleen hartioiden leveydellä; oikeakätisellä vasen jalka hieman edessä (vasenkätisellä päinvastoin); polvet joustavina, ei lukittuina; paino hieman edessä, noin 60 prosenttia etujalalla. Valmentajat sanovat ”nose over toes” – nenä varpaiden päällä.", "Tärkein ohje: käännä etujalka kohti osumapistettä (break point), eli kohtaa, jossa ampuja aikoo rikkoa kiekon. Silloin vartalo on rento ja ”kiertymätön” juuri siinä, missä laukaus tapahtuu. Ampuja kiertyy lantiosta taaksepäin aseen aloituskohtaan (hold point) ja aukeaa kierrosta laukaukseen. Jos jalat osoittavat heitintä kohti, valmentajat varoittavat, kierto loppuu kesken, ja ase pysähtyy tai pää nousee tukilta.", "Vartalo kiertyy lantiosta, ei käsistä. Jalkojen asento voi olla hieman erilainen jokaiselle kiekolle.", "Käännä ”front foot” ja ”back foot” sanoilla etujalka ja takajalka, älä vasen ja oikea: ampujasi voi olla vasenkätinen."], "key_points": ["Sporting™: molemmat jalat 1 m:n ampumapaikan sisällä ennen kiekon pyytämistä.", "Compak® Sporting: 1 m:n ampumapaikka, jossa on ampumakulman rajoitin.", "Jalat hartioiden leveydellä, polvet joustavina, paino hieman edessä.", "Etujalka osoittaa osumapisteeseen; kierry lantiosta taaksepäin aloituskohtaan.", "Käännä etujalka/takajalka, älä vasen/oikea."], "terms": ["stance", "shooting-stand", "break-point", "hold-point", "firing-angle-limiter"], "sources": [{"title": "NSSA-NSCA — Stance and foot position (blog)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "Shotgun Life — Best foot position for clays shooting", "url": "https://www.shotgunlife.com/briefs/best-foot-position-for-clays-shooting.html"}, {"title": "Positive Shooting — Stance", "url": "http://www.positiveshooting.com/StanceMain.html"}], "sim": {"type": "flight", "preset": "crosser-lr", "focus": "stance"}, "rule_refs": [{"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}], "coach_says": [{"en": "Point your front foot at the break point.", "meaning": "Käännä etujalan kärki kohti kohtaa, jossa kiekko rikotaan.", "say": "Etujalka kohti osumapistettä."}, {"en": "Set your feet for the break, then wind back to the hold.", "meaning": "Aseta ensin jalat osumapisteen mukaan ja kierrä sitten ylävartalo takaisin aloituskohtaan.", "say": "Jalat osumapisteeseen, sitten kierrä takaisin aloituskohtaan."}, {"en": "Weight forward, soft knees.", "meaning": "Nojaa hieman etujalan päälle äläkä lukitse polvia.", "say": "Paino eteen, polvet joustaviksi."}, {"en": "Turn from the hips, not the arms.", "meaning": "Koko ylävartalo kiertyy; kädet eivät heilauta asetta yksinään.", "say": "Käänny lantiosta, älä käsistä."}], "quiz": [{"q": "Mihin valmentaja yleensä haluaa etujalan osoittavan?", "options": ["Heittimeen", "Katsepisteeseen", "Tuomariin", "Osumapisteeseen"], "answer": 3, "why": "Kun jalat on asetettu osumapisteen mukaan, vartalo on rento siellä, missä laukaus tapahtuu; jos jalat osoittavat heittimeen, kierto loppuu kesken."}, {"q": "Mitä Parcours de Chasse – Sporting™ -säännöt vaativat jaloilta ennen kiekon pyytämistä?", "options": ["Molemmat jalat ampumapaikan sisällä", "Etujalka ampumapaikan rajaviivalla", "Jalat yhdessä", "Ei mitään vaatimusta"], "answer": 0, "why": "Valmiusasentoa koskeva sääntö edellyttää, että molemmat jalat ovat 1 m:n ampumapaikan sisällä ennen kuin ampuja pyytää kiekkoa."}, {"q": "Ampuja on vasenkätinen. Valmentaja sanoo ”Open your front foot”. Kummasta jalasta on kyse?", "options": ["Aina vasemmasta, kätisyydestä riippumatta", "Oikeasta: se on vasenkätisen etujalka", "Takajalasta, joka on lähempänä heitintä", "Molemmista jaloista yhdessä"], "answer": 1, "why": "Vasenkätisellä etujalka on oikea jalka. Kun käännät ”front foot” sanalla ”etujalka”, vältät virheen."}]}, {"id": "basics-mount", "minutes": 6, "title": "Valmiusasento ja aseen nosto", "body": ["Parcours de Chasse – Sporting™ -lajissa lähdetään ase alhaalla. Ennen kiekon pyytämistä tukin perä koskettaa vartaloa ja tukin takaosan yläreuna pysyy ampumaliivin merkkiviivan alapuolella; viiva on 25 cm olkapäiden linjan alapuolella ja kontrastivärinen. Ampuja pitää tämän asennon, kunnes kiekko on lähtenyt ja näkyy. Liian aikaisesta nostosta seuraa suullinen varoitus ja keltainen kortti; toistuvasta rikkeestä samalla rataosuudella seuraa punainen kortti ja kiekko merkitään ohilaukaukseksi (nolla).", "Compak® Sporting -lajissa aseen asento kiekkoa pyydettäessä on vapaa, joten ase voi olla jo olalla. Molemmissa lajeissa jokainen kiekko ammutaan ase olalla, ja Sporting™-lajissa aseen asento on vapaa kaksoiskiekon kahden kiekon välillä.", "Aseen nosto (gun mount) tuo aseen poskelle ja olalle. Valmentajat opettavat periaatetta ”muzzles first” – piipunsuut ensin: etukäsi aloittaa piippujen liikkeen kiekon linjaa pitkin, tukki nousee poskelle ja asettuu olkataskuun samalla, kun ase saavuttaa linjan. ”Move, mount, shoot” – liike, nosto, laukaus – on yksi sujuva kokonaisuus. Ase tuodaan kasvoille, ei kasvoja aseelle; poski pysyy poskipakalla, koska silmä on takatähtäin.", "Brittiläinen valmentaja voi sanoa ”gun up” tai ”pre-mount this one” (nosta ase valmiiksi olalle). Se on kielletty FITASCin Sporting™-kilpailussa, normaali Compak® Sporting -lajissa ja harjoituksissa pelkkä harjoite. Aseen nostaminen ja heilauttaminen kuvitellulla linjalla ennen kiekon pyytämistä (tähtäysharjoittelu, mock shooting) on Sporting™-lajissa kielletty: ensin varoitus, sitten nolla."], "key_points": ["Sporting™: tukki liivin merkkiviivan alapuolella (25 cm olkapäiden linjan alapuolella), kunnes kiekko näkyy.", "Liian aikainen nosto: keltainen kortti, sitten punainen kortti ja menetetty kiekko samalla rataosuudella.", "Compak® Sporting: aseen asento vapaa kiekkoa pyydettäessä; laukaus aina olalta.", "Piipunsuut ensin, ase kasvoille, poski poskipakalla: liike, nosto, laukaus.", "”Pre-mount” on harjoite, ei koskaan FITASCin Sporting™-kilpailussa."], "terms": ["ready-position", "jacket-line", "gun-mount", "move-mount-shoot", "comb", "yellow-card", "mock-shooting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-lr", "focus": "mount"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Gun to your face, not your face to the gun.", "meaning": "Nosta tukki poskelle; älä laske päätä aseen luo.", "say": "Ase poskelle, älä poskea aseelle."}, {"en": "Muzzles first — move, mount, shoot.", "meaning": "Aloita piippujen liike kiekon mukana, nosta ase liikkeen aikana ja laukaise, kun nosto on valmis.", "say": "Piiput ensin – liike, nosto, laukaus."}, {"en": "Your mount's late and too fast — start it with the front hand.", "meaning": "Ase nousee liian myöhään ja nykäisten; etukäden pitäisi aloittaa liike aikaisemmin.", "say": "Nostosi on myöhässä ja liian nopea – aloita se etukädellä."}, {"en": "Low gun on this one, like in competition.", "meaning": "Aloita tukki liivin merkkiviivan alapuolella, kuten FITASCin Sporting™-säännöt vaativat.", "say": "Tämä ase alhaalta, niin kuin kisoissa."}], "quiz": [{"q": "Mihin asti tukin on Parcours de Chasse – Sporting™ -lajissa pysyttävä liivin merkkiviivan alapuolella?", "options": ["Kunnes ampuja on pyytänyt kiekkoa", "Kunnes tuomari nyökkää", "Kunnes kiekko on lähtenyt ja näkyy", "Kunnes ensimmäinen laukaus on ammuttu"], "answer": 2, "why": "Valmiusasento pidetään, kunnes kiekko on lähtenyt ja se näkyy; vasta silloin aseen saa nostaa."}, {"q": "Saako ampuja Compak® Sporting -lajissa pyytää kiekkoa ase jo olalla?", "options": ["Ei: siitä saa keltaisen kortin", "Vain jäniskiekoissa ja muissa matalissa kiekoissa", "Vain kaksoiskiekon kiekkojen välillä", "Kyllä: aseen asento pyydettäessä on vapaa"], "answer": 3, "why": "Compak® Sporting -lajissa ei ole ase alhaalla -sääntöä: ase voi olla olalla tai alhaalla kiekkoa pyydettäessä, mutta jokainen kiekko ammutaan olalta."}, {"q": "Miksi valmentajat vaativat, että poski pysyy poskipakalla?", "options": ["Silmä on takatähtäin, joten sen on oltava aina samassa kohdassa", "Jotta korvaan tulisi vähemmän melua", "Koska molempien lajien säännöt vaativat sitä", "Jotta kasvot olisivat piilossa tuomarilta"], "answer": 0, "why": "Haulikossa ei ole takatähtäintä: kiskon yllä oleva silmä on tähtäin, joten poskelta noussut pää vie laukauksen yläkanttiin."}]}, {"id": "basics-eyes", "minutes": 5, "title": "Silmät: hallitsevuus, molemmat silmät auki, tarkka katse", "body": ["Useimmilla ihmisillä on hallitseva silmä (master eye), johon aivot luottavat enemmän; se on yleensä samalla puolella kuin vahvempi käsi. Hallitsevan silmän on katsottava kiskoa pitkin. Ristidominanssi (cross-dominance) tarkoittaa, että hallitseva silmä on eri puolella kuin ampumaolka; keskeisessä näössä (central vision) kumpikaan silmä ei selvästi hallitse. Kummassakin tapauksessa ase osoittaa muualle kuin ampuja odottaa, usein sivulle.", "Yksinkertainen testi: rajaa molemmat silmät auki kaukana oleva kohde käsillä muodostettuun pieneen kolmioon ja sulje sitten silmät vuorotellen; se silmä, jolla kohde pysyy kolmiossa, on hallitseva. Valmentaja voi myös asettua ampujan eteen ja katsoa kolmion läpi.", "Valmentajan valitsemat ratkaisut: toisen silmän sulkeminen tai siristäminen aseen noston aikana; pieni piste ampumalaseissa; ampumaan opettelu toiselta olalta; tai harvemmin ristitukki (cross-over stock). Molemmat silmät auki on suositeltavaa aina kun mahdollista, koska kaksi silmää arvioi nopeutta, kulmaa ja etäisyyttä paremmin.", "Katse: pehmeä, laaja katse (soft focus) odotettaessa katsepisteessä, sitten tarkka katse (hard focus) itse kiekkoon, mieluiten sen etureunaan (leading edge). Jos ampuja katsoo taaksepäin piippuun tai jyvään tarkistaakseen ennakon, ase pysähtyy.", "Ampumalasit ovat ampujille pakolliset molemmissa lajeissa, joten piste tehdään niihin."], "key_points": ["Hallitsevan silmän on katsottava kiskoa pitkin.", "Ristidominanssi ja keskeinen näkö saavat aseen osoittamaan kiekon ohi.", "Testaa käsillä tehdyllä kolmiolla; valmentaja valitsee ratkaisun.", "Pehmeä katse katsepisteessä, tarkka katse etureunaan; älä koskaan katso takaisin jyvään.", "Ampumalasit ovat pakolliset molemmissa lajeissa."], "terms": ["eye-dominance", "master-eye", "cross-dominance", "central-vision", "soft-focus", "hard-focus", "leading-edge", "safety-glasses"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "Paragon School — Eye dominance testing", "url": "https://www.paragonschool.com/blog-post/eye-dominance-testing-and-issues-in-sporting-clays-skeet-and-trap-go-slowly-please"}, {"title": "Shotgun Life — How to shoot a chandelle target (focus on the leading edge)", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}], "sim": {"type": "flight", "preset": "going-away", "focus": "eyes"}, "rule_refs": [{"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}], "coach_says": [{"en": "Close your left eye as the gun comes up.", "meaning": "Sulje vasen silmä aseen noston aikana, ei ennen, jotta oikea silmä ohjaa asetta.", "say": "Sulje vasen silmä, kun ase nousee."}, {"en": "Eyes on the clay, not the barrel.", "meaning": "Pidä katse kiekossa; piipun tarkistaminen pysäyttää aseen.", "say": "Katse kiekkoon, ei piippuun."}, {"en": "Look at the leading edge.", "meaning": "Keskitä katse liikkuvan kiekon etureunaan, älä sen keskelle.", "say": "Katso kiekon etureunaa."}, {"en": "Don't look at the trap — look out to your pick-up point.", "meaning": "Odota katse hieman ulompana linjalla, siellä missä kiekon näkee ensimmäisen kerran selvästi.", "say": "Älä katso heitintä – katso ulos katsepisteeseen."}], "quiz": [{"q": "Oikeakätisen ampujan hallitseva silmä on vasen. Miksi tätä kutsutaan?", "options": ["Keskeinen näkö", "Tarkka katse", "Ristidominanssi", "Etureuna"], "answer": 2, "why": "Ristidominanssi tarkoittaa, että hallitseva silmä on eri puolella kuin ampumaolka."}, {"q": "Miksi on virhe katsoa takaisin jyvään ennakon tarkistamiseksi?", "options": ["Se on sääntöjen mukaan kielletty", "Ase pysähtyy ja laukaus menee taakse", "Jyvä heijastaa auringonvaloa", "Kiekko vaihtaa siitä väriä"], "answer": 1, "why": "Kun katse siirtyy aseeseen, aseen liike pysähtyy ja kiekko jää ääreisnäön varaan, joten laukaus menee kiekon taakse."}, {"q": "Mihin dominanssin korjaava piste yleensä tehdään?", "options": ["Ampumalaseihin peitettävän silmän eteen", "Jyvään kiskon päässä", "Kiskoon sen puoliväliin", "Liivin merkkiviivaan olan alapuolelle"], "answer": 0, "why": "Ampumalasit ovat joka tapauksessa pakolliset, joten pieni piste linssiin ei-hallitsevan silmän eteen on yksinkertaisin ratkaisu."}]}, {"id": "basics-three-points", "minutes": 5, "title": "Katsepiste, aloituskohta ja osumapiste: ampumapaikan suunnittelu", "body": ["Ennen jokaista kiekkoa ampuja määrittää kolme pistettä. Katsepiste (pick-up point) on kohta, jossa silmät näkevät kiekon ensimmäisen kerran selvästi – hieman ulompana heittimestä, ei sen suulla, jossa kiekko on pelkkä sumea viiru. Aseen aloituskohta (hold point) on kohta, jossa piipunsuut odottavat kiekkoa pyydettäessä, yleensä kiekon linjalla tai hieman sen alapuolella, katsepisteen ja osumapisteen välissä. Osumapiste (break point) on kohta, jossa ampuja aikoo rikkoa kiekon.", "Suunnittelujärjestys: valitse ensin osumapiste, aseta jalat sen mukaan, kierry takaisin aloituskohtaan ja vie sitten katse katsepisteeseen. Parcours de Chasse – Sporting™ -lajissa tukki on alhaalla, kunnes kiekko ilmestyy, joten aloituskohta tarkoittaa siellä sitä, mihin piipunsuut osoittavat aseen ollessa alhaalla.", "Tyypilliset virheet: liian kaukana oleva osumapiste tarkoittaa nopeaa, hallitsematonta aseen liikettä tai jo laskevaa kiekkoa; liian lähellä oleva liian vähäistä liikettä ja ”tökkäystä” (poke). Liian lähellä heitintä oleva aloituskohta pakottaa aseen jahtaamaan kiekkoa; liian kaukana kiekko ohittaa aseen.", "Kiekot luetaan näytekiekoista. Sporting™-lajissa kaikki lentoradat näytetään ensimmäiselle ampujalle, ja pyynnöstä tuomari näyttää kiekot uudelleen, enintään kaksi kiekkoa kiekkoluettelon kutakin kiekkoa kohden; Compak® Sporting -lajin erissä yksittäiskiekot näytetään kerran aamulla, ensimmäiselle erälle. Kiekko on rikottava paikassa, jossa tuomari näkee sen, takarajan sisäpuolella.", "”Where are you taking it?” kysyy osumapistettä; ”kill point” on neutraali synonyymi."], "key_points": ["Katsepiste = silmät; aloituskohta = piipunsuut; osumapiste = missä kiekko rikotaan.", "Suunnittele osumapisteestä taaksepäin: jalat, aloituskohta, silmät.", "Aloituskohta on yleensä katsepisteen ja osumapisteen välissä, linjalla tai hieman sen alla.", "Lue kiekot näytekiekoista; riko ne paikassa, jossa tuomari näkee.", "”Where are you taking it?” = missä osumapisteesi on?"], "terms": ["pick-up-point", "hold-point", "break-point", "target-presentation", "shooting-limit", "target-line"], "sources": [{"title": "Shotgun Life — The proper hold point for sporting clays", "url": "https://www.shotgunlife.com/briefs/what-is-the-proper-hold-point-for-shooting-sporting-clays.html"}, {"title": "Clay Target Instruction — Hold point", "url": "https://claytargetinstruction.com/articles/hold-point/"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "flight", "preset": "quartering-away", "focus": "points"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}], "coach_says": [{"en": "Where are you taking it?", "meaning": "Valmentaja kysyy, missä ampuja aikoo rikkoa kiekon.", "say": "Missä otat sen?"}, {"en": "Move your hold point halfway back to the trap.", "meaning": "Pidä piipunsuut lähempänä heitintä, puolessa nykyisestä etäisyydestä.", "say": "Siirrä aloituskohtaa puoliväliin takaisin heitintä kohti."}, {"en": "Look further out — pick it up where it's sharp.", "meaning": "Siirrä katse kauemmas heittimestä sinne, missä kiekon näkee ensimmäisen kerran selvästi.", "say": "Katso kauemmas – ota se siitä, missä se näkyy terävänä."}, {"en": "Hold a little lower, just under the line.", "meaning": "Pidä piipunsuut kiekkoa pyydettäessä hieman kiekon radan alapuolella.", "say": "Pidä vähän alempana, juuri linjan alla."}], "quiz": [{"q": "Mikä piste koskee silmiä eikä asetta?", "options": ["Aloituskohta", "Osumapiste", "Katsepiste", "Sisäänvientikohta"], "answer": 2, "why": "Katsepiste on kohta, jossa silmät näkevät kiekon ensimmäisen kerran selvästi; aloituskohta koskee piipunsuita."}, {"q": "Mitä yleensä tapahtuu, jos aloituskohta on liian lähellä heitintä?", "options": ["Kiekko ohittaa aseen", "Tuomari huutaa No Bird", "Aseen on jahdattava kiekkoa", "Kiekko hidastuu"], "answer": 2, "why": "Liian lähellä heitintä kiekko lähtee täydellä vauhdilla piipunsuiden ohi, ja ampujan on jahdattava sitä."}, {"q": "Parcours de Chasse – Sporting™ -lajissa ampumapaikalla oleva ampuja pyytää nähdä näytekiekot uudelleen. Mikä on enimmäismäärä kiekkoluettelon kiekkoa kohden?", "options": ["Kaksi kiekkoa", "Ei yhtään: uusintoja ei sallita", "Niin monta kuin hän haluaa", "Tasan viisi"], "answer": 0, "why": "Tuomari näyttää kiekot pyynnöstä uudelleen, enintään kaksi kiekkoa kiekkoluettelon kutakin kiekkoa kohden."}]}, {"id": "basics-follow-through", "minutes": 5, "title": "Saatto, aseen nopeus ja tempo", "body": ["Saatto (follow-through) tarkoittaa, että ase jatkaa liikettä kiekon linjaa pitkin liipaisimen painamisen jälkeen, kuten golf- tai tennislyönnissä. Laukaisupäätöksen ja haulien piipusta lähdön välillä on pieni viive; jos ase pysähtyy liipaisimella, laukaus menee taakse. Valmentajat seuraavat piipunsuita laukauksen jälkeen: jos ne jähmettyvät tai painuvat alas, saatto puuttui.", "Aseen nopeus (gun speed) on se, kuinka nopeasti piipunsuut liikkuvat kiekkoon verrattuna, ja se määrittää ennakkomenetelmän: sama nopeus kuin kiekolla on pysyvä ennakko (maintained lead); kiekkoa nopeampi on läpiveto (swing-through); sama nopeus ja sitten lyhyt kiihdytys on edestä irtiveto (pull-away). Liian hidas ase jää jälkeen; liian nopea, valmentajat sanovat, menee yli, ja ampuja usein pysäyttää sen.", "Tempo on se, kuinka nopeasti koko laukaus tehdään; rytmi on sen tasaisuus. Nopea, lähellä oleva kiekko vaatii nopean tempon, pitkä ja hidas sivukiekko rauhallisemman, mutta rytmi pysyy sujuvana. Monet valmentajat sanovat, että ampujat, joilla on yksi tempo kaikkeen, menettävät ne kiekot, jotka vaativat päinvastaista.", "”Stay in the gun” – pysy aseessa: poski tukilla ja katse kiekossa, kunnes se rikkoutuu. Näin ampuja on myös valmis toiseen piippuun, koska yksittäiskiekkoon saa ampua kaksi laukausta.", "Käännä ”finish the shot” liikkeen jatkamiseksi, ei pysähtymiseksi."], "key_points": ["Saatto: ase jatkaa liikettä liipaisun jälkeen; pysähdys vie laukauksen taakse.", "Aseen nopeus määrittää menetelmän: sama (pysyvä ennakko), nopeampi (läpiveto), ensin sama ja sitten nopeampi (edestä irtiveto).", "Tempo = koko laukauksen nopeus; rytmi = sen tasaisuus.", "Pysy aseessa: valmiina toiseen piippuun yksittäiskiekossa.", "”Finish the shot” = jatka liikettä."], "terms": ["follow-through", "gun-speed", "tempo", "stopping-the-gun", "maintained-lead", "swing-through", "pull-away", "single-target"], "sources": [{"title": "Shooting UK — The overhead clay from behind (follow-through)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "focus": "follow-through"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "Follow through — the gun keeps moving after the bang.", "meaning": "Älä pysäytä aseen liikettä laukaukseen.", "say": "Saatto – ase liikkuu vielä pamauksen jälkeen."}, {"en": "You stopped the gun.", "meaning": "Piipunsuut pysähtyivät liipaisimella, joten laukaus meni taakse.", "say": "Pysäytit aseen."}, {"en": "Match the speed of the bird — you're racing it.", "meaning": "Ase liikkuu paljon kiekkoa nopeammin; liiku kiekon nopeudella.", "say": "Liiku kiekon tahdissa – nyt kilpailet sen kanssa."}, {"en": "Slow the tempo down, this one gives you lots of time.", "meaning": "Kiekko on hidas tai pitkä, joten koko liike voi olla rauhallisempi.", "say": "Hidasta tempoa, tässä on paljon aikaa."}, {"en": "Stay in the gun until you see it break.", "meaning": "Pidä poski tukilla ja katse kiekossa, kunnes se rikkoutuu.", "say": "Pysy aseessa, kunnes näet sen hajoavan."}], "quiz": [{"q": "Valmentaja sanoo ”You stopped the gun”. Mihin laukaus todennäköisimmin meni?", "options": ["Eteen", "Yli", "Täsmälleen kiekkoon", "Taakse"], "answer": 3, "why": "Kiekko jatkaa liikettään, mutta pysähtynyt ase ei, joten laukaus menee kiekon taakse."}, {"q": "Mikä aseen nopeus kuvaa pysyvää ennakkoa?", "options": ["Paljon kiekkoa nopeampi", "Sama kuin kiekolla", "Nolla: ase odottaa", "Kiekkoa hitaampi"], "answer": 1, "why": "Pysyvässä ennakossa piipunsuut liikkuvat kiekon nopeudella, ja väli pysyy samana. Odottava ase on väijytys (ambush); nopeampi on läpiveto."}, {"q": "Mikä on tempon ja rytmin ero?", "options": ["Tempo on laukauksen nopeus, rytmi sen tasaisuus", "Ne ovat kaksi sanaa samalle asialle", "Tempo on radalla soitettava musiikki", "Rytmi on kiekkojen välinen aikaraja"], "answer": 0, "why": "Valmentajat muuttavat tempoa jokaisen kiekon mukaan ja pitävät rytmin sujuvana, joten käännä molemmat sanat erikseen."}]}]}, {"id": "lead", "icon": "lead", "title": "Ennakko ja ampumamenetelmät", "intro": "Ennakko (lead, brittienglanniksi myös forward allowance) on se, mistä valmentajat puhuvat eniten: miksi aseen on osoitettava liikkuvan kiekon edelle, neljä tapaa saada se sinne ja ne oudot yksiköt, joilla sitä kuvataan. Tämä tehtävä näyttää jokaisen menetelmän vaihe vaiheelta ja opettaa kääntämään ilmaukset ”four foot”, ”half a bird” tai ”double it” muuttamatta merkitystä.", "lessons": [{"id": "lead-why", "minutes": 6, "title": "Miksi ennakkoa tarvitaan: todellinen ja havaittu ennakko", "body": ["Hauleilta kuluu sekunnin murto-osa kiekon luo, ja sinä aikana kiekko liikkuu eteenpäin. Suoraan sivukiekkoon osoittava ase ampuu siksi sen taakse. Aseen on osoitettava edelle, jotta haulit ja kiekko kohtaavat. Tämä väli on ennakko (lead), brittienglanniksi myös ”forward allowance”.", "Ennakko kasvaa kiekon nopeuden, etäisyyden ja kulman mukana. Täysi sivukiekko tarvitsee eniten; suoraan ampujaa kohti tai hänestä poispäin lentävä kiekko ei tarvitse juuri lainkaan sivuttaista ennakkoa, mutta nousevat ja laskevat kiekot tarvitsevat pystysuuntaista ennakkoa (yläpuolelle tai alapuolelle).", "Todelliset luvut yllättävät. Eräs ammunta-aiheinen verkkosivusto antaa noin 21–25 jaardin (noin 20 m) päässä olevalle sivukiekolle noin 3–4 jalan eli suunnilleen metrin todellisen ennakon. Monet ampujat sanovat sen kasvavan suunnilleen suhteessa etäisyyteen, joten sama pieni väli piipunsuulla tarkoittaa kaukaisessa kiekossa paljon suurempaa todellista ennakkoa.", "Todellinen ennakko (actual lead) on todellinen etäisyys kiekon edessä ilmassa. Havaittu ennakko (perceived lead, ”lead picture” tai ”sight picture”, ennakkokuva) on väli, jonka ampuja näkee piipunsuun ja kiekon välillä. Metri 20 metrin päässä näyttää piipunsuulla muutamalta senttimetriltä. Menetelmä muuttaa kuvaa: pysyvää ennakkoa käyttävä ampuja näkee suurimman välin, läpivetoa käyttävä vähän tai ei lainkaan, koska aseen nopeus lisää ennakkoa.", "Eräs amerikkalainen ohjaaja huomauttaa, että oikeakätinen ampuja tuntee usein vasemmalta oikealle lentävän sivukiekon tarvitsevan enemmän ennakkoa kuin oikealta vasemmalle lentävän; todellinen ennakko on sama, vain havainto eroaa. Siksi valmentajan ”four feet” kuvaa hänen näkemäänsä kuvaa, ei mittausta."], "key_points": ["Ennakkoa tarvitaan, koska kiekko liikkuu haulien lentäessä.", "Suurempi nopeus, etäisyys ja kulma tarkoittavat enemmän ennakkoa.", "Todellinen ennakko (ilmassa) on paljon suurempi kuin havaittu ennakko (piipunsuulla).", "Menetelmä muuttaa kuvaa: pysyvässä ennakossa näkyy eniten, läpivedossa vähiten.", "Valmentajan luku on kuva, ei mittaus."], "terms": ["lead", "perceived-lead", "crosser", "gun-speed", "maintained-lead", "swing-through"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "focus": "perceived-vs-actual"}, "rule_refs": [], "coach_says": [{"en": "Forget the real distance — what matters is your picture.", "meaning": "Älä ajattele metrejä ilmassa; muista se väli, jonka näit piipunsuulla osuessasi.", "say": "Unohda todellinen etäisyys – ratkaisevaa on näkemäsi kuva."}, {"en": "That's the picture — remember it.", "meaning": "Ennakko oli tuossa osumassa oikea; pidä sama ennakkokuva.", "say": "Tuo on oikea kuva – muista se."}, {"en": "Same lead on the right-to-left, it only looks different.", "meaning": "Todellinen ennakko on molempiin suuntiin sama; vain havainto muuttuu.", "say": "Sama ennakko oikealta vasemmalle, se vain näyttää erilaiselta."}], "quiz": [{"q": "Mitä havaittu ennakko on?", "options": ["Todellinen etäisyys kiekon edessä ilmassa", "Väli, jonka ampuja näkee piipunsuun ja kiekon välillä", "Kiekkoluetteloon kirjattu ennakko", "Etäisyys ampumapaikalta heittimelle"], "answer": 1, "why": "Havaittu ennakko on kuva piipunsuulla; todellinen ennakko on todellinen etäisyys ilmassa ja paljon suurempi."}, {"q": "Mikä menetelmä antaa yleensä suurimman havaitun ennakon?", "options": ["Läpiveto", "Edestä irtiveto", "Pysyvä ennakko", "Kaikki ovat samanlaisia"], "answer": 2, "why": "Pysyvässä ennakossa ase liikkuu kiekon nopeudella eikä aseen nopeus lisää mitään, joten ampujan on nähtävä koko väli."}, {"q": "Mikä kiekko ei tarvitse juuri lainkaan sivuttaista ennakkoa?", "options": ["Suoraan poispäin lentävä kiekko", "Kaukainen sivukiekko", "45°:n viistokiekko poispäin", "40 m:n päässä oleva sivukiekko"], "answer": 0, "why": "Suoraan poispäin lentävällä kiekolla ei ole sivuttaisliikettä; sen tarvitsema ennakko on pystysuuntaista."}]}, {"id": "lead-maintained", "minutes": 5, "title": "Pysyvä ennakko: mene eteen, pysy edessä", "body": ["Maintained lead (pysyvä ennakko; Yhdysvalloissa sustained lead) pitää piipunsuut kiekon edellä alusta laukaukseen asti.", "Miltä se näyttää vaihe vaiheelta sivukiekossa. 1) Aloitus: piipunsuut odottavat aloituskohdassa (hold point) selvästi ulompana linjalla, sen kohdan edellä, josta kiekko kulkee; silmät katsovat taaksepäin kohti katsepistettä. 2) Sisäänvienti: kiekon tullessa ase liikkuu ja piipunsuut liittyvät linjalle sen eteen, ei koskaan taakse; tämä on sisäänvientikohta (insertion point). 3) Seuranta: piipunsuut liikkuvat kiekon nopeudella, joten väli pysyy samana. 4) Laukaus: liipaisinta painetaan, kun väli on oikea ja ase yhä liikkeessä. 5) Ase jatkaa liikettä laukauksen jälkeen.", "Vahvuudet: tarkka, vähän aseen liikettä, nopea kiekkojen välillä, ja ennakkoa on helppo säätää. Se sopii tasaisille, ennustettaville kiekoille: kaukaisille sivukiekoille, tasaisille korkeille kiekoille.", "Heikkoudet: vaikein oppia; ampujan on tiedettävä kiekon nopeus ja linja etukäteen; ja koska ase ei ole kiekkoa nopeampi, ampuja näkee suurimman välin ja houkuttuu mittaamaan sitä, hidastamaan ja pysähtymään.", "Valmentajat sanovat ”insert the gun in front” (vie ase eteen), ”stay ahead of it” (pysy sen edellä), ”match its speed” (liiku sen nopeudella)."], "key_points": ["Piipunsuut lähtevät edeltä ja liittyvät linjalle kiekon eteen.", "Aseen nopeus = kiekon nopeus; väli pysyy vakiona.", "Liipaisu, kun väli on oikea ja ase liikkuu; sitten saatto.", "Paras kaukaisiin, ennustettaviin kiekkoihin.", "Suurin riski: välin mittaaminen ja aseen pysäyttäminen."], "terms": ["maintained-lead", "insertion-point", "hold-point", "gun-speed", "follow-through", "crosser"], "sources": [{"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shotgun Sports USA — How to read sporting clays targets (insertion point)", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "muzzle_start": "ahead", "gun_speed": "equal", "trigger": "gap-held", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Get in front and stay in front.", "meaning": "Vie piipunsuut kiekon eteen ja pidä ne siellä laukauksen jälkeenkin.", "say": "Mene eteen ja pysy edessä."}, {"en": "Your insertion point is behind the bird — put the gun in front of it.", "meaning": "Piipunsuut liittyivät linjalle kiekon taakse; niiden on liityttävä sen eteen.", "say": "Sisäänvientisi on kiekon takana – vie ase sen eteen."}, {"en": "Match its speed — don't let it catch you.", "meaning": "Liikuta asetta kiekon nopeudella, jotta väli ei kutistu.", "say": "Liiku sen nopeudella – älä päästä sitä kiinni."}, {"en": "You're measuring it — trust the picture and pull.", "meaning": "Ampuja hidastaa tarkistaakseen välin; laukaise heti, kun kuva on oikea.", "say": "Mittaat sitä – luota kuvaan ja laukaise."}], "quiz": [{"q": "Pysyvässä ennakossa, missä kohdassa piipunsuut liittyvät kiekon linjalle?", "options": ["Kiekon takana", "Kiekon kohdalla", "Kiekon edessä", "Heittimen alapuolella"], "answer": 2, "why": "Piipunsuut viedään kiekon eteen ja ne pysyvät edellä; takaa on läpiveto, kiekon kohdalta edestä irtiveto."}, {"q": "Mikä on pysyvää ennakkoa käyttävien ampujien tyypillinen virhe?", "options": ["Aloittaminen liian kaukaa takaa", "Välin mittaaminen ja aseen pysäyttäminen", "Nosto lonkalta", "Liian aikainen laukaus heittimelle"], "answer": 1, "why": "Väli on suuri ja näkyvä, joten ampujat houkuttuvat tarkistamaan sen; ase hidastuu tai pysähtyy, ja laukaus menee taakse."}, {"q": "Mihin kiekkoon pysyvää ennakkoa suositellaan usein?", "options": ["Kaukaiseen, ennustettavaan sivukiekkoon", "Pomppivaan jäniskiekkoon lyhyessä aukossa", "Yllättävään takaa tulevaan kiekkoon", "ZZ-kiekkoon"], "answer": 0, "why": "Menetelmä vaatii tunnetun nopeuden ja linjan, jotka kaukaiset, tasaiset sivukiekot antavat; epäsäännöllisiin tai yllättäviin kiekkoihin sopivat muut menetelmät."}]}, {"id": "lead-swing-through", "minutes": 5, "title": "Läpiveto: takaa, kiekon läpi", "body": ["Swing-throughissa (läpiveto, myös ”takaa ohi”) piipunsuut lähtevät kiekon takaa ja ohittavat sen. Suomeksi voit kuulla myös pelkän englanninkielisen sanan swing-through.", "Miltä se näyttää vaihe vaiheelta. 1) Aloitus: piipunsuut liittyvät kiekon linjalle sen taakse, sen pyrstöön. 2) Ohitus: ase liikkuu kiekkoa nopeammin, sen linjaa pitkin, sen rungon läpi. 3) Laukaus: liipaisinta painetaan, kun piipunsuut ohittavat kiekon etureunan, juuri sen edellä. Koska päätöksen ja laukauksen välillä on pieni viive ja ase liikkuu kiekkoa nopeammin, piipunsuut ovat jo kauempana edellä haulien lähtiessä: todellinen ennakko laukaushetkellä on suurempi kuin ampujan näkemä ennakko, ja väliä näkyy vähän tai ei lainkaan. 4) Aseen liike jatkuu laukauksen jälkeen. Muistisääntö on ”butt, belly, beak, bang”: pyrstö, vatsa, nokka, pam. Brittienglanniksi voit kuulla sanan ”butt” sijaan ”bum”; käännä se sanalla ”pyrstö”.", "Vahvuudet: luonteva ja nopea; hyvä aloittelijoille, läheisille nopeille kiekoille, ylilentäville ja yli tuleville kiekoille sekä epäsäännöllisille tai yllättäville kiekoille.", "Heikkoudet: hyvin lyhyt aikaikkuna liipaisulle; kaukaisissa sivukiekoissa ampujalta voi loppua aika, hän voi kadottaa linjan tai mennä yli; hidastaminen piipunsuiden saavuttaessa kiekon tuottaa ohilaukauksen taakse.", "Lähteet ovat eri mieltä nimestä ”CPSA method”: jotkut kuvaavat sen läpivedoksi, kun taas nykyisen CPSA-valmennuksen kerrotaan opettavan edestä irtivetoa. Jos valmentaja sanoo ”CPSA method”, kysy, kumpaa hän tarkoittaa."], "key_points": ["Piipunsuut lähtevät takaa, kiekon linjalta.", "Ase kiekkoa nopeampi: pyrstö, vatsa, nokka, pam.", "Liipaisu piipunsuiden ohittaessa etureunan; todellinen ennakko on suurempi kuin nähty.", "Hyvä läheisiin, nopeisiin, ylilentäviin ja yllättäviin kiekkoihin; vaikeampi kaukaisissa sivukiekoissa.", "”CPSA method” on monitulkintainen: kysy, mitä menetelmää tarkoitetaan."], "terms": ["swing-through", "gun-speed", "perceived-lead", "driven-target", "overhead", "follow-through"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}], "sim": {"type": "lead", "method": "swing-through", "preset": "crosser-lr", "muzzle_start": "behind", "gun_speed": "faster", "trigger": "passing-front", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Come from behind, through the bird, and shoot as you see daylight.", "meaning": "Aloita kiekon takaa, vie ase sen läpi ja laukaise, kun eteen ilmestyy rako.", "say": "Tule takaa, kiekon läpi, ja ammu, kun näet valoa välissä."}, {"en": "Butt, belly, beak, bang.", "meaning": "Muistisääntö: kiekon pyrstö, vatsa, nokka ja sitten laukaus.", "say": "Pyrstö, vatsa, nokka, pam."}, {"en": "You slowed down as you got to it.", "meaning": "Ase menetti vauhtia saavuttaessaan kiekon, joten laukaus meni taakse.", "say": "Hidastit, kun pääsit sen kohdalle."}, {"en": "Brush it out and keep going.", "meaning": "Vie ase kiekon läpi kuin pyyhkisit sen taivaalta, pysähtymättä.", "say": "Pyyhi se pois ja jatka liikettä."}], "quiz": [{"q": "Mistä piipunsuut lähtevät läpivedossa?", "options": ["Kiekon edestä", "Kiekon etureunasta", "Kiinteästä kohdasta osumapisteessä", "Kiekon takaa, sen linjalta"], "answer": 3, "why": "Läpiveto lähtee takaa ja ohittaa kiekon; edestä lähteminen on pysyvä ennakko, kiinteä kohta on väijytys."}, {"q": "Miksi läpivetoa käyttävä ampuja näkee vähän tai ei lainkaan ennakkoa?", "options": ["Kiekot ovat aina hitaampia", "Aseen nopeus luo ennakon", "Säännöt kieltävät näkyvän välin", "Ampuja sulkee molemmat silmät"], "answer": 1, "why": "Ase liikkuu kiekkoa nopeammin, joten päätöksen ja laukauksen välillä se kulkee itsestään edelle."}, {"q": "Valmentaja sanoo ”bum, belly, beak, bang”. Miten sinun pitäisi kääntää ”bum”?", "options": ["Sanalla ”pyrstö” (tail)", "Karkealla sanalla, kirjaimellisesti", "Sanalla ”pum” (ääni)", "Jättää se kokonaan pois"], "answer": 0, "why": "Se tarkoittaa kiekon pyrstöä; neutraali ”pyrstö” säilyttää merkityksen ja muistisäännön rytmin."}]}, {"id": "lead-pull-away", "minutes": 5, "title": "Edestä irtiveto: kiinni, mukana, irti, laukaus", "body": ["Pull-awayssa (edestä irtiveto; itse irtautumista voidaan kutsua myös ”irtivedoksi”) piipunsuut liittyvät ensin kiekkoon ja vetäytyvät sitten sen edelle. Sitä opetetaan laajasti nykyaikaisessa brittiläisessä valmennuksessa, ja sitä kutsutaan nykyään usein CPSA-menetelmäksi.", "Miltä se näyttää vaihe vaiheelta. 1) ”On it” (kiinni): ase nostetaan kiekkoon tai sen etureunaan; piipunsuut koskettavat sitä sen linjalla. 2) ”With it” (mukana): piipunsuut seuraavat kiekkoa hetken sen nopeudella, linja ja tahti samana. 3) ”Pull away” (irti): ase kiihtyy tasaisesti edelle, kunnes oikea ennakkokuva ilmestyy. 4) ”Shoot” (laukaus): liipaisinta painetaan, kun ase vielä kiihtyy tai liikkuu. 5) Saatto: ase jatkaa liikettä laukauksen jälkeen.", "Vahvuudet: kiekon seuraaminen ensin antaa ampujan arvioida sen nopeuden, etäisyyden ja linjan ennen sitoutumista, joten linja on hyvä. Se sopii kaukaisille kiekoille, viistokiekoille ja nouseville kiekoille. Kiihdytyksen vuoksi havaittu ennakko on pienempi kuin pysyvässä ennakossa.", "Heikkoudet: kiihdytyksen määrä vaihtelee kiekosta toiseen, joten sen tunteminen vaatii harjoittelua; liian pitkä seuraaminen muuttuu kiekon perässä roikkumiseksi (riding the target), ja työnnön pysäyttäminen tuottaa ohilaukauksen taakse.", "Valmentajat sanovat ”touch it and go”, ”mount on it and push out” tai neljän tahdin ”on it, with it, pull away, shoot”. Säilytä neljän tahdin rytmi kääntäessäsi: se on tärkeämpi kuin tarkat sanat."], "key_points": ["Piipunsuut lähtevät kiekosta (tai sen etureunasta).", "Seuraa sen nopeudella, sitten kiihdytä edelle.", "Liipaisu, kun ase vielä liikkuu eteenpäin; sitten saatto.", "Hyvä linjan hallinta; sopii kaukaisiin, viisto- ja nouseviin kiekkoihin.", "Säilytä neljän tahdin rytmi kääntäessäsi."], "terms": ["pull-away", "insertion-point", "gun-speed", "perceived-lead", "quartering-away", "follow-through"], "sources": [{"title": "CPSA — How to hit series (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/how-to-hit-series-3"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "muzzle_start": "on-target", "gun_speed": "equal-then-faster", "trigger": "during-acceleration", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "On it, with it, pull away, shoot.", "meaning": "Liity kiekkoon, seuraa sitä, kiihdytä edelle, laukaise.", "say": "Kiinni, mukana, irti, laukaus."}, {"en": "Touch it and go.", "meaning": "Kohtaa kiekko piipunsuilla ja aloita heti irtiveto edelle.", "say": "Kosketa ja lähde."}, {"en": "You rode it too long.", "meaning": "Ampuja seurasi kiekkoa liian kauan ennen irtivetoa ja kadotti linjan tai hetken.", "say": "Roikuit sen perässä liian kauan."}, {"en": "Mount on it and push out a bit more.", "meaning": "Nosta ase kiekkoon ja vedä sitten hieman pidemmälle edelle ennen laukausta.", "say": "Nosta siihen kiinni ja työnnä vähän pidemmälle eteen."}], "quiz": [{"q": "Mitä edestä irtivedossa tapahtuu juuri ennen liipaisua?", "options": ["Ase pysähtyy kiekkoon", "Ase kiihtyy kiekon edelle", "Ase laskee kiekon alapuolelle", "Ase odottaa osumapisteessä"], "answer": 1, "why": "Itse irtiveto on kiihdytys edelle; laukaus ammutaan, kun ase vielä liikkuu eteenpäin."}, {"q": "Valmentaja sanoo ”You rode it too long”. Mikä meni vikaan?", "options": ["Hän seisoi liian kauan ampumapaikalla ennen kiekon pyytämistä", "Hän nosti aseen aivan liian aikaisin", "Hän seurasi kiekkoa liian kauan ennen irtivetoa", "Heittäjä lähetti kiekon myöhään"], "answer": 2, "why": "Kiekon perässä roikkuminen tarkoittaa, että sitä seurataan liian kauan, jolloin se hidastuu, laskee tai karkaa ja linja katoaa."}, {"q": "Pysyvään ennakkoon verrattuna havaittu ennakko edestä irtivedossa on yleensä…", "options": ["pienempi, koska kiihdytys lisää ennakkoa", "suurempi, koska ase lähtee kiekosta", "aina täsmälleen kaksinkertainen", "nolla jokaisessa kiekossa"], "answer": 0, "why": "Lyhyt kiihdytys kuljettaa asetta eteenpäin laukauksen viiveen aikana, joten väliä tarvitsee nähdä vähemmän."}]}, {"id": "lead-ambush-instinctive", "minutes": 5, "title": "Väijytys ja vaistonvarainen ammunta", "body": ["Ambush eli spot shooting (väijytys, pisteeseen ampuminen) on aseen heilautuksen vastakohta. 1) Piipunsuut asetetaan kiekon edelle sen linjalle, lähelle osumapistettä. 2) Ne odottavat vähällä liikkeellä tai liikkumatta. 3) Liipaisinta painetaan, kun kiekko saapuu tähän kohtaan.", "Yleisenä tapana, tyypillisenä kouluttamattomille ampujille, se on epäluotettava: ase on paikallaan ja ajoituksen on oltava täydellinen. Mutta tietoinen väijytys on joskus oikea valinta: kiekko, joka on ammuttava hyvin nopeasti, tai jäniskiekko, joka näkyy vain lyhyessä aukossa pensaiden välissä. Sukua tälle on syrjällään lentävissä battue-kiekoissa niiden lakipisteessä käytetty ”collapse”: pidä ase hyvin lähellä osumapistettä ja tee minimaalinen liike. Kiekko on silti rikottava paikassa, jossa tuomari näkee sen.", "Vaistonvarainen ammunta (instinctive shooting) tarkoittaa, ettei ennakkoa ajatella tietoisesti lainkaan. Ampuja pitää tarkan katseen kiekossa ja antaa käsien seurata; aseen liike ja nosto tapahtuvat yhdessä, ja laukaus lähtee, kun ase saavuttaa kasvot. Klassinen koulukunta liitetään englantilaiseen aseseppä Robert Churchilliin, ja se on suosittu metsästysammunnassa.", "Monet Parcours de Chasse – Sporting™ -lajin huippuampujat yhdistelevät menetelmiä ja valitsevat ne kiekkokohtaisesti. ”Which method for this one?” – mikä menetelmä tähän? – on tavallinen valmennuskysymys."], "key_points": ["Väijytys: piipunsuut paikallaan edellä olevassa kohdassa; laukaus kiekon saapuessa.", "Epäluotettava tapana, hyödyllinen tietoisesti (hyvin nopeat kiekot, lyhyet aukot).", "”Collapse”: minimaalinen liike osumapisteen lähellä syrjällään lentävissä battue-kiekoissa.", "Vaistonvarainen: ei tietoista ennakkoa, tarkka katse, nosto ja liike yhdessä (Churchillin koulukunta).", "Hyvät ampujat valitsevat menetelmän kiekkokohtaisesti."], "terms": ["ambush", "instinctive-shooting", "hard-focus", "break-point", "battue", "rabbit"], "sources": [{"title": "Wikipedia — Clay pigeon shooting (methods)", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}, {"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "Shotgun Life — Wingshooting schools of England", "url": "https://www.shotgunlife.com/travel/places-to-shoot/wingshooting-schools-of-england-3.html"}], "sim": {"type": "lead", "method": "ambush", "preset": "rabbit", "muzzle_start": "at-break-point", "gun_speed": "none-or-minimal", "trigger": "target-arrives", "follow_through": false}, "rule_refs": [{"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "You're ambushing it — keep the gun moving with the target.", "meaning": "Ampuja odottaa yhdessä kohdassa; valmentaja haluaa tässä liikkuvan menetelmän.", "say": "Väijyt sitä – pidä ase liikkeessä kiekon mukana."}, {"en": "Ambush this one in the gap.", "meaning": "Odota tietoisesti aukon kohdalla ja laukaise, kun kiekko ylittää sen.", "say": "Väijy tämä aukossa."}, {"en": "Don't think about the lead, just look at the bird and let the gun go to it.", "meaning": "Ammu vaistonvaraisesti: keskity kiekkoon ja anna käsien seurata.", "say": "Älä mieti ennakkoa, katso vain kiekkoa ja anna aseen mennä sen luo."}, {"en": "Hold right on the break point and just collapse onto it.", "meaning": "Vie piipunsuut lähes osumapisteeseen ja tee vain pieni liike battue-kiekon saapuessa.", "say": "Pidä ase suoraan osumapisteessä ja vain painu siihen."}], "quiz": [{"q": "Mikä on väijytykselle (spot shooting) ominaista?", "options": ["Ase liikkuu kiekkoa nopeammin", "Ase odottaa kohdassa kiekon edellä", "Ase seuraa kiekkoa ja kiihtyy sitten", "Ase lähtee kiekon takaa sen linjalta"], "answer": 1, "why": "Väijytys tarkoittaa vähäistä tai olematonta aseen liikettä: piipunsuut odottavat linjalla ja kiekko lentää laukaukseen."}, {"q": "Milloin tietoinen väijytys voi olla hyvä valinta?", "options": ["Jokaisessa kaukaisessa, tasaisessa sivukiekossa", "Ei koskaan: säännöt kieltävät sen", "Vain Compak® Sporting -lajissa, ei koskaan Sporting™-lajissa", "Jäniskiekossa, joka näkyy vain lyhyessä aukossa"], "answer": 3, "why": "Kun kiekko näkyy vain hetken, aseen heilautukseen ei ole aikaa, joten aukossa odottaminen voi toimia. Mikään sääntö ei kiellä mitään menetelmää."}, {"q": "Mitä on vaistonvarainen ammunta?", "options": ["Tarkka katse kiekkoon, ei tietoista ennakkoa", "Ampumista ilman ampumalaseja", "Ampumista lonkalta ilman nostoa", "Odottamista heittimellä jokaista kiekkoa varten"], "answer": 0, "why": "Vaistonvarainen ammunta perustuu silmän ja käden koordinaatioon; se tehdään silti ase olalla, kuten säännöt edellyttävät."}]}, {"id": "lead-how-coaches-say-it", "minutes": 6, "title": "Miten valmentajat ilmaisevat ennakon ja miten se käännetään", "body": ["Yksiköt. Brittiläiset ja amerikkalaiset valmentajat puhuvat jaloista ja jaardeista: ”give it four foot” (brittiläinen muoto, neljä jalkaa), ”two feet in front”. Eurooppalaiset valmentajat käyttävät metrejä. Yksi jalka on noin 30 cm, yksi jaardi noin 0,9 m. Mutta ennakon luku on valmentajan kuva, ei mittaus, joten säilytä hänen lukunsa ja yksikkönsä. Älä koskaan muunna kesken ohjeen; jos ampuja kysyy, selitä suunnilleen kiekkojen välillä. Etäisyydet kiekkoon (”it's 30 yards”) voi antaa muodossa ”noin 27 m”.", "Kiekon leveydet: ”half a bird”, ”a bird's width”, ”a clay's length”. Bird tarkoittaa kiekkoa, ei koskaan oikeaa lintua: ”puoli kiekkoa”. Piipun leveydet: ”a barrel's width”, ”two barrels” tarkoittavat piipunsuulla nähtyä väliä. Varo: tuomarin ”two barrels” tarkoittaa, että molemmat piiput laukesivat samanaikaisesti.", "Suhteelliset sanat: ”more”, ”less”, ”a touch more”, ”double it”, ”half that”, ”same lead”. Pidä ne suhteellisina äläkä koskaan keksi lukua. ”Same lead” on elintärkeä: ampuja ei saa lisätä ennakkoa.", "Suunnat: ”in front” ja ”behind” viittaavat kiekon kulkusuuntaan; ”over” ja ”high”, ”under” ja ”low” ovat synonyymejä. Kellotaulu kuvaa sijainteja: kello 12 on ylhäällä, kello 3 oikealla, ampujan näkökulmasta. ”You hit it at six” tarkoittaa alareunaa; ”it comes from eleven” antaa suunnan.", "Menetelmä: käännä luku, yksikkö, vertailukohta ja suunta täsmälleen, lyhyesti, valmentajan rytmissä. Jos jokin on epäselvää, kysy häneltä yhdellä sanalla: ”Feet?” Kilpailuissa valmentaminen on kielletty."], "key_points": ["Säilytä valmentajan luku ja yksikkö; älä koskaan muunna ennakkoa kesken ohjeen.", "Bird = kiekko: ”half a bird” = ”puoli kiekkoa”.", "Suhteelliset sanat pysyvät suhteellisina; ”same lead” on käännettävä.", "Kellotaulu: 12 ylhäällä, 3 oikealla, ampujan näkökulmasta.", "Tuomarin ”two barrels” tarkoittaa molempien piippujen samanaikaista laukeamista, ei ennakkoa."], "terms": ["lead", "perceived-lead", "clock-face", "double-discharge", "coach"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "Shooting UK — The overhead clay from behind (clock-face pick-up)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-rl", "focus": "lead-units"}, "rule_refs": [{"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Give it four foot.", "meaning": "Anna ennakko, jota valmentaja kutsuu ”neljäksi jalaksi”; se kuvaa hänen kuvaansa, joten säilytä hänen lukunsa ja yksikkönsä.", "say": "Anna sille neljä jalkaa."}, {"en": "Half a bird more.", "meaning": "Lisää ennakkokuvaan puolen kiekon leveys.", "say": "Puoli kiekkoa lisää."}, {"en": "Double it.", "meaning": "Tee ennakkokuvasta kaksi kertaa niin suuri kuin viime kerralla.", "say": "Tuplaa se."}, {"en": "Same lead, just keep it moving.", "meaning": "Ennakko oli oikea; ohilaukaus johtui aseen pysäyttämisestä.", "say": "Sama ennakko, pidä vain ase liikkeessä."}, {"en": "You were at two o'clock — a touch low and more in front.", "meaning": "Osumakuvio oli kellotaululla kiekon yläpuolella ja oikealla; ammu hieman alemmas ja anna vähän enemmän ennakkoa.", "say": "Olit kello kahdessa – hitusen alemmas ja enemmän eteen."}, {"en": "A barrel's width in front.", "meaning": "Pidä kiekon edellä väli, joka on piipunsuulla nähtynä piipun levyinen.", "say": "Piipun leveys eteen."}], "quiz": [{"q": "Valmentaja sanoo ”Give it four foot” ampujalle, joka ajattelee metreinä. Mitä sanot?", "options": ["”Anna 1,22 metriä”", "”Anna noin metri”", "”Anna neljä jalkaa”", "”Anna neljä metriä”"], "answer": 2, "why": "Ennakon luku on valmentajan kuva; sen muuntaminen kesken ohjeen lisää näennäistä tarkkuutta tai virheitä, ja ”neljä metriä” muuttaa merkityksen täysin. Jos ampuja kysyy, selitä suunnilleen kiekkojen välillä."}, {"q": "Mitä ”half a bird” tarkoittaa?", "options": ["Puolta kiekon leveydestä", "Rikkoutunutta kiekkoa", "Pientä lintua, joka lentää heittimen lähellä", "Puolta kierroksesta"], "answer": 0, "why": "Kiekkoammunnassa ”bird” tarkoittaa kiekkoa, joten valmentaja pyytää puolen kiekon leveyden ennakkoa."}, {"q": "Valmentaja sanoo ”Same lead, keep it moving”. Miksi ”same lead” on käännettävä?", "options": ["Se on tuomarin käyttämä huuto", "Muuten ampuja saattaa lisätä ennakkoa ja ampua ohi", "Se on ampujien kohtelias tervehdys", "Se muuttaa kiekkojen järjestystä"], "answer": 1, "why": "Ohilaukauksen jälkeen useimmat ampujat lisäävät ennakkoa itsestään; ”same lead” kertoo heille, että syy oli pysähtynyt ase, ei ennakko."}]}]}, {"id": "faults", "icon": "search", "title": "Virheet ja miten valmentajat tunnistavat ne", "intro": "Kun kiekko menee ohi, valmentaja nimeää ohilaukauksen yhdellä tai kahdella sanalla ja sitten sen syyn. Tässä tehtävässä opit ohilaukausten ja virheiden sanat, mitä kukin oikeasti tarkoittaa ja miten välität valmentajan diagnoosin ampujalle nopeasti ja tarkasti.", "lessons": [{"id": "faults-behind-in-front", "minutes": 5, "title": "Takana, edessä, yli, ali, sirpale", "body": ["Jokaisella ohilaukauksella on suunta. Ampujan takaa seuraava valmentaja sanoo yleensä ensin, mihin laukaus meni kiekkoon nähden, ja vasta sitten miksi. Välitä se heti: ampuja valmistautuu jo seuraavaan kiekkoon.", "Behind (takana) tarkoittaa, että laukaus meni liikkuvan kiekon taakse: liian vähän ennakkoa tai hidastunut ase. Se on yleisin ohilaukaus sivukiekoissa. In front (edessä) on päinvastainen: liikaa ennakkoa, usein sen jälkeen, kun ampuja on ylikorjannut. Monet valmentajat pitävät edestä ohi menneestä laukauksesta: se osoittaa, että ase pysyi liikkeessä.", "Over (myös ”high”, ”over the top”, eli yli) ja under (”low”, eli ali) kuvaavat pystysuuntaista ohilaukausta. Yli on yleinen laskevissa kiekoissa, jäniskiekoissa ja vastakiekoissa, ja se liittyy usein siihen, että pää nousee tukilta. Ali on tyypillinen nousevissa kiekoissa, jotka nousevat vielä laukaushetkellä.", "Chipped (sirpale irti) tarkoittaa, että kiekosta irtosi vain pieni pala. Valmentajalle se on puoliksi kehu, puoliksi korjaus: kiekko oli osumakuvion reunalla. Tuomarille se on osuma, kunhan pala on näkyvä. Ansa on pöly: sääntöjen mukaan kiekko, josta irtoaa vain pölyä tai savua ilman näkyvää palaa, on ohi. Silti valmentajien slangissa ”smoked it” tarkoittaa täydellistä, keskitettyä osumaa, ja ”dusted it” kuullaan kummassakin merkityksessä, joten kysy, jos olet epävarma.", "Säilytä valmentajan järjestys: suunta, syy, korjaus. Jos valmentaja sanoo ”behind, you stopped”, syy on tärkeämpi: ampuja, joka kuulee vain ”takana”, lisää ennakkoa, mikä ei korjaa pysähtynyttä asetta."], "key_points": ["Välitä ensin suunta: takana, edessä, yli, ali.", "Takana = liian vähän ennakkoa tai hidastuva ase; edessä = liikaa ennakkoa.", "Näkyvä sirpale on tuomarille osuma; pelkkä pöly tai savu on ohi.", "”Smoked it” on valmentajan kehu, ei sääntöjen ”savu”: älä koskaan sekoita niitä.", "Säilytä valmentajan järjestys: suunta, syy, korjaus."], "terms": ["lead", "crosser", "dropping-target", "visible-piece", "one", "zero", "miss-behind", "miss-in-front", "miss-over", "miss-under", "chip", "smoke-ball"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}], "coach_says": [{"en": "Behind, give it more.", "meaning": "Laukaus meni kiekon taakse; lisää ennakkoa.", "say": "Takana, anna lisää."}, {"en": "Just over the top, it was already dropping.", "meaning": "Laukaus meni yli, koska kiekko oli jo laskemassa; ammu alemmas ja eteen.", "say": "Juuri yli, se oli jo laskemassa."}, {"en": "In front this time, good, now a touch less.", "meaning": "Liikaa ennakkoa, mutta ase liikkui; vähennä ennakkoa hieman.", "say": "Tällä kertaa edessä, hyvä, nyt hitusen vähemmän."}, {"en": "You just chipped it, a little more in front.", "meaning": "Osuma osumakuvion reunalla; vähän lisää ennakkoa keskittää sen.", "say": "Sait siitä vain sirpaleen, vähän enemmän eteen."}, {"en": "Smoked it! Same again.", "meaning": "Täydellinen keskitetty osuma (slangia, ei sääntöjen ”savu”); toista täsmälleen samoin.", "say": "Pölyksi! Samoin uudestaan."}, {"en": "Behind, but you stopped, so don't just add lead.", "meaning": "Syy on pysähtynyt ase; pelkkä lisäennakko ei auta.", "say": "Takana, mutta pysäytit, joten älä vain lisää ennakkoa."}], "quiz": [{"q": "Valmentaja huutaa: ”Behind, you stopped!” Mikä on tärkein käännettävä osa?", "options": ["Syy: ase pysähtyi", "Vain suunta ”takana”", "Ei mitään: ampuja näki ohilaukauksen", "Pyyntö lisätä paljon ennakkoa"], "answer": 0, "why": "Ennakon lisääminen ei korjaa pysähtynyttä asetta; syy on se, mikä ampujan on korjattava."}, {"q": "Kiekosta irtoaa pieni mutta selvästi näkyvä pala. Valmentaja sanoo ”just chipped it”. Miten tuomari merkitsee sen?", "options": ["Ohi, koska suurin osa kiekosta lensi eteenpäin", "No Bird", "Osuma", "Osuma vain, jos valmentaja on samaa mieltä"], "answer": 2, "why": "Vähintään yksi näkyvä pala tekee kiekosta osuman sekä Sporting™- että Compak® Sporting -lajissa; tuomari päättää yksin."}, {"q": "Osuman jälkeen valmentaja huudahtaa ”Smoked it!”. Mitä hän tarkoittaa?", "options": ["Kiekosta irtosi vain pölyä, joten se on ohi", "Täydellinen, keskitetty osuma", "Se oli pölykiekko", "Ampujan pitäisi vaihtaa patruunoita"], "answer": 1, "why": "Valmentajien slangissa ”smoked it” on kehu pölyksi ammutusta kiekosta; säännöissä pöly tai savu ilman näkyvää palaa on ohilaukaus."}]}, {"id": "faults-head-lift-stopping", "minutes": 5, "title": "Pään nosto, pysäyttäminen, roikkuminen, tökkääminen", "body": ["Suunnan jälkeen valmentaja nimeää syyn. Neljä syytä toistuu joka harjoituspäivä, ja jokaisella on oma lyhyt sanansa. Opettele ne pareittain: virhe ja korjaus.", "Head lift (pään nostaminen tukilta): poski irtoaa tukista laukaushetkellä tai juuri ennen sitä, usein siksi, että ampuja haluaa nähdä kiekon hajoavan. Silmä on takatähtäin, joten sen nouseminen siirtää kuvaa, ja laukaus menee yleensä yli. Korjaus: ”head down”, ”cheek on the stock”, ”stay in the gun” – pää alas, poski tukille, pysy aseessa.", "Stopping the gun (aseen pysäyttäminen): piipunsuut pysähtyvät laukaukseen, yleensä siksi, että ampuja tarkistaa ennakon piipusta. Laukaus menee taakse. Lievempi muoto on checking: aseen liike epäröi sekunnin murto-osan. Korjaus: ”keep the gun moving”, ”follow through”, ”finish the shot” – pidä ase liikkeessä, saatto, vie laukaus loppuun.", "Riding the target (kiekon perässä roikkuminen): kiekkoa seurataan liian kauan ennen laukausta, joten se hidastuu, laskee tai kaartaa pois, ja ampuja kadottaa linjan. Korjaus: ”take it earlier”, ”commit to it” – ota aikaisemmin, sitoudu laukaukseen. Poking (myös ”aiming”, ”measuring”, eli tökkääminen, tähtääminen): haulikkoa osoitetaan hitaasti kuin kivääriä, katse jyvässä eikä kiekossa. Se on tyypillistä, kun osumapiste on liian lähellä, tai pystykiekossa (teal) lakipisteessä. Korjaus: ”eyes on the clay”, ”let the gun go” – katse kiekkoon, anna aseen mennä.", "Valmentajat nimeävät syyn usein ennen kuin ampuja on edes laskenut aseensa. Käännä se samalla hengenvedolla ja samalla verbillä: ”you stopped” ei ole ”ammuit ohi”. Sana kuten ”aiming” on lähes aina arvostelua, joten älä koskaan muuta sitä neuvoksi kuten ”tähtää paremmin”."], "key_points": ["Pään nosto: laukaus yleensä yli; korjaus: pää alas, pysy aseessa.", "Pysäyttäminen tai epäröinti: laukaus taakse; korjaus: pidä ase liikkeessä, saatto.", "Roikkuminen: kiekko hidastuu tai laskee pois; korjaus: ota aikaisemmin, sitoudu.", "Tökkääminen tai tähtääminen: hidas kiväärimäinen osoittaminen; korjaus: katse kiekkoon.", "Käännä syy heti, valmentajan omalla verbillä."], "terms": ["head-lift", "stopping-the-gun", "follow-through", "break-point", "teal", "checking", "riding-the-target", "poking"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "The Field — Improve your game and clay shooting: 20 top tips", "url": "https://www.thefield.co.uk/shooting/improve-your-game-and-clay-shooting-20-top-tips-45462"}, {"title": "Clay Target Nation — 5 major shooting mistakes", "url": "https://www.claytargetnation-digital.com/articles/5-major-shooting-mistakes"}], "sim": null, "rule_refs": [], "coach_says": [{"en": "You lifted your head, that's why it went over.", "meaning": "Poski irtosi tukista, joten laukaus meni kiekon yli.", "say": "Nostit pään, siksi se meni yli."}, {"en": "Keep the gun moving, you stopped on it.", "meaning": "Aseen liike pysähtyi laukaukseen; jatka liikettä laukauksen läpi ja sen jälkeen.", "say": "Pidä ase liikkeessä, pysäytit sen kiekon kohdalle."}, {"en": "You checked just before the shot, commit to it.", "meaning": "Lyhyt epäröinti ennen laukausta; päätä ja ammu hidastamatta.", "say": "Epäröit juuri ennen laukausta, sitoudu siihen."}, {"en": "Stop aiming, look at the bird and let the gun go.", "meaning": "Arvostelua: ampuja osoittaa kuin kiväärillä; keskity kiekkoon ja anna aseen liikkua vapaasti.", "say": "Lopeta tähtääminen, katso kiekkoa ja anna aseen mennä."}, {"en": "You rode it too long, take it earlier.", "meaning": "Ampuja seurasi kiekkoa liian kauan; riko se aikaisemmin.", "say": "Roikuit sen perässä liian kauan, ota se aikaisemmin."}, {"en": "Stay in the gun.", "meaning": "Pidä poski tukilla vielä laukauksen jälkeenkin.", "say": "Pysy aseessa."}], "quiz": [{"q": "Valmentaja sanoo ”You lifted your head”. Mihin laukaus todennäköisimmin meni?", "options": ["Taakse", "Yli", "Ali", "Eteen"], "answer": 1, "why": "Silmä on takatähtäin: kun pää nousee, laukaus menee yleensä yli."}, {"q": "Valmentaja huutaa ”Stop aiming!”. Mitä hän haluaa?", "options": ["Älä osoita kuin kiväärillä: katso kiekkoa ja liikuta asetta", "Tähtää tarkemmin", "Lopeta ampuminen heti", "Laske ase"], "answer": 0, "why": "Valmentajan suussa ”aiming” on virhe (tökkääminen); korjaus on katse kiekkoon ja vapaa aseen liike."}, {"q": "”You rode it too long” tarkoittaa…", "options": ["Ampuja laukaisi liian aikaisin", "Heitin oli liian hidas", "Ampuja aloitti liian kaukaa takaa", "Ampuja seurasi kiekkoa liian kauan ennen laukausta"], "answer": 3, "why": "Kiekon perässä roikkuminen tarkoittaa, että sitä seurataan liian kauan, joten se hidastuu tai laskee ja linja katoaa."}]}, {"id": "faults-mount-errors", "minutes": 5, "title": "Noston virheet: myöhäinen, kasvot aseelle, kallistus", "body": ["Moni ohilaukaus alkaa jo ennen aseen liikettä, aseen nostossa: liikkeessä, joka tuo aseen poskelle ja olalle. Valmentajan sanat sille ovat lyhyitä ja fyysisiä.", "Late mount (myöhäinen nosto): ase saavuttaa olan vasta sen hetken jälkeen, jolloin laukauksen olisi pitänyt lähteä, joten ampuja kiirehtii tai laukaisee ennen kuin poski on tukilla. Vastakkainen virhe on liian aikaisin valmis nosto, jonka jälkeen ase odottaa paikallaan raskaana. Korjaus: ”move, mount, shoot” – liike, nosto, laukaus: piipunsuut lähtevät kiekon mukana ja nosto valmistuu samalla kun laukaus lähtee.", "Face to the gun (kasvot aseelle): sen sijaan, että ampuja nostaisi tukin kasvoille, hän laskee pään tukkia vastaan. Silmä päätyy joka kerta eri kohtaan, ja rekyyli osuu poskeen. Valmentajat sanovat: ”bring the gun to your face, not your face to the gun” – ase kasvoille, ei kasvoja aseelle. Myös tukki, joka osuu käsivarteen olkataskun sijaan, sattuu.", "Canting (kallistus): ase on laukaushetkellä kallistunut sivulle, ja laukaus ajautuu pois linjalta. Siihen liittyy usein laskenut olkapää. Korjaus: ”keep the gun level”, ”turn from the hips” – pidä ase suorassa, käänny lantiosta.", "FITASCin Parcours de Chasse – Sporting™ -kilpailuissa asetta ei saa nostaa ennen kuin kiekko ilmestyy, joten ”pre-mount this one” on vain harjoite. Liian aikainen nosto Sporting™-kilpailussa tuo varoituksen ja keltaisen kortin. Compak® Sporting -lajissa ase saa olla olalla jo kiekkoa pyydettäessä. Käännä harjoite harjoitteena äläkä lisää mitään omaasi."], "key_points": ["Myöhäinen nosto: kiirehditty laukaus; korjaus: liike, nosto, laukaus.", "Kasvot aseelle: silmä liikkuu ja rekyyli sattuu; tuo ase kasvoille.", "Kallistus: laukaus ajautuu pois linjalta; pidä ase suorassa, käänny lantiosta.", "Valmiiksi nostettu ase on harjoite: ei sallittu ennen kiekon ilmestymistä Sporting™-kilpailussa, sallittu kiekkoa pyydettäessä Compak® Sporting -lajissa."], "terms": ["gun-mount", "ready-position", "recoil", "comb", "gun-fit", "dry-mounting", "late-mount", "canting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Bring the gun to your face, not your face to the gun.", "meaning": "Nosta tukki poskelle; älä laske päätä tukille.", "say": "Tuo ase kasvoille, älä kasvoja aseelle."}, {"en": "Move, mount, shoot, all in one.", "meaning": "Lähde liikkeelle kiekon mukana ja vie nosto loppuun laukaistessasi, yhtenä sujuvana liikkeenä.", "say": "Liike, nosto, laukaus, kaikki yhdessä."}, {"en": "You canted the gun, keep it level.", "meaning": "Ase oli laukaushetkellä kallistunut sivulle.", "say": "Kallistit asetta, pidä se suorassa."}, {"en": "Mount on the line.", "meaning": "Aseen pitäisi nousta valmiiksi kiekon radalle.", "say": "Nosta linjalle."}, {"en": "Pre-mount this one, just for practice.", "meaning": "Harjoite ase valmiiksi olalla; ei sallittu Sporting™-kilpailussa.", "say": "Tämä ase valmiiksi olalla, ihan vain harjoituksena."}], "quiz": [{"q": "Harjoituksissa valmentaja sanoo FITASCin Sporting™-kilpailuun valmistautuvalle ampujalle: ”Pre-mount this one.” Mikä pitää paikkansa?", "options": ["Se on sallittu kaikissa FITASCin kilpailuissa", "Tulkin pitäisi kieltäytyä kääntämästä sitä", "Se on harjoite; Sporting™-kilpailussa asetta ei saa nostaa ennen kuin kiekko ilmestyy", "Se tarkoittaa nostoa laukauksen jälkeen"], "answer": 2, "why": "Sporting™ edellyttää valmiusasentoa ase alhaalla, kunnes kiekko ilmestyy; valmiiksi nostettu ase kilpailussa tuo varoituksen ja keltaisen kortin."}, {"q": "”You canted the gun” tarkoittaa…", "options": ["Ase oli laukaushetkellä kallistunut sivulle", "Ase nostettiin liian myöhään", "Ase pysähtyi", "Varmistin oli päällä"], "answer": 0, "why": "Kallistus on aseen sivuttainen kallistuminen, joka vetää laukauksen pois linjalta."}, {"q": "Mikä ohje korjaa virheen ”kasvot aseelle”?", "options": ["Paina päätä alas voimakkaammin", "Tuo ase kasvoille", "Sulje toinen silmä", "Pidä asetta alempana käsivarrella"], "answer": 1, "why": "Tukin pitää nousta kasvoille, jotta silmä on joka kerta samassa kohdassa."}]}, {"id": "faults-pairs-transition", "minutes": 5, "title": "Kaksoiskiekot: toinen kiekko", "body": ["Kaksoiskiekossa (pari) moni ampuja rikkoo ensimmäisen kiekon ja ampuu toisen ohi. Valmentaja puhuu silloin siirtymästä (transition), liikkeestä ensimmäiseltä kiekolta toiselle, ja palautumisesta (recovery), aseen ja pään hallinnan palauttamisesta ensimmäisen laukauksen jälkeen.", "Kultainen sääntö on ”eyes first, then the gun” – ensin silmät, sitten ase. Silmät jättävät rikkoutuneen ensimmäisen kiekon ja etsivät toisen; ase seuraa. Ampuja, joka katsoo ensimmäisen kiekon hajoamista tai heilauttaa asetta ennen kuin on löytänyt toisen, menettää aikaa. Valmentajat sanovat ”eyes to the second” tai yksinkertaisesti osoittavat.", "Palautuminen: rekyyli nostaa piipunsuita ja joskus päätä. ”Let the gun recover, then go” tarkoittaa: poski takaisin tukille ja ase takaisin linjalle ennen kuin lähdet toisen kiekon perään. Hyvä ampuma-asento, jossa paino on edessä, nopeuttaa palautumista.", "Suunnittelu: kaksoiskiekkoa lukiessaan valmentaja päättää, kumpi kiekko otetaan ensin ja missä se rikotaan, jotta toinen on helppo löytää. Tyypillisiä ilmauksia: ”take the dropping one first” (ota laskeva ensin), ”break the first early” (riko ensimmäinen aikaisin), ”stick to the plan” (pysy suunnitelmassa). Ampuja, joka vaihtaa järjestystä ampumapaikalla, ”went for the wrong one” – otti väärän ensin.", "Säännöillä on tässä merkitystä. Parcours de Chasse – Sporting™ -lajissa aseen asento on vapaa minkä tahansa kaksoiskiekon kahden kiekon välillä, ja ampujalla on kaksoiskiekkoon kaksi patruunaa, jotka molemmat saa ampua samaan kiekkoon. Compak® Sporting -lajissa kaksoiskiekossa sallitaan vain yksi patruuna kiekkoa kohden. Älä selitä rangaistuksia itse: käännä valmentajan sanat ja jätä sääntökysymykset tuomarille."], "key_points": ["Ensin silmät, sitten ase.", "Palautuminen: poski takaisin tukille ja ase linjalle ennen toista kiekkoa.", "Valmentaja suunnittelee kaksoiskiekon järjestyksen ja osumapisteet sitä lukiessaan.", "Sporting™: aseen asento vapaa kiekkojen välillä, ja molemmat patruunat saa ampua yhteen kiekkoon; Compak® Sporting: yksi patruuna kiekkoa kohden."], "terms": ["double", "double-on-report", "simultaneous-double", "rafale-double", "recoil", "stance", "dropping-target", "transition", "recovery"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Eyes first to the second bird, then the gun.", "meaning": "Löydä toinen kiekko silmillä ennen kuin liikutat asetta.", "say": "Ensin silmät toiseen kiekkoon, sitten ase."}, {"en": "Let the gun recover, then go to the second.", "meaning": "Rekyylin jälkeen asetu, ase ja poski paikoilleen, ennen toista laukausta.", "say": "Anna aseen palautua, sitten toiseen."}, {"en": "Take the dropping one first.", "meaning": "Ammu ensin kiekko, joka katoaa tai putoaa aikaisimmin.", "say": "Ota laskeva ensin."}, {"en": "Don't watch the first one break.", "meaning": "Siirrä katse heti toiseen kiekkoon.", "say": "Älä jää katsomaan, kun ensimmäinen hajoaa."}, {"en": "You went for the wrong one first, stick to the plan.", "meaning": "Ampuja muutti suunniteltua järjestystä; tekniikkahuomautus, ei sääntörike.", "say": "Otit väärän ensin, pysy suunnitelmassa."}], "quiz": [{"q": "Mitä ”eyes first, then the gun” tarkoittaa kaksoiskiekossa?", "options": ["Sulje silmät ensimmäisen laukauksen jälkeen", "Katso piippua ennen toista laukausta", "Nosta ase ennen kaksoiskiekon pyytämistä", "Löydä toinen kiekko silmillä ennen kuin viet aseen sen luo"], "answer": 3, "why": "Hyvässä siirtymässä silmät johtavat ja ase seuraa."}, {"q": "Compak® Sporting -kaksoiskiekossa ampuja ampuu ensimmäisen kiekon ohi ja haluaa ampua myös toisen patruunan siihen. Onko se sallittua?", "options": ["Kyllä, kuten Sporting™-lajissa", "Kyllä, mutta vain yhtäaikaisessa kaksoiskiekossa", "Ei: Compak® Sporting -kaksoiskiekossa sallitaan vain yksi patruuna kiekkoa kohden", "Vain tuomarin luvalla"], "answer": 2, "why": "Compak® Sporting kieltää kaksoiskiekon ensimmäisen kiekon ampumisen kahdesti; Sporting™ sallii molemmat patruunat yhteen kiekkoon."}, {"q": "Saako ampuja Sporting™-kaksoiskiekossa laskea aseen ensimmäisen ja toisen kiekon välillä?", "options": ["Kyllä, aseen asento on vapaa kahden kiekon välillä", "Ei, aseen on pysyttävä olalla", "Vain laukauksesta lähtevässä kaksoiskiekossa", "Vain jos tuomari sallii"], "answer": 0, "why": "Vapaa asento koskee minkä tahansa kaksoiskiekon kiekkojen väliä, mutta ei aikaa ennen ensimmäistä kiekkoa."}]}, {"id": "faults-reading-the-coach", "minutes": 5, "title": "Valmentajan lukeminen: lyhyet käskyt ja merkit", "body": ["Ampumapaikalla valmentaja puhuu katkelmin: ”Behind.” ”Head.” ”More.” ”Again.” Kiekkojen välissä on vain muutama sekunti, joten lyhyys on tarkoituksellista. Käännöksesi pitää olla yhtä lyhyt; pitkä lause ehtii perille vasta seuraavan kiekon pyynnön jälkeen.", "Monet valmentajat kysyvät ennen kuin kertovat: ”Where did it go?” tai ”What did you see?” Tämä on opetuskysymys, ei tulkin koe. Käännä kysymys, anna ampujan vastata ja käännä vastaus takaisin täsmälleen, vaikka se kuulostaisi väärältä. Valmentajan on tiedettävä, mitä ampuja havaitsi.", "Käsimerkit kertovat paljon. Yleisiä ovat: kädet erkanevat tai lähenevät = enemmän tai vähemmän ennakkoa, alas liikkuva kämmen = ”alemmas”, napautus poskeen = ”pää alas”, sormi piirtää kiekon linjan, peukku ylös = ”samoin uudestaan”. Merkit vaihtelevat valmentajittain, joten sovi niistä ennen harjoitusta, äläkä käännä elettä, jonka ampuja on jo nähnyt.", "Jotkin sanat ovat pelkkää rytmiä ja kannustusta: ”commit”, ”trust it”, ”smooth”, ”good, same again”. Säilytä sävy. ”Bad luck” ohilaukauksen jälkeen on ystävällisyyttä, ei kommentti tuomarista.", "Kilpailussa valmentaminen on kielletty: tuomari antaa kilpailijalle keltaisen kortin ja lähettää valmentajan pois ampuma-alueelta. Säännöt eivät kerro, saako tulkki välittää valmentajan neuvoja kilpailun aikana: se on FITASCille avoin kysymys. Turvallinen käytäntö: kilpailussa tulkkaa vain tuomarille, jurylle ja järjestäjälle."], "key_points": ["Valmentajat puhuvat katkelmin; käännä yhtä lyhyesti.", "”Where did it go?” on opetuskysymys: käännä ampujan vastaus täsmälleen.", "Sovi käsimerkeistä ennen harjoitusta.", "Ei valmentamista kilpailussa; tulkkaa vain tuomarille, jurylle ja järjestäjälle."], "terms": ["coach", "referee", "jury", "yellow-card", "hand-signal"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Where did it go?", "meaning": "Valmentaja kysyy, mihin ampujan mielestä laukaus meni; opetuskysymys.", "say": "Mihin se meni?"}, {"en": "What did you see?", "meaning": "Kuvaile näkymä laukaushetkellä.", "say": "Mitä näit?"}, {"en": "More.", "meaning": "Asiayhteydessä lähes aina ”lisää ennakkoa”.", "say": "Lisää."}, {"en": "Good, same again.", "meaning": "Toista täsmälleen se, mitä juuri teit.", "say": "Hyvä, samoin uudestaan."}, {"en": "Trust it, commit to it.", "meaning": "Lopeta epäröinti; päätä ja laukaise.", "say": "Luota siihen, sitoudu."}, {"en": "Bad luck.", "meaning": "Myötätuntoa ohilaukauksen jälkeen; ei valitus tuomarista.", "say": "Huono tuuri."}], "quiz": [{"q": "Valmentaja kysyy ampujalta ”Where did it go?”. Mitä tulkin pitäisi tehdä?", "options": ["Vastata ampujan puolesta", "Kääntää kysymys ja sitten ampujan vastaus täsmälleen", "Selittää ohilaukaus omin sanoin", "Olla hiljaa: se on retorinen kysymys"], "answer": 1, "why": "Valmentaja haluaa kuulla ampujan oman havainnon, joten vastauksen on tultava hänelle muuttumattomana."}, {"q": "Kilpailun aikana ampujan valmentaja pyytää sinua välittämään: ”Give the next one more lead.” Mikä on turvallinen käytäntö?", "options": ["Välitä se hiljaa", "Välitä se vain ampumapaikkojen välillä", "Älä välitä valmennusta kilpailussa; tulkkaa vain tuomarille, jurylle ja järjestäjälle", "Kysy ensin muilta ampujilta"], "answer": 2, "why": "Valmentaminen kilpailussa on kielletty, eivätkä säännöt kerro, saako tulkki välittää sitä; siitä pidättäytyminen suojaa ampujaa."}, {"q": "Mitä sääntöjen mukaan tapahtuu, jos tuomari katsoo, että kilpailijaa valmennetaan?", "options": ["Keltainen kortti kilpailijalle; valmentaja lähetetään pois ampuma-alueelta", "Ei mitään: valmentaminen on sallittua", "Kiekko uusitaan", "Koko erä hylätään"], "answer": 0, "why": "Molemmat sääntökirjat antavat kilpailijalle keltaisen kortin, toistuvista rikkeistä ankarampia rangaistuksia, ja poistavat valmentajan."}]}]}, {"id": "sporting", "icon": "flag", "title": "Parcours de Chasse – Sporting™ -säännöt", "intro": "Parcours de Chasse – Sporting™ on FITASCin laji, joka jäljittelee metsästystä luonnonmaastossa. Tässä tehtävässä käydään sen säännöt läpi niin kuin tuomari niitä soveltaa: kierrokset ja ampumapaikat, ase alhaalla -aloitus, yksittäis- ja kaksoiskiekot, näytekiekot, häiriöt ja aikarajat. Kaikki tässä on omin sanoin kerrottua; sääntöviittaukset avaavat ClayArenan sääntöoppaan.", "lessons": [{"id": "sporting-rounds-stands", "minutes": 5, "title": "Kierrokset, ampumapaikat ja ampumajärjestys", "body": ["Parcours de Chasse – Sporting™ -kilpailu lasketaan 25 kiekon kierroksina. Kansainvälinen kilpailu on 200 kiekkoa eli kahdeksan kierrosta; jokainen kierros ammutaan yhdellä rataosuudella (ampumapaikkojen ryhmä) tai yhdellä linjalla.", "Jokainen rataosuus antaa 15 yksittäiskiekkoa ja 5 kaksoiskiekkoa. Ampumapaikkojen ja heittimien määrä riippuu järjestelmästä: vanhassa järjestelmässä on 5 heitintä 3 ampumapaikalle, kun taas uuden järjestelmän linjoilla on 4 tai 5 ampumapaikkaa, kullakin 3 tai 4 heitintä. Heittimet merkitään kirjaimin A, B, C, D vasemmalta oikealle ampumapaikalta katsottuna. Ampumapaikan edessä oleva kiekkoluettelo luettelee ne ampumajärjestyksessä sekä mahdolliset erikoiskiekot: 90, 70 tai 60 mm, battue, jäniskiekko.", "Itse ampumapaikka on 1 m:n neliö tai halkaisijaltaan 1 m:n ympyrä. Jokaisella lentoradalla on vaikeusluokka: A (keskitason ampuja rikkoo yli 80 %), B (60–80 %) tai C (40–60 %).", "Ampujat kiertävät enintään kuuden hengen erissä, jotka muodostetaan arvalla. Jokaisella ampumapaikalla kaikki ampuvat ensin yksittäiskiekot ja sitten kaksoiskiekot, ja ampumajärjestys kiertää jokaisella ampumapaikalla ja uudelleen kaksoiskiekoissa. Muut odottavat lähellä häiritsemättä ampujaa.", "Tuomari tai tuomarin valvoma henkilö pitää tulospöytäkirjaa ja merkitsee jokaisen kiekon sen heitinkirjaimen alle. Jokaiselta ampumapaikalta poistuessaan jokainen ampuja tarkistaa tuloksensa; erimielisyys on otettava heti esiin tuomarin kanssa, ja tuomarin ratkaisu on lopullinen."], "key_points": ["Kierros = 25 kiekkoa yhdellä rataosuudella: 15 yksittäis- + 5 kaksoiskiekkoa; kansainvälinen kilpailu = 200 kiekkoa.", "Heittimet A, B, C, D vasemmalta oikealle ampumapaikalta katsottuna; kiekkoluettelo kertoo järjestyksen ja erikoiskiekot.", "Enintään kuuden hengen erät; ensin yksittäis-, sitten kaksoiskiekot; järjestys kiertää.", "Tarkista tuloksesi poistuessasi jokaiselta ampumapaikalta; tuomari ratkaisee."], "terms": ["round", "layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "squad", "rotation", "score-sheet", "referee", "difficulty-class"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}], "coach_says": [{"en": "Singles first, then doubles.", "meaning": "Vakiojärjestys jokaisella ampumapaikalla.", "say": "Ensin yksittäiset, sitten parit."}, {"en": "Read the menu: the traps go A, B, C.", "meaning": "Kiekkoluettelotaulu luettelee heittimet siinä järjestyksessä, jossa ne ammutaan.", "say": "Lue kiekkoluettelo: heittimet menevät A, B, C."}, {"en": "Next shooter.", "meaning": "Tuomari kutsuu seuraavan henkilön ampumapaikalle.", "say": "Seuraava ampuja."}, {"en": "Check your score before you leave the stand.", "meaning": "Erimielisyys on otettava esiin nyt, ei myöhemmin.", "say": "Tarkista tuloksesi ennen kuin lähdet ampumapaikalta."}], "quiz": [{"q": "Montako kiekkoa yksi Sporting™-rataosuus antaa ja miten ne jakautuvat?", "options": ["20: 10 yksittäis- ja 5 kaksoiskiekkoa", "25: kaikki yksittäiskiekkoja", "25: 15 yksittäis- ja 5 kaksoiskiekkoa", "50: 25 yksittäis- ja 25 kaksoiskiekkoa"], "answer": 2, "why": "Jokainen rataosuustyyppi antaa 15 yksittäiskiekkoa ja 5 kaksoiskiekkoa, eli 25 kiekkoa."}, {"q": "Missä järjestyksessä erä ampuu ampumapaikalla?", "options": ["Ensin kaksoiskiekot, sitten yksittäiskiekot", "Kaikki ampuvat ensin yksittäiskiekot, sitten kaksoiskiekot, ja järjestys kiertää", "Jokainen ampuja ampuu koko rataosuuden kerralla", "Ampujat valitsevat vapaasti"], "answer": 1, "why": "Ensin yksittäiskiekot, sitten kaksoiskiekot, kiertävässä järjestyksessä, ellei jury päätä toisin."}, {"q": "Ampumapaikalta poistuessaan ampuja huomaa, että osuma on merkitty ohilaukaukseksi. Mitä hänen pitäisi tehdä?", "options": ["Odottaa kierroksen loppuun ja valittaa juryyn", "Korjata pöytäkirja itse", "Pyytää erää äänestämään", "Kertoa heti tuomarille; tuomari ratkaisee"], "answer": 3, "why": "Tulokset tarkistetaan jokaiselta ampumapaikalta poistuttaessa; tuomari ratkaisee yksin, eikä jälkikäteen voi valittaa."}]}, {"id": "sporting-gun-position", "minutes": 5, "title": "Ase alhaalla -aloitus", "body": ["Parcours de Chasse – Sporting™ -lajin näkyvin sääntö on ase alhaalla -aloitus. Ennen kiekon pyytämistä ampuja seisoo molemmat jalat ampumapaikan sisällä, tukin perä koskettaa vartaloa ja tukin takaosan ylin kohta on liivin merkkiviivan alapuolella. Tämä valmiusasento pidetään, kunnes kiekko on lähtenyt ja näkyy.", "Viiva merkitään liiviin tai takkiin 25 cm olkapäiden linjan alapuolelle, sen suuntaisesti, värillä, joka erottuu liivistä, jotta tuomari näkee sen. Sääntö koskee kaikkia tukkityyppejä, myös säädettäviä poskipakkoja.", "Aseen saa nostaa vasta, kun kiekko ilmestyy. Jokainen kiekko, myös jäniskiekko, ammutaan ase olalla; lonkalta ampuminen ei ole sallittua. Minkä tahansa kaksoiskiekon ensimmäisen ja toisen kiekon välillä aseen asento on vapaa, mutta ennen ensimmäistä kiekkoa valmiusasento on voimassa.", "Rangaistukset: kun ampuja ensimmäisen kerran pyytää kiekkoa väärässä asennossa tai nostaa aseen ennen kiekon ilmestymistä, tuomari antaa suullisen varoituksen ja keltaisen kortin. Jokaisesta seuraavasta rikkeestä samalla rataosuudella seuraa punainen kortti, ja kiekko merkitään yksittäiskiekossa nollaksi, laukauksesta lähtevässä kaksoiskiekossa nolla ja No Bird, yhtäaikaisessa tai rafale-kaksoiskiekossa nolla ja nolla.", "Aseen nostaminen ja heilauttaminen kuvitellun linjan mukana ennen kiekon pyytämistä (tähtäysharjoittelu, mock shooting) on myös kielletty: ensin varoitus, sitten nolla. Jos valmentaja harjoituttaa ase ylhäällä -aloitusta ennen FITASCin kilpailua, käännä myös sana ”drill” (harjoite)."], "key_points": ["Ennen pyyntöä: molemmat jalat ampumapaikalla, tukki koskettaa vartaloa, tukin yläreuna liivin merkkiviivan alapuolella.", "Liivin viiva on 25 cm olkapäiden linjan alapuolella, kontrastivärillä.", "Nosta vasta, kun kiekko ilmestyy; ammu aina olalta; vapaa asento kaksoiskiekon kiekkojen välillä.", "Ensimmäinen rike: varoitus + keltainen kortti; seuraava samalla rataosuudella: punainen kortti ja kiekko merkitään."], "terms": ["ready-position", "gun-mount", "shooting-stand", "shooting-vest", "adjustable-comb", "mock-shooting", "yellow-card", "red-card", "jacket-line"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}], "coach_says": [{"en": "Gun down, please.", "meaning": "Tuomari: tuo tukki liivin merkkiviivan alapuolelle ennen kiekon pyytämistä.", "say": "Ase alas, kiitos."}, {"en": "Your stock was above the line. This is a warning.", "meaning": "Ensimmäinen aseen asentoa koskeva rike: suullinen varoitus ja keltainen kortti.", "say": "Tukkisi oli viivan yläpuolella. Tämä on varoitus."}, {"en": "Don't mount before the target appears.", "meaning": "Aseen saa nostaa vasta, kun kiekko näkyy.", "say": "Älä nosta asetta ennen kuin kiekko ilmestyy."}, {"en": "Red card, zero.", "meaning": "Toistuva rike samalla rataosuudella; yksittäiskiekko on menetetty.", "say": "Punainen kortti, nolla."}], "quiz": [{"q": "Ensimmäinen ampumapaikka. Ampuja pyytää kiekkoa ase jo olalla. Se on hänen ensimmäinen rikkeensä tällä rataosuudella. Mikä on tuomarin ratkaisu?", "options": ["Kiekko merkitään nollaksi", "Suullinen varoitus ja keltainen kortti", "No Bird eikä muuta", "Kilpailusta sulkeminen"], "answer": 1, "why": "Ensimmäinen aseen asentoa koskeva rike on suullinen varoitus, jota tukee keltainen kortti."}, {"q": "Sama rataosuus, kaksi ampumapaikkaa myöhemmin: sama ampuja pyytää yksittäiskiekkoa tukki liivin viivan yläpuolella. Ratkaisu?", "options": ["Uusi keltainen kortti", "No Bird", "Punainen kortti, ja kiekko uusitaan", "Punainen kortti, ja yksittäiskiekko merkitään nollaksi"], "answer": 3, "why": "Varoituksen jälkeen uusi rike samalla rataosuudella on punainen kortti: yksittäiskiekossa nolla."}, {"q": "Laukauksesta lähtevä kaksoiskiekko. Rikottuaan ensimmäisen kiekon ampuja laskee asetta hieman ennen toista. Ratkaisu?", "options": ["Sallittu: aseen asento on vapaa kahden kiekon välillä", "Keltainen kortti", "Nolla toisesta kiekosta", "No Bird"], "answer": 0, "why": "Vapaa asento koskee minkä tahansa kaksoiskiekon kiekkojen väliä; valmiusasento vaaditaan vain ennen ensimmäistä."}]}, {"id": "sporting-singles-doubles", "minutes": 5, "title": "Yksittäis- ja kaksoiskiekot", "body": ["Yksittäiskiekko on yksi kiekko yhdestä heittimestä. Parcours de Chasse – Sporting™ -lajissa ampuja saa ampua siihen kaksi patruunaa, joten ensimmäisen piipun ohilaukauksen voi vielä pelastaa toisella. Jokaisen yksittäiskiekon on jätettävä aikaa kahdelle laukaukselle.", "Kaksoiskiekko on kaksi kiekkoa, ja ampujalla on siihen vain kaksi patruunaa; molemmat saa ampua samaan kiekkoon. Lajeja on kolme. Laukauksesta lähtevä (on report): toinen kiekko lähtee 0–3 sekuntia ensimmäiseen ammutun laukauksen jälkeen, ja sen lähettää tuo laukaus. Yhtäaikainen (simultaneous): molemmat lähtevät samalla hetkellä yhdestä tai kahdesta heittimestä. Rafale (peräkkäinen): kaksi kiekkoa samasta heittimestä samalla linjalla, toinen niin nopeasti kuin heitin latautuu. Yhtäaikaisissa ja rafale-kaksoiskiekoissa kiekot saa ampua kummassa järjestyksessä tahansa. Kaksoiskiekoissa käytetään vain kiekkoja, jotka on jo näytetty yksittäiskiekkoina samalta ampumapaikalta.", "Ratkaisuja, joita tuomari joutuu usein tekemään: jos yksi laukaus rikkoo minkä tahansa kaksoiskiekon molemmat kiekot, molemmat lasketaan, osuma ja osuma. Jos ampuja ei ilman pätevää syytä ammu rafale- tai yhtäaikaiseen kaksoiskiekkoon, tulos on nolla ja nolla.", "Laukauksesta lähtevässä kaksoiskiekossa virheellinen ensimmäinen kiekko tarkoittaa, että kaksoiskiekko uusitaan; jos ensimmäinen kiekko tai sen palat rikkovat toisen ennen toista laukausta tai toinen on virheellinen, kaksoiskiekko uusitaan ja ensimmäinen tulos jää voimaan. Yhtäaikaisissa ja rafale-kaksoiskiekoissa virheellinen kiekko tarkoittaa uusintaa ilman tuloksen kirjaamista.", "Vinkki: välitä kaksoiskiekon tulos parina, tuomarin järjestyksessä."], "key_points": ["Yksittäiskiekko: kaksi patruunaa sallittu.", "Kaksoiskiekko: yhteensä kaksi patruunaa, molemmat saa ampua yhteen kiekkoon; lajit: laukauksesta lähtevä, yhtäaikainen, rafale.", "Yksi laukaus rikkoo molemmat kiekot: osuma ja osuma.", "Ampumatta jättäminen yhtäaikaisessa tai rafale-kaksoiskiekossa ilman syytä: nolla ja nolla."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "trap", "trajectory", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch2-trajectories-ethics", "label": "2 · Hunting ethics and shooting distances"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-target-doubles", "label": "6 · Target No Bird in doubles"}], "coach_says": [{"en": "Report pair: the second comes on your shot.", "meaning": "Valmentaja: toisen kiekon lähettää ensimmäiseen ammuttu laukaus.", "say": "Laukauksesta lähtevä pari: toinen tulee laukauksestasi."}, {"en": "On the rafale, take either one first.", "meaning": "Rafale-kaksoiskiekossa järjestys on vapaa.", "say": "Rafalessa ota kumpi tahansa ensin."}, {"en": "One and one.", "meaning": "Tuomari: kaksoiskiekon molemmat kiekot ovat osumia.", "say": "Osuma ja osuma."}, {"en": "No Bird, repeat the double.", "meaning": "Virheellinen kiekko; kaksoiskiekko heitetään uudelleen.", "say": "No Bird, kaksoiskiekko uusitaan."}], "quiz": [{"q": "Yhtäaikainen kaksoiskiekko. Yksi laukaus rikkoo molemmat kiekot. Mikä on tuomarin ratkaisu?", "options": ["Osuma ja osuma", "Osuma ja No Bird", "No Bird, kaksoiskiekko uusitaan", "Osuma ja nolla"], "answer": 0, "why": "Sporting™-lajissa yhdellä laukauksella rikotut kaksi kiekkoa missä tahansa kaksoiskiekossa merkitään osuma ja osuma (Compak® Sporting eroaa)."}, {"q": "Laukauksesta lähtevä kaksoiskiekko. Ampuja rikkoo ensimmäisen kiekon, ja sen pala murskaa toisen ennen toista laukausta. Ratkaisu?", "options": ["Osuma ja osuma", "Kaksoiskiekko uusitaan ja ensimmäinen tulos jää voimaan", "Nolla toisesta kiekosta", "Osuma ja nolla"], "answer": 1, "why": "Kun ensimmäinen kiekko tai sen palat rikkovat toisen ennen toista laukausta, kaksoiskiekko uusitaan ja ensimmäinen tulos pysyy."}, {"q": "Rafale-kaksoiskiekko. Molemmat kiekot lentävät oikein, mutta ampuja laskee aseen eikä ammu kumpaankaan, ilman pätevää syytä. Ratkaisu?", "options": ["No Bird", "Nolla ja No Bird", "Vain keltainen kortti", "Nolla ja nolla"], "answer": 3, "why": "Oikea kiekko, johon ei ammuta ilman pätevää syytä, on menetetty; rafale- tai yhtäaikaisessa kaksoiskiekossa se tarkoittaa nolla ja nolla."}]}, {"id": "sporting-viewing", "minutes": 5, "title": "Näytekiekot", "body": ["Ennen kuin erä ampuu ampumapaikan, tuomari näyttää kiekot. Näytekiekot ovat kiekkojen lukemista varten: linja, nopeus, etäisyys ja mitä kiekko tekee. Kaikki lentoradat näytetään erän ensimmäiselle ampujalle, jonka on seistävä valmiina ampumapaikalla.", "Ampumapaikalla oleva ampuja voi pyytää tuomaria näyttämään kiekot uudelleen, enintään kaksi kiekkoa kiekkoluettelon kutakin kiekkoa kohden.", "Laukauksesta lähteviä kaksoiskiekkoja ei näytetä, koska toinen kiekko lähtee vasta laukauksen äänestä. Yhtäaikaiset ja rafale-kaksoiskiekot näytetään kunkin erän ensimmäiselle ampujalle, ja pyynnöstä ne näytetään uudelleen enintään kaksi näytettyä kaksoiskiekkoa.", "Näytekiekkojen aikana aseet ovat auki ja tyhjinä, kuten jokaisen keskeytyksen aikana, ja ne suljetaan vasta tuomarin luvalla. Ampuminen tai tähtäysharjoittelu näytekiekkojen aikana on kielletty, ja siitä rangaistaan kuten aseen asentoa koskevasta rikkeestä: ensin varoitus, sitten punainen kortti.", "Jos heitin rikkoutuu tai ammunta keskeytyy yli kymmeneksi minuutiksi, tuomari näyttää kyseisen ampumapaikan kiekot uudelleen. Ennen kilpailua kukaan ei saa harjoitella kilpailun rataosuuksilla.", "Harjoituksissa näytekiekot ovat valmentajan lempihetki: ”watch where it turns” (katso, missä se kääntyy). Kilpailussa näytekiekot ovat osa kilpailua, joten valmentamiskielto koskee myös niitä: ole hiljaa, ellei tuomari tai ampuja tarvitse menettelyä koskevaa käännöstä."], "key_points": ["Kaikki lentoradat näytetään ensimmäiselle ampujalle, joka seisoo valmiina ampumapaikalla.", "Uusinnat pyynnöstä: enintään kaksi kiekkoluettelon kiekkoa kohden.", "Laukauksesta lähteviä kaksoiskiekkoja ei koskaan näytetä; yhtäaikaiset ja rafale-kaksoiskiekot näytetään.", "Aseet auki näytekiekkojen aikana; ei ampumista eikä tähtäysharjoittelua.", "Yli 10 minuutin keskeytys: kiekot näytetään uudelleen."], "terms": ["target-presentation", "target-menu", "double-on-report", "simultaneous-double", "rafale-double", "mock-shooting", "practice", "red-card"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch16-long-interruption", "label": "16 · Interruption over 10 minutes"}, {"book": "sporting", "id": "ch15-no-practice", "label": "15 · No practice on competition layouts"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}], "coach_says": [{"en": "Show me the targets, please.", "meaning": "Ampuja tuomarille: aloita näytekiekot.", "say": "Näyttäkää kiekot, kiitos."}, {"en": "Again, please, B only.", "meaning": "Pyyntö näyttää uudelleen yksi kiekkoluettelon kiekko.", "say": "Uudelleen, kiitos, vain B."}, {"en": "Guns open during the show.", "meaning": "Tuomari: avaa ja tyhjennä ase, kunnes hän sallii sulkemisen.", "say": "Aseet auki näytön ajan."}, {"en": "Watch where it turns.", "meaning": "Valmentaja harjoituksissa: huomaa kohta, jossa kiekko muuttaa suuntaa tai muotoa.", "say": "Katso, missä se kääntyy."}], "quiz": [{"q": "Mitä kaksoiskiekkoja EI näytetä näytekiekoissa?", "options": ["Yhtäaikaisia", "Rafale-kaksoiskiekkoja", "Laukauksesta lähteviä", "Ei mitään: kaikki näytetään"], "answer": 2, "why": "Laukauksesta lähtevän parin toinen kiekko lähtee vasta laukauksesta, joten näitä kaksoiskiekkoja ei näytetä."}, {"q": "Montako kiekon uusintaa ampumapaikalla oleva ampuja saa pyytää?", "options": ["Ei yhtään", "Enintään kaksi kiekkoluettelon kutakin kiekkoa kohden", "Niin monta kuin tarvitaan", "Yhden ampumapaikkaa kohden"], "answer": 1, "why": "Pyynnöstä tuomari näyttää kiekot uudelleen, enintään kaksi kiekkoa kiekkoluettelon kutakin kiekkoa kohden."}, {"q": "Näytekiekkojen aikana ampuja sulkee aseensa ja heilauttaa sitä kiekon linjaa pitkin. Mitä sovelletaan?", "options": ["Se on kielletty: sovelletaan aseen asentoa koskevia rangaistuksia, varoitus ja sitten punainen kortti", "Ei mitään: näytön aikana saa tehdä mitä haluaa", "Kiekko näytetään uudelleen", "Vain valmentajaa varoitetaan"], "answer": 0, "why": "Aseet pysyvät auki näytekiekkojen aikana, ja ampumisesta tai tähtäysharjoittelusta rangaistaan varoitus- ja punaisen kortin sääntöjen mukaan."}]}, {"id": "sporting-malfunctions", "minutes": 5, "title": "Ase- ja patruunahäiriöt", "body": ["Häiriö (malfunction) on aseen tai patruunan toimintahäiriö: patruuna ei laukea, toinen piippu ei toimi, tai molemmat piiput laukeavat samanaikaisesti (double discharge). Parcours de Chasse – Sporting™ -lajissa häiriöt lasketaan 25 kiekon kierrosta kohden.", "Ensin se, mitä ampujan on tehtävä: pysyttävä paikallaan ase ampuma-alueelle päin, avaamatta sitä tai koskematta varmistimeen, kunnes tuomari on tarkastanut sen. Jos ampuja avaa aseen tai koskee varmistimeen ensin, kiekko tai kiekot merkitään nolliksi.", "Kierroksen ensimmäinen häiriö on No Bird ja varoitus, ja kiekko uusitaan. Samalla kierroksella toisesta häiriöstä alkaen kiekkoa ei enää uusita, vaan se merkitään nollaksi.", "Ensimmäisen häiriön yksityiskohdat: jos ensimmäinen laukaus ei lähde, yksittäiskiekko tai mikä tahansa kaksoiskiekko uusitaan, mutta jos ampuja silti ampuu toisen laukauksen, sen tulos jää voimaan. Jos yksittäiskiekossa toinen laukaus ei lähde, kiekko uusitaan, ja sen saa silloin rikkoa vain toisella laukauksella; ensimmäisellä laukauksella rikottu merkitään nollaksi. Laukauksesta lähtevässä kaksoiskiekossa ensimmäinen tulos jää voimaan ja kaksoiskiekko uusitaan. Kun molemmat piiput laukeavat samanaikaisesti yksittäiskiekossa tai minkä tahansa kaksoiskiekon ensimmäisessä kiekossa, tulos on No Bird eikä mitään kirjata.", "Jos ase saadaan korjattua ennen kuin erä on ampunut ampumapaikan loppuun, ampuja voi ampua viimeisenä tuomarin luvalla; muuten hän voi jatkaa heti toisella aseella tai ampua loppuun toisessa erässä juryn hyväksynnällä. Asetta, supistajaa tai piippua ei saa vaihtaa, kun ampuja on ampumapaikalla."], "key_points": ["Häiriön jälkeen: pysy paikallasi, ase ampuma-alueelle päin, älä avaa sitä äläkä koske varmistimeen.", "Kierroksen ensimmäinen häiriö: No Bird + varoitus, kiekko uusitaan.", "Toinen häiriö samalla kierroksella: nolla, ei uusintaa.", "Toisen laukauksen häiriö yksittäiskiekossa: uusinnassa lasketaan vain toisella laukauksella rikottu kiekko."], "terms": ["malfunction", "double-discharge", "no-bird", "zero", "safety-catch", "round", "choke", "barrel"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}, {"book": "sporting", "id": "ch6-malfunction-first-shot", "label": "6 · Malfunction on the first shot"}, {"book": "sporting", "id": "ch6-malfunction-second-shot", "label": "6 · Malfunction on the second shot"}, {"book": "sporting", "id": "ch6-second-malfunction", "label": "6 · Second malfunction in the same round"}, {"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch7-double-discharge", "label": "7 · Double discharge due to a gun fault"}, {"book": "sporting", "id": "ch7-malfunction-procedure", "label": "7 · What happens after a gun malfunction"}, {"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}], "coach_says": [{"en": "Stay there, don't open the gun.", "meaning": "Tuomari: odota tarkastusta; jos avaat ensin, menetät kiekon.", "say": "Pysy siinä, älä avaa asetta."}, {"en": "Let me see the gun.", "meaning": "Tuomari tarkastaa aseen tai patruunan.", "say": "Näytä minulle ase."}, {"en": "Malfunction. No Bird, first warning.", "meaning": "Kierroksen ensimmäinen häiriö: kiekko uusitaan.", "say": "Häiriö. No Bird, ensimmäinen varoitus."}, {"en": "Second malfunction this round. Zero.", "meaning": "Tällä kertaa ei uusintaa; kiekko on menetetty.", "say": "Toinen häiriö tällä kierroksella. Nolla."}], "quiz": [{"q": "Kierroksen ensimmäinen aseongelma: yksittäiskiekossa ensimmäinen patruuna ei laukea. Ampuja odottaa tuomaria ase ampuma-alueelle päin. Ratkaisu?", "options": ["Nolla", "No Bird ja varoitus; kiekko uusitaan", "Osuma", "Keltainen kortti ja nolla"], "answer": 1, "why": "Kierroksen ensimmäinen ase- tai patruunahäiriö on No Bird ja varoitus, ja yksittäiskiekko uusitaan."}, {"q": "Patruuna ei laukea, ja ärtynyt ampuja taittaa aseen auki katsoakseen nallia ennen tuomarin tuloa. Ratkaisu?", "options": ["No Bird", "Kiekko uusitaan varoituksen jälkeen", "Nolla", "Punainen kortti, ja kiekko uusitaan"], "answer": 2, "why": "Aseen avaaminen tai varmistimeen koskeminen ennen tuomarin tarkastusta tarkoittaa, että kiekko merkitään nollaksi."}, {"q": "Yksittäiskiekko, ensimmäinen häiriö: ensimmäinen laukaus menee ohi ja toinen patruuna ei laukea, joten kiekko uusitaan. Uusinnassa ampuja rikkoo sen ensimmäisellä laukauksella. Ratkaisu?", "options": ["Osuma", "Taas No Bird", "Osuma ja varoitus", "Nolla: tässä uusinnassa lasketaan vain toisella laukauksella rikottu kiekko"], "answer": 3, "why": "Toisen laukauksen häiriön jälkeen uusitun yksittäiskiekon saa rikkoa vain toisella laukauksella, joten ensimmäinen laukaus on ammuttava tahallaan ohi."}]}, {"id": "sporting-time-and-lateness", "minutes": 5, "title": "Aikarajat ja myöhästyminen", "body": ["Parcours de Chasse – Sporting™ etenee tiukassa rytmissä, ja useat säännöt suojaavat sitä. Kun ampuja pyytää kiekkoa sanalla ”pull” tai ”ready”, tuomari välittää pyynnön heittäjälle äänimerkillä, ja kiekon on lähdettävä kolmen sekunnin kuluessa; myöhemmin lähtevä kiekko on No Bird.", "Yksittäiskiekkojen tai kaksoiskiekkojen välillä ampujalla on enintään 15 sekuntia. Kun raja ylittyy ensimmäisen kerran, tuomari antaa varoituksen; sen jälkeen sovelletaan punaisen kortin rangaistuksia. Protestia koskevan lopullisen ratkaisun jälkeen ampujan on jatkettava 15 sekunnin kuluessa, muuten se katsotaan määräysten noudattamatta jättämiseksi; tahallista viivyttelyä käsitellään samoin.", "Myöhästyminen: kun ampuja puuttuu, tuomari kutsuu hänen nimeään ja numeroaan kolme kertaa yhden minuutin aikana. Saapuminen ennen omaa vuoroa ensimmäisen ampumapaikan yksittäiskiekoissa ei maksa mitään. Sen jälkeen jokainen ampumatta jäänyt kiekko on nolla; jos ampuja liittyy mukaan myöhemmällä ampumapaikalla, kaikki aiempien ampumapaikkojen kiekot ovat nollia. Rataosuutta, jolta ampumapaikkoja on jäänyt väliin, ei voi koskaan ampua uudelleen toisessa erässä.", "Ampuja, joka myöhästyy itsestään riippumattomista syistä, ei saa liittyä erään kyseisellä kierroksella, vaan hänen on tehtävä kirjallinen vetoomus juryyn. Jos jury hyväksyy sen, kierros ammutaan toisessa erässä; jos ei, jokaisesta ampumatta jääneestä rataosuudesta tulee 25 nollaa.", "Ampumapaikalle astuminen ilman kuulosuojaimia tai ampumalaseja katsotaan poissaoloksi. Ennalta aikatauluttamattomaan uusintakierrokseen ampujien on oltava valmiina 15 minuutin kuluessa kutsusta.", "Sinulle: älä koskaan pidätä erää pitkällä käännöksellä. Lyhyesti nyt, yksityiskohdat ampumapaikan jälkeen."], "key_points": ["Kiekko 3 sekunnin kuluessa tuomarin merkistä, muuten No Bird.", "Enintään 15 sekuntia yksittäis- tai kaksoiskiekkojen välillä: varoitus, sitten punainen kortti.", "Jatka 15 sekunnin kuluessa lopullisen ratkaisun jälkeen, muuten kyse on määräysten noudattamatta jättämisestä.", "Myöhässä: nimi ja numero kutsutaan kolme kertaa minuutin aikana; väliin jääneet kiekot ovat nollia."], "terms": ["call", "trapper", "no-bird", "firing-time", "red-card", "jury", "hearing-protection", "safety-glasses", "shoot-off"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch10-deliberate-delay", "label": "10 · Deliberate delay or unfair behaviour"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch16-late-excuse", "label": "16 · Lateness beyond the shooter's control"}, {"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}], "coach_says": [{"en": "Shooter number twenty-three!", "meaning": "Tuomari kutsuu puuttuvaa ampujaa (kolme kertaa minuutin aikana).", "say": "Ampuja numero kaksikymmentäkolme!"}, {"en": "Watch your time.", "meaning": "Muistutus kiekkojen välisestä 15 sekunnin rajasta.", "say": "Seuraa aikaasi."}, {"en": "Over fifteen seconds. This is a warning.", "meaning": "Ensimmäinen rajan ylitys: varoitus; seuraavalla kerralla rangaistus.", "say": "Yli viisitoista sekuntia. Tämä on varoitus."}, {"en": "Glasses on, or you can't shoot.", "meaning": "Ilman silmäsuojaimia ampuja katsotaan poissaolevaksi.", "say": "Lasit päähän, tai et voi ampua."}], "quiz": [{"q": "Ampuja pyytää kiekkoa, tuomari välittää merkin, mutta kiekko lähtee noin viisi sekuntia myöhemmin. Ampuja ampuu ja menee ohi. Ratkaisu?", "options": ["Nolla", "No Bird", "Osuma", "Varoitus ampujalle"], "answer": 1, "why": "Kiekko, joka lähtee yli kolme sekuntia tuomarin merkin jälkeen, on No Bird."}, {"q": "Ampuja saapuu, kun hänen eränsä ampuu vielä ampumapaikan 1 yksittäiskiekkoja eikä hänen vuoronsa ole vielä tullut. Mitä tapahtuu?", "options": ["Hän liittyy mukaan ilman rangaistusta", "25 nollaa", "Nolla kaikista ampumapaikan 1 yksittäiskiekoista", "Hänen on ammuttava toisen erän kanssa"], "answer": 0, "why": "Saapuminen ennen kuin oma vuoro ensimmäisen ampumapaikan yksittäiskiekoissa on mennyt ohi ei tuo rangaistusta."}, {"q": "Kahden yksittäiskiekon välillä ampuja käyttää noin 25 sekuntia, ensimmäistä kertaa tänään. Ratkaisu?", "options": ["Nolla seuraavasta kiekosta", "Punainen kortti", "Ei mitään seurausta", "Tuomarin varoitus"], "answer": 3, "why": "Raja on 15 sekuntia; ensimmäisellä ylityskerralla tuomari varoittaa, ja vasta sen jälkeen seuraa rangaistuksia."}]}]}, {"id": "compak", "icon": "grid", "title": "Compak® Sporting -säännöt", "intro": "Compak® Sporting tiivistää Parcours de Chasse – Sporting™ -lajin monipuolisuuden pienelle kentälle: viisi ampumapaikkaa rivissä, kuusi heitintä ja kiinteä suorakaide, jonka yli kiekkojen on lennettävä. Monet säännöt näyttävät samoilta, mutta aseen asento, aikarajat, kaksoiskiekot ja rangaistukset eroavat. Tulkki, joka sekoittaa nämä kaksi lajia, antaa ampujalle väärää tietoa.", "lessons": [{"id": "compak-layout-rotation", "minutes": 5, "title": "Rataosuus, kiekkoluettelo ja ampumajärjestys", "body": ["Compak® Sporting -rataosuus on tarkoituksella tiivis. Kiekkojen on lennettävä merkityn suorakaiteen yli, joka on 35–40 m leveä ja 25 m syvä ja jonka jokaisessa kulmassa on lippu tai merkki. Sen edessä on viisi ampumapaikkaa, kukin 1 m:n neliö, rivissä 4–8 m suorakaiteen etusivun takana; ampumapaikka 3 on keskellä.", "Heittimiä on kuusi, ja ne on merkitty kirjaimin A–F vasemmalta oikealle, kukin omalla kyltillään. Jokaisessa Compak®-radassa on oltava vasemmalta oikealle lentävä sivukiekko, oikealta vasemmalle lentävä sivukiekko ja peräkiekko; muut lentoradat valitsee järjestäjä. Jokaisella ampumapaikalla on ampumakulman rajoitin (Firing Angle Limiter), kehikko, joka estää asetta kääntymästä liian kauas ja pitää ampujan ampumapaikan sisällä.", "Kierros on 25 kiekkoa, viisi jokaiselta ampumapaikalta: viisi yksittäiskiekkoa, kolme yksittäiskiekkoa ja yksi kaksoiskiekko tai yksi yksittäiskiekko ja kaksi kaksoiskiekkoa. Samalla Compak®-radalla kaksoiskiekon tyyppi on sama kaikilla ampumapaikoilla. Kiekkoluettelo eli kiekkojen järjestys on nähtävillä jokaisella ampumapaikalla, ja jokaisen kaksoiskiekon ensimmäinen kiekko on edellisen ampumapaikan viimeinen kiekko.", "Ampumajärjestys enintään kuuden ampujan erässä: ampumapaikka 1 aloittaa aina, ja kuudes ampuja odottaa sen takana. Kun ampumapaikan 5 ampuja on valmis, hän siirtyy odottamaan ampumapaikan 1 taakse, kaikki siirtyvät yhden ampumapaikan oikealle, ja odottanut ampuja astuu ampumapaikalle 1. Ampumapaikkaa vaihdetaan ase avattuna ja tyhjänä, häiritsemättä niitä, jotka vielä ampuvat.", "Linjassa ammuttava Compak® (in-line) toimii toisin: ryhmän jokainen ampuja kulkee ampumapaikalta 1 ampumapaikalle 5."], "key_points": ["Suorakaide 35–40 m × 25 m; viisi 1 m:n ampumapaikkaa; kuusi heitintä A–F.", "Pakolliset: vasemmalta oikealle lentävä sivukiekko, oikealta vasemmalle lentävä sivukiekko, peräkiekko.", "Kierros = 25 kiekkoa, 5 ampumapaikkaa kohden; yksi kaksoiskiekkotyyppi Compak®-rataa kohden.", "Jokainen kaksoiskiekko alkaa edellisen ampumapaikan viimeisellä kiekolla.", "Ampumapaikan 5 jälkeen: odota ampumapaikan 1 takana; kaikki siirtyvät yhden paikan oikealle."], "terms": ["trap", "target-menu", "round", "squad", "rotation", "crosser", "going-away", "shooting-stand", "double", "fly-over-rectangle", "firing-angle-limiter", "waiting-position"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch3-free-trajectories", "label": "3 · Free trajectories"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-squads-groups", "label": "17 · Size of squads and groups"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Move one station to the right.", "meaning": "Ampumajärjestyksen vaihto sen jälkeen, kun ampumapaikan 5 ampuja on valmis.", "say": "Siirry yksi paikka oikealle."}, {"en": "Gun open when you change stations.", "meaning": "Ampumapaikkojen välillä ase on avattuna ja tyhjänä.", "say": "Ase auki, kun vaihdat paikkaa."}, {"en": "Your double starts with the last target of the previous station.", "meaning": "Compak®-kiekkoluettelon ketjusääntö.", "say": "Kaksoiskiekkosi alkaa edellisen paikan viimeisellä kiekolla."}, {"en": "You're waiting behind one.", "meaning": "Kuudes ampuja seisoo ampumapaikan 1 takana.", "say": "Sinä odotat ykköspaikan takana."}], "quiz": [{"q": "Montako heitintä ja ampumapaikkaa Compak® Sporting -rataosuudella on?", "options": ["4 heitintä, 3 ampumapaikkaa", "6 heitintä, 5 ampumapaikkaa", "5 heitintä, 5 ampumapaikkaa", "8 heitintä, 6 ampumapaikkaa"], "answer": 1, "why": "Compak®-radalla on kuusi heitintä, A–F, ja viisi ampumapaikkaa."}, {"q": "Ampumapaikan 5 ampuja on ampunut kiekkoluettelonsa. Mihin hän menee?", "options": ["Ampumapaikalle 1", "Hän jää ampumapaikalle 5", "Ampumapaikan 1 taakse odottamaan", "Tuomarin luo allekirjoittamaan pöytäkirjan"], "answer": 2, "why": "Hänestä tulee odottava ampuja ampumapaikan 1 taakse, ja kaikki muut siirtyvät yhden ampumapaikan oikealle."}, {"q": "Compak®-radalla jokaisen kaksoiskiekon ensimmäinen kiekko on…", "options": ["mikä tahansa ampujan valitsema kiekko", "aina heitin A", "kiekko, joka näytetään vain pyynnöstä", "edellisen ampumapaikan viimeinen kiekko"], "answer": 3, "why": "Kiekkoluettelo ketjuttaa ampumapaikat: jokainen kaksoiskiekko alkaa kiekolla, joka päätti edellisen ampumapaikan."}]}, {"id": "compak-gun-and-call", "minutes": 5, "title": "Aseen asento, kiekon pyytäminen ja aika", "body": ["Tässä Compak® Sporting eroaa näkyvimmin Parcours de Chasse – Sporting™ -lajista. Kiekkoa pyydettäessä aseen asento on vapaa: ase voi olla jo olalla tai ei. Ase alhaalla -aloitusta ja liivin merkkiviivaa ei ole. Jokainen kiekko ammutaan silti ase olalla.", "Kiekon lähetys: heittimet laukaistaan käsin, kauko-ohjaimella tai äänellä toimivalla mikrofonilähdöllä (sonopull). Käsin laukaistaessa kiekon on lähdettävä 0–3 sekunnin kuluessa pyynnöstä; mikrofonilähdössä on kiinteä 0,5 sekunnin viive. Kansainvälisissä in-line-kilpailuissa käytetään vain mikrofonilähtöä. Kiekko, joka lähtee yli 3 sekuntia pyynnön jälkeen, tai kiekko, jota ampuja ei pyytänyt, on No Bird (uusi kiekko).", "Aika: ampujalla on enintään 10 sekuntia aikaa pyytää kiekkoa sen jälkeen, kun edellisen ampumapaikan kiekko on ammuttu – lyhyempi aika kuin Sporting™-lajin 15 sekuntia. Ensimmäisellä kerralla tuomari merkitsee varoituksen tulospöytäkirjaan; jos sama toistuu samalla kierroksella, seuraa punainen kortti ja kiekot merkitään näin: yksittäiskiekko nolla, laukauksesta lähtevä kaksoiskiekko nolla ja No Bird, yhtäaikainen kaksoiskiekko nolla ja nolla.", "Näytekiekot: erissä ammuttaessa kiekot näytetään kerran aamulla ensimmäiselle erälle. Ampumapaikan 1 ampuja pyytää jokaisen yksittäiskiekon, A–F; sitten tuomari näyttää yhtäaikaiset kaksoiskiekot ja sanoo ”start” tai ”competition”. Yli 10 minuutin keskeytyksen jälkeen kuusi yksittäiskiekkoa näytetään uudelleen.", "Lataaminen: vain omalla ampumapaikalla, ase avattuna ja suunnattuna ampuma-alueelle ampumakulman rajoittimen sisällä; sulje ase vasta, kun on sinun vuorosi."], "key_points": ["Aseen asento kiekkoa pyydettäessä on vapaa; laukaukset aina olalta.", "Käsilähtö 0–3 s pyynnöstä; mikrofonilähtö kiinteästi 0,5 s; yli 3 s = No Bird.", "Enintään 10 sekuntia kiekon pyytämiseen: ensin varoitus pöytäkirjaan, sitten kiekot merkitään nolliksi.", "Kiekot näytetään kerran aamulla ensimmäiselle erälle; uudelleen yli 10 minuutin tauon jälkeen."], "terms": ["ready-position", "call", "sonopull", "no-bird", "firing-time", "score-sheet", "target-presentation", "loading"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}], "coach_says": [{"en": "Start! / Competition!", "meaning": "Tuomari: näytekiekot ovat ohi ja kilpailuammunta alkaa.", "say": "Start! / Kilpailu alkaa!"}, {"en": "Gun up or down, your choice here.", "meaning": "Valmentaja: Compak®-lajissa aseen asento kiekkoa pyydettäessä on vapaa.", "say": "Ase ylhäällä tai alhaalla, saat valita."}, {"en": "Ten seconds, call your target.", "meaning": "Muistutus 10 sekunnin aikarajasta kiekon pyytämiseen.", "say": "Kymmenen sekuntia, pyydä kiekkosi."}, {"en": "Warning: time.", "meaning": "Ensimmäinen ylitys yli 10 sekuntia; merkitään tulospöytäkirjaan.", "say": "Varoitus: aika."}], "quiz": [{"q": "Compak® Sporting -lajissa ampuja pyytää kiekkoa ase jo olalla. Mikä on tuomarin ratkaisu?", "options": ["Keltainen kortti", "Sallittu: aseen asento pyydettäessä on vapaa", "Nolla", "Sallittu vain kaksoiskiekoissa"], "answer": 1, "why": "Compak® Sporting -lajissa ei ole ase alhaalla -aloitusta eikä liivin merkkiviivaa; vain itse laukaus on ammuttava olalta."}, {"q": "Käsilähtö. Kiekko lähtee noin neljä sekuntia pyynnön jälkeen, ja ampuja ampuu ohi. Ratkaisu?", "options": ["Nolla", "Osuma", "Varoitus vain heittäjälle, nolla jää voimaan", "No Bird"], "answer": 3, "why": "Kiekko, joka lähtee yli 3 sekuntia pyynnön jälkeen, on No Bird ja heitetään uudelleen."}, {"q": "Ampuja käyttää samalla kierroksella toisen kerran yli 10 sekuntia kiekon pyytämiseen. Kiekko on yksittäiskiekko. Ratkaisu?", "options": ["Nolla", "Vain uusi varoitus", "No Bird", "Kilpailusta sulkeminen"], "answer": 0, "why": "Ensimmäisen varoituksen jälkeen toistuva rike samalla kierroksella rangaistaan taulukon mukaan: yksittäiskiekko merkitään nollaksi."}]}, {"id": "compak-singles-doubles", "minutes": 5, "title": "Yksittäis- ja kaksoiskiekot Compak®-lajissa", "body": ["Compak® Sporting käyttää samoja sanoja kuin Parcours de Chasse – Sporting™, mutta sen kaksoiskiekkoja koskevat eri säännöt. Tulkki, joka siirtää Sporting™-säännöt sellaisinaan, antaa vääriä vastauksia.", "Yksittäiskiekot: jokaiseen yksittäiskiekkoon on voitava ampua kaksi laukausta kaikilta viideltä ampumapaikalta, joten toinen piippu on sallittu toinen mahdollisuus.", "Compak®-säännöt määrittelevät kaksi kaksoiskiekon lajia: laukauksesta lähtevä (on report: pyyntö lähettää ensimmäisen kiekon, laukaus toisen; yksi tai kaksi heitintä) ja yhtäaikainen (simultaneous: kaksi kiekkoa yhdellä pyynnöllä, aina kahdesta eri heittimestä, ammuttavissa kummassa järjestyksessä tahansa). Peräkkäistä kaksoiskiekkoa (rafale) ei ole.", "Keskeinen ero: Compak®-kaksoiskiekossa kumpaankin kiekkoon saa ampua vain yhden patruunan. Molempien laukausten ampuminen ensimmäiseen kiekkoon on kielletty, ja tuomarien pikaoppaan mukaan tahallinen kahden laukauksen ampuminen yhteen kiekkoon merkitään nolla ja nolla. Sporting™-lajissa molemmat patruunat saa ampua yhteen kiekkoon.", "Kaksi kiekkoa yhdellä laukauksella: laukauksesta lähtevässä kaksoiskiekossa ensimmäinen tulos jää voimaan, toinen on No Bird, ja kaksoiskiekko ammutaan uudelleen. Yhtäaikaisessa kaksoiskiekossa tulos on No Bird, mitään ei merkitä, ja kaksoiskiekko uusitaan; samoin toisella kerralla; kolmannella kerralla tulos on nolla ja nolla. Sporting™-lajissa sama laukaus merkitään yksinkertaisesti osuma ja osuma.", "Virheelliset kiekot: jos laukauksesta lähtevän kaksoiskiekon ensimmäinen kiekko tai yhtäaikaisen kaksoiskiekon kumpi tahansa kiekko on virheellinen, heitetään uusi kaksoiskiekko. Jos laukauksesta lähtevän kaksoiskiekon toinen kiekko on virheellinen tai rikkoutuu ensimmäisestä, ensimmäinen tulos jää voimaan ja kaksoiskiekko uusitaan."], "key_points": ["Vain kaksi kaksoiskiekon lajia: laukauksesta lähtevä ja yhtäaikainen; ei rafalea.", "Kaksoiskiekossa yksi patruuna kiekkoa kohden; molemmat yhteen kiekkoon = nolla ja nolla (pikaopas).", "Laukauksesta lähtevä, kaksi yhdellä laukauksella: ensimmäinen tulos jää, toinen No Bird, kaksoiskiekko uusitaan.", "Yhtäaikainen, kaksi yhdellä laukauksella: kahdesti No Bird, kolmannella kerralla nolla ja nolla."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch3-two-with-one-report", "label": "3 · Double on report: both targets broken with one shot"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}, {"book": "compak", "id": "ch20-target-no-bird-actions", "label": "20 · What happens after a target NO BIRD"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}], "coach_says": [{"en": "One shot per bird on the pairs here.", "meaning": "Valmentaja: Compak®-lajissa kaksoiskiekon kumpaankin kiekkoon saa vain yhden patruunan.", "say": "Täällä pareissa yksi laukaus per kiekko."}, {"en": "Both with one shot. No Bird, shoot the double again.", "meaning": "Tuomari yhtäaikaisessa kaksoiskiekossa: mitään ei merkitä, uusitaan.", "say": "Molemmat yhdellä laukauksella. No Bird, ammu kaksoiskiekko uudelleen."}, {"en": "Choose your order on the show.", "meaning": "Valmentaja: päätä näytekiekkoja katsoessasi, kumman yhtäaikaisen kiekon otat ensin.", "say": "Valitse järjestys näytekiekoista."}, {"en": "Zero, zero.", "meaning": "Tuomari: kumpaakaan kaksoiskiekon kiekkoa ei hyväksytä.", "say": "Nolla, nolla."}], "quiz": [{"q": "Yhtäaikainen kaksoiskiekko Compak®-lajissa. Yksi laukaus rikkoo molemmat kiekot; näin käy ensimmäistä kertaa. Ratkaisu?", "options": ["Osuma ja osuma", "No Bird, mitään ei merkitä, kaksoiskiekko uusitaan", "Osuma ja No Bird", "Nolla ja nolla"], "answer": 1, "why": "Compak®-lajissa yhdellä laukauksella rikottu yhtäaikainen kaksoiskiekko on No Bird ensimmäisellä ja toisella kerralla ja nolla ja nolla kolmannella kerralla."}, {"q": "Laukauksesta lähtevä kaksoiskiekko Compak®-lajissa. Yksi laukaus rikkoo molemmat kiekot. Ratkaisu?", "options": ["Osuma ja osuma", "Nolla ja nolla", "Ensimmäinen tulos jää voimaan, toinen on No Bird, ja kaksoiskiekko uusitaan", "No Bird, mitään ei merkitä"], "answer": 2, "why": "Laukauksesta lähtevässä kaksoiskiekossa ensimmäisen kiekon tulos kirjataan, ja kaksoiskiekko ammutaan uudelleen toisen kiekon tuloksen saamiseksi."}, {"q": "Compak®-kaksoiskiekossa ampuja ampuu ensimmäisen kiekon ohi ja ampuu tahallaan myös toisen patruunan siihen. Miten tuomarien pikaopas merkitsee tämän?", "options": ["Nolla ja nolla", "Se on sallittu, kuten Sporting™-lajissa", "Kaksoiskiekko uusitaan", "Vain toinen laukaus lasketaan"], "answer": 0, "why": "Compak®-kaksoiskiekossa kiekkoa kohden sallitaan vain yksi patruuna; tahallinen kaksi laukausta yhteen kiekkoon on nolla ja nolla."}]}, {"id": "compak-malfunctions", "minutes": 5, "title": "Häiriöt Compak®-lajissa", "body": ["Compak® Sporting -lajissa, kuten Parcours de Chasse – Sporting™ -lajissa, ase- ja patruunahäiriöt lasketaan 25 kiekon kierrosta kohden: ensimmäisestä häiriöstä seuraa No Bird ja keltainen kortti; toisesta samantyyppisestä häiriöstä ampumatta jääneet kiekot merkitään nolliksi ja annetaan punainen kortti.", "Mitä ampujan on tehtävä: pysyä paikallaan ase suunnattuna ampuma-alueelle, avaamatta asetta tai koskematta varmistimeen, kunnes tuomari on tarkastanut sen. Jos ampuja avaa aseen ensin, hän menettää kiekon tai kiekot: nolla.", "Ensimmäinen häiriö, kun molemmat piiput laukeavat samanaikaisesti tai ensimmäinen patruuna ei laukea: yksittäiskiekko heitetään uudelleen, laukauksesta lähtevä tai yhtäaikainen kaksoiskiekko heitetään uudelleen, eikä epäonnistuneesta yrityksestä merkitä mitään. Kun toinen patruuna ei laukea: yksittäiskiekossa kiekko heitetään uudelleen, mutta vain toinen laukaus voi tuottaa osuman, joten ensimmäinen on ammuttava tahallaan ohi; laukauksesta lähtevässä kaksoiskiekossa ensimmäinen tulos jää voimaan ja kaksoiskiekko uusitaan toista kiekkoa varten; yhtäaikaisessa kaksoiskiekossa heitetään uusi kaksoiskiekko.", "Häiriön jälkeen ampujalla on kaksi minuuttia aikaa korjata tai vaihtaa ase. Poikkeuksena hän voi lainata aseen ampujalta, joka ei ole hänen omassa erässään, omistajan ja tuomarin suostumuksella. Jos toimivaa asetta ei ole, jäljellä olevat kiekot ovat nollia. Muuten asetta, supistajaa tai piippua ei saa vaihtaa kierroksen aikana.", "Sama logiikka koskee jäniskiekkoa, joka ammutaan ohi ensimmäisellä laukauksella ja rikkoutuu ennen toista: No Bird, ja uusinnassa vain toinen laukaus lasketaan."], "key_points": ["Kierroksen ensimmäinen häiriö: No Bird + keltainen kortti; toinen samantyyppinen: nolla + punainen kortti.", "Älä avaa asetta tai koske varmistimeen ennen tuomarin tarkastusta.", "Toisen patruunan häiriö yksittäiskiekossa: uusinnassa vain toinen laukaus lasketaan.", "Kaksi minuuttia korjaamiseen tai vaihtoon; lainaa vain oman erän ulkopuolelta, omistajan ja tuomarin suostumuksella."], "terms": ["malfunction", "double-discharge", "safety-catch", "no-bird", "zero", "yellow-card", "red-card", "rabbit", "choke"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch20-gun-failure-principle", "label": "20 · Gun or cartridge failures: first and second incident"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-malfunction", "label": "21 · Malfunction: inspection, 2 minutes, replacement gun"}, {"book": "compak", "id": "ch20-gun-failure-first-shot", "label": "20 · Both barrels fire together or the first cartridge fails"}, {"book": "compak", "id": "ch20-gun-failure-second-shot", "label": "20 · The second cartridge fails"}, {"book": "compak", "id": "ch12-borrowing", "label": "12 · Borrowing a gun after a breakdown"}, {"book": "compak", "id": "ch13-shared-gun", "label": "13 · No sharing a gun within a group"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}], "coach_says": [{"en": "Don't move, keep the gun closed.", "meaning": "Tuomari: odota tarkastusta häiriön jälkeen.", "say": "Älä liiku, pidä ase kiinni."}, {"en": "First malfunction. Yellow card, No Bird.", "meaning": "Kierroksen ensimmäinen tämäntyyppinen häiriö; kiekko heitetään uudelleen.", "say": "Ensimmäinen häiriö. Keltainen kortti, No Bird."}, {"en": "You have two minutes.", "meaning": "Aika aseen korjaamiseen tai vaihtamiseen.", "say": "Sinulla on kaksi minuuttia."}, {"en": "Only the second shot counts on this one.", "meaning": "Uusinta toisen patruunan häiriön jälkeen: ammu ensimmäinen laukaus tahallaan ohi.", "say": "Tässä lasketaan vain toinen laukaus."}], "quiz": [{"q": "Kierroksen ensimmäinen häiriö Compak®-lajissa: ensimmäinen patruuna ei laukea yksittäiskiekossa. Ampuja odottaa oikein. Ratkaisu?", "options": ["No Bird ja keltainen kortti; heitetään uusi kiekko", "Nolla", "Punainen kortti ja nolla", "Osuma"], "answer": 0, "why": "Kierroksen ensimmäinen ase- tai patruunahäiriö on No Bird, ja ensimmäinen varoitus näytetään keltaisella kortilla."}, {"q": "Ampujan ase hajoaa. Hän haluaa lainata erätoverinsa asetta. Onko se sallittua?", "options": ["Kyllä, omistajan suostumuksella", "Kyllä, jos tuomari suostuu", "Kyllä, ilman ehtoja", "Ei: lainaajan on oltava oman erän ulkopuolelta, ja sekä omistajan että tuomarin on suostuttava"], "answer": 3, "why": "Compak® kieltää saman aseen yhteiskäytön ryhmän sisällä; poikkeuksellinen lainaus on mahdollinen vain ryhmän ulkopuolelta ja molempien suostumuksella."}, {"q": "Toinen samantyyppinen asehäiriö tällä kierroksella yksittäiskiekossa, johon ampuja ei voinut ampua. Ratkaisu?", "options": ["Taas No Bird", "No Bird ja varoitus", "Nolla ja punainen kortti", "Kiekko näytetään uudelleen"], "answer": 2, "why": "Toisesta samantyyppisestä häiriöstä alkaen ampumatta jääneet kiekot merkitään nolliksi."}]}, {"id": "compak-dress-and-conduct", "minutes": 5, "title": "Pukeutuminen ja käyttäytyminen", "body": ["Compak® Sporting -kilpailut ovat yleisölle avoimia, joten vaatetuksen on oltava asiallinen ja käytännöllinen. Lyhyet shortsit on kielletty, mutta bermudashortsit, jotka päättyvät enintään 5 cm polven yläpuolelle, ovat sallittuja. Paidoissa on oltava vähintään lyhyet hihat, ja niiden on ulotuttava kaulaan asti; T-paita käy, mutta paljas rinta liivin alla ei. Sandaalit on kielletty harjoituksissa ja kilpailuissa. Kilpailunumero pidetään selässä kokonaan näkyvissä; ensimmäisestä rikkeestä seuraa varoitus, sitten seuraamuksia.", "Kuulo- ja silmäsuojaimet ovat pakolliset. Jos ampuja saapuu ampumapaikalle ilman niitä, hänet katsotaan poissaolevaksi: hän ei saa ampua.", "Täsmällisyys: ilmoittaudu tuomarille ajoissa. Erissä ammuttaessa, jos ampuja saapuu vasta sen jälkeen, kun erän ensimmäinen ampuja on pyytänyt ensimmäistä kiekkoa, hän saa kierrokselta 25 nollaa; vetoomus tehdään juryyn kirjallisesti samana päivänä.", "Käyttäytyminen: valmentaminen kilpailun aikana on kielletty; kilpailija saa keltaisen kortin ja valmentaja poistetaan ampuma-alueelta. Lopullisen ratkaisun kiistäminen sen jälkeen, kun ammunta on jatkunut, tai ratkaisun avoin arvostelu ampujana tai katsojana on yritys vaikuttaa tuomariin ja voi johtaa kilpailusta sulkemiseen. Jokaisen kierroksen lopussa ampuja allekirjoittaa tulospöytäkirjan; allekirjoituksesta kieltäytyminen tarkoittaa valitusoikeuden menettämistä.", "Ampumapaikan lähellä olet osa yleisöä: käytä suojaimia, ole hiljaa kiekon pyytämisen aikana äläkä koskaan kommentoi ratkaisua. Saako valmentajan sanoja välittää kilpailussa, on FITASCille avoin kysymys; turvallinen käytäntö on tulkata vain tuomarille, jurylle ja järjestäjälle."], "key_points": ["Ei lyhyitä shortseja, ei paljasta rintaa liivin alla, ei sandaaleja (ei myöskään harjoituksissa); numero selässä.", "Ei kuulo- tai silmäsuojaimia ampumapaikalla = poissa, ei ammuntaa.", "Myöhästyminen erän ensimmäisen pyynnön jälkeen: 25 nollaa; kirjallinen vetoomus samana päivänä mahdollinen.", "Ei valmentamista; ei ratkaisujen julkista arvostelua; allekirjoita tulospöytäkirja."], "terms": ["dress-code", "competitor-number", "hearing-protection", "safety-glasses", "conduct", "yellow-card", "score-sheet", "protest", "quiet-on-stand"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-late-appeal", "label": "9 · Appealing a lateness penalty"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}], "coach_says": [{"en": "Number on your back, please.", "meaning": "Tuomari: kilpailunumeron on oltava selässä kokonaan näkyvissä.", "say": "Numero selkään, kiitos."}, {"en": "Ears and eyes on.", "meaning": "Laita kuulosuojaimet ja lasit ennen ampumapaikalle tuloa.", "say": "Kuulosuojaimet ja lasit päähän."}, {"en": "Sign the sheet, please.", "meaning": "Kierroksen loppu: ampuja allekirjoittaa tulospöytäkirjan.", "say": "Allekirjoita pöytäkirja, kiitos."}, {"en": "No coaching on the stand.", "meaning": "Tuomarin varoitus: valmentaminen on kilpailussa kielletty.", "say": "Ei valmentamista ampumapaikalla."}], "quiz": [{"q": "Ampuja tulee ampumapaikalle sandaaleissa harjoituskierrokselle. Onko se sallittua?", "options": ["Kyllä, vain harjoituksissa", "Ei: sandaalit on kielletty harjoituksissa ja kilpailuissa", "Kyllä, sukkien kanssa", "Vain tuomarin luvalla"], "answer": 1, "why": "Compak®-lajin pukeutumissäännöt kieltävät sandaalit turvallisuussyistä sekä harjoituksissa että kilpailuissa."}, {"q": "Erissä ammunta. Ampuja saapuu juuri sen jälkeen, kun hänen eränsä ensimmäinen ampuja on pyytänyt ensimmäistä kiekkoa. Seuraus?", "options": ["Ei rangaistusta", "Nolla vain ensimmäisestä kiekosta", "Hän ampuu erän viimeisenä", "Kierrokselta 25 nollaa; kirjallinen vetoomus juryyn samana päivänä on mahdollinen"], "answer": 3, "why": "Takaraja on erän ensimmäinen kiekon pyyntö; sen jälkeen myöhästynyt ampuja saa 25 nollaa, ellei jury hyväksy pätevää syytä."}, {"q": "Kierroksen jälkeen ampuja kieltäytyy allekirjoittamasta tulospöytäkirjaa, koska on eri mieltä yhdestä ratkaisusta. Mikä on seuraus?", "options": ["Hän menettää oikeuden tehdä minkäänlaista valitusta", "Tuomarin on muutettava tulosta", "Kierros ammutaan uudelleen", "Mitään ei tapahdu"], "answer": 0, "why": "Pöytäkirjan allekirjoittaminen jokaisen kierroksen lopussa on pakollista; allekirjoituksesta kieltäytyminen tekee kaikista valituksista mahdottomia käsitellä."}]}]}, {"id": "referee", "icon": "whistle", "title": "Tuomari, pisteytys ja rangaistukset", "intro": "Kilpailussa tuomari on se henkilö, jonka sanoja käännät useimmin ja huolellisimmin. Tässä tehtävässä opit suulliset ilmoitukset, tulospöytäkirjan, kortit ja rangaistukset, protestimenettelyn ja ikäsarjat, jotta jokainen ratkaisu tavoittaa ampujasi täsmälleen sellaisena kuin se tehtiin.", "lessons": [{"id": "referee-calls", "minutes": 5, "title": "Mitä tuomari sanoo ampumapaikalla", "body": ["Ampumapaikalla on oma lyhyt kielensä. Ampuja pyytää kiekkoa, kun on valmis, yleensä sanalla ”Pull!” tai ”Ready!”. Parcours de Chasse – Sporting™ -lajissa tuomari välittää pyynnön heittäjälle äänimerkillä, ja kiekon on lähdettävä kolmen sekunnin kuluessa; myöhemmin lähtevä kiekko on No Bird (uusi kiekko). Compak® Sporting -lajissa myös käsilähdön on tapahduttava kolmen sekunnin kuluessa pyynnöstä, ja äänilähdössä (mikrofonilähtö, sonopull) on kiinteä puolen sekunnin viive.", "Ennen kuin kukaan ampuu, tuomari valvoo aseita. Lataaminen on sallittua vain ampumapaikalla, ase ampuma-alueelle päin, kun tuomari on ilmoittanut ammunnan voivan alkaa. Näytekiekkojen aikana ja aina ammunnan keskeytyessä aseet ovat auki ja tyhjinä, ja ne suljetaan uudelleen vasta tuomarin luvalla. Compak®-lajissa tuomari aloittaa kierroksen sanalla ”Start” tai ”Competition”.", "Jokaisen kiekon jälkeen säännöt tuntevat kolme tulosta: ”one” (osuma), ”zero” (ohi) ja ”No Bird” (kiekko ei lasketa ja heitetään uudelleen). Eri puolilla maailmaa kuulet osumasta myös ”dead”, ”good”, ”lost” (ohi) tai pelkän hiljaisuuden. Compak®-lajissa tuomarin on ilmoitettava jokainen nolla ääneen tai äänimerkillä, jotta eri mieltä oleva ampuja voi protestoida heti.", "Myös ampujalla on yksi muodollinen sana: käsi nostettuna ”Protest!” tai ”Appeal!”. Kun tulkkaat, pidä nämä ilmoitukset lyhyinä ja joka kerta samanlaisina. Sovi ampujasi kanssa ennen kierrosta, mitä sanoja käytät, äläkä koskaan lisää mitään omaasi kiekon pyynnön ja laukauksen väliin."], "key_points": ["Ampuja pyytää ”Pull!” tai ”Ready!”; kiekon on lähdettävä 3 sekunnin kuluessa", "Lataa vain ampumapaikalla ja vain tuomarin luvalla; aseet auki näytekiekkojen ja keskeytysten aikana", "Sääntöjen sanat: one = osuma, zero = ohi, No Bird = heitetään uudelleen", "Compak®: jokainen nolla ilmoitetaan ääneen tai äänimerkillä", "Protesti = nostettu käsi + ”Protest!” tai ”Appeal!”"], "terms": ["call", "referee", "trapper", "sonopull", "one", "zero", "no-bird", "loading", "target-presentation", "protest"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch5-referee-oath", "label": "5 · Referee's commitments"}, {"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}], "coach_says": [{"en": "You may load.", "meaning": "Tuomari sallii ammunnan alkaa: laita patruunat nyt, ase ampuma-alueelle päin.", "say": "Saat ladata."}, {"en": "No bird!", "meaning": "Tämä kiekko ei lasketa; älä ammu sitä. Se heitetään uudelleen.", "say": "Uusi kiekko!"}, {"en": "Lost.", "meaning": "Tuomari merkitsi kiekon ohilaukaukseksi (nolla).", "say": "Ohi."}, {"en": "Dead. / Good.", "meaning": "Kiekko on osuma.", "say": "Osuma."}, {"en": "Guns open, please — we’re showing the targets.", "meaning": "Kaikki avaavat ja tyhjentävät aseensa; tuomari heittää kiekot nähtäviksi.", "say": "Aseet auki, kiitos – näytämme kiekot."}, {"en": "Start. / Competition.", "meaning": "Compak®: näytekiekot ovat ohi, kierros lasketaan tästä eteenpäin.", "say": "Start. / Kilpailu alkaa."}], "quiz": [{"q": "Parcours de Chasse – Sporting™ -lajissa kiekko lähtee viisi sekuntia tuomarin merkin jälkeen. Mikä on ratkaisu?", "options": ["Se lasketaan normaalisti", "No Bird", "Nolla, koska ampuja pyysi liian aikaisin", "Varoitus vain heittäjälle"], "answer": 1, "why": "Kiekon on lähdettävä kolmen sekunnin kuluessa tuomarin merkistä; myöhemmin lähtevä on No Bird ja heitetään uudelleen."}, {"q": "Milloin ampuja saa ladata aseen?", "options": ["Kävellessään ampumapaikalle", "Ampumapaikan takana odottaessaan", "Ampumapaikalla, ase ampuma-alueelle päin, kun tuomari on sallinut ammunnan", "Aina kun valmentaja niin sanoo"], "answer": 2, "why": "Lataaminen on sallittua vain ampumapaikalla, ampuma-alueelle päin, ja vasta kun tuomari on antanut luvan aloittaa."}, {"q": "Millä sanalla muodollinen protesti aloitetaan ampumapaikalla?", "options": ["”Protest!” tai ”Appeal!” käsi nostettuna", "”Pull!”", "”No bird!”", "”Tuomari, katso!”"], "answer": 0, "why": "Molemmat sääntökirjat mainitsevat ”protest” tai ”appeal” käsi nostettuna; ”No bird” kuuluu yksin tuomarille."}]}, {"id": "referee-scoring", "minutes": 5, "title": "Tulospöytäkirjat, tulokset ja tasapisteet", "body": ["Jokainen kiekko päätyy tulospöytäkirjaan. Parcours de Chasse – Sporting™ -lajissa pöytäkirjaa pitää tuomari tai joku tuomarin valvonnassa. FITASCin mallissa näkyy jokaisen kiekon heitinkirjain, osuma merkitään X:llä ja ohi O:lla, sekä yhteispisteet ja allekirjoitussarake. Ennen kuin erä siirtyy eteenpäin, tuomari valokuvaa pöytäkirjan.", "Ampujien on tarkistettava tuloksensa poistuessaan jokaiselta ampumapaikalta. Erimielisyys viedään heti tuomarille; tuomari ratkaisee, mahdollisesti muita kuultuaan, eikä sen jälkeen voi valittaa. Compak® Sporting -lajissa ampuja allekirjoittaa tulospöytäkirjan kierroksen lopussa, ja allekirjoituksesta kieltäytyvä ampuja menettää valitusoikeutensa. Käännä ”check your card” kiireellisenä ohjeena, ei kohteliaana huomautuksena.", "Kansainvälinen kilpailu on 200 kiekkoa 25 kiekon kierroksina. Kun ampujat ovat tasapisteissä kolmesta ensimmäisestä sijasta, he ampuvat 25 kiekon uusintakierroksen; jos he ovat yhä tasoissa, seuraa sudden death, jossa ensimmäinen nolla pudottaa. Kolmannen sijan alapuolella uusintakierrosta ei ammuta: tasapisteissä olevat jakavat sijan ja heidät järjestetään Count Back -säännöllä viimeisestä (kahdeksannesta) rataosuudesta tai Compak®-radasta ensimmäiseen päin. Joukkueet eivät koskaan ammu uusintaa.", "Uusintakierrokseen liittyy vielä yksi tulkin ansa. Jos aikaa ei ole määrätty, ampujien on oltava valmiina viidentoista minuutin kuluessa kutsusta. Puuttuva ampuja on Sporting™-säännöissä ”hylätty” (disqualified) ja Compak®-säännöissä ”katsotaan luopuneeksi” (considered withdrawn). Käytä sen lajin sanaa, jonka kilpailussa olet."], "key_points": ["X = osuma, O = ohi FITASCin tulospöytäkirjoissa", "Sporting™: tarkista tuloksesi poistuessasi jokaiselta ampumapaikalta; Compak®: allekirjoita pöytäkirja tai menetät valitusoikeuden", "Tasapisteet sijoista 1–3: 25 kiekon uusinta, sitten sudden death", "3. sijan alapuolella: Count Back 8. rataosuudesta tai Compak®-radasta; ei joukkueuusintoja", "Valmiina 15 minuutin kuluessa uusintakierroksen kutsusta"], "terms": ["score-sheet", "round", "one", "zero", "shoot-off", "countback", "team", "referee"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}, {"book": "sporting", "id": "ch18-team-ties", "label": "18 · Team ties"}, {"book": "compak", "id": "ch15-who-keeps", "label": "15 · Who keeps the score sheet"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}, {"book": "compak", "id": "ch14-shootoff-availability", "label": "14 · Staying available for a shoot-off"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}, {"book": "compak", "id": "ch14-team-ties", "label": "14 · Ties between national teams"}], "coach_says": [{"en": "Check your card before you leave the stand.", "meaning": "Katso merkintäsi nyt; myöhempiä vastalauseita ei hyväksytä.", "say": "Tarkista pöytäkirjasi ennen kuin lähdet ampumapaikalta."}, {"en": "Sign here, please.", "meaning": "Compak®: allekirjoitus vahvistaa tuloksen; kieltäytyminen tarkoittaa valitusoikeuden menettämistä.", "say": "Allekirjoita tähän, kiitos."}, {"en": "Twenty-three — you dropped two.", "meaning": "Tulos 23/25; kaksi kiekkoa meni ohi.", "say": "Kaksikymmentäkolme – kaksi ohi."}, {"en": "There’s a tie for third — shoot-off in fifteen minutes.", "meaning": "Ole nimetyllä rataosuudella ja valmiina ampumaan viidentoista minuutin kuluessa.", "say": "Kolmannesta sijasta on tasapisteet – uusintakierros viidentoista minuutin päästä."}, {"en": "Sudden death: first zero is out.", "meaning": "25 kiekon uusinnan jälkeen ensimmäinen ohi ampuva (yhtä monen ammutun kiekon jälkeen) putoaa.", "say": "Sudden death: ensimmäinen nolla putoaa."}], "quiz": [{"q": "Mitä O tarkoittaa FITASCin tulospöytäkirjassa?", "options": ["Osumaa", "No Birdiä", "Ohilaukausta", "Tyhjää ampumapaikkaa"], "answer": 2, "why": "FITASCin mallissa osuma merkitään X:llä ja ohilaukaus O:lla."}, {"q": "Kaksi ampujaa on tasapisteissä 7. sijasta. Mitä tapahtuu?", "options": ["25 kiekon uusintakierros", "Heti sudden death", "Juryn kolikonheitto", "He jakavat sijan ja heidät järjestetään Count Back -säännöllä"], "answer": 3, "why": "Uusintakierrokset ammutaan vain sijoista 1–3; sen alapuolella tasapisteissä olevat järjestetään Count Back -säännöllä kahdeksannesta rataosuudesta tai Compak®-radasta alkaen."}, {"q": "Compak® Sporting -lajissa ampujasi kieltäytyy allekirjoittamasta tulospöytäkirjaa. Mikä on seuraus?", "options": ["Hän menettää oikeuden tehdä minkäänlaista valitusta", "Kierros ammutaan uudelleen", "Tuomari allekirjoittaa eikä mikään muutu", "Hän saa automaattisesti 25 nollaa"], "answer": 0, "why": "Compak®-sääntöjen mukaan allekirjoituksesta kieltäytyvä ampuja menettää valitusoikeutensa."}]}, {"id": "referee-cards", "minutes": 5, "title": "Varoitukset, kortit ja rangaistukset", "body": ["FITASCin rangaistukset etenevät portaittain. Ilmoittautuessaan kilpailuun ampuja hyväksyy säännöt ja seuraamukset. Ensimmäisestä sääntörikkeestä seuraa yleensä varoitus, joka näytetään keltaisella kortilla. Parcours de Chasse – Sporting™ -lajissa klassinen esimerkki on aseen asento: tukki liivin merkkiviivan yläpuolella tai ennen kiekon ilmestymistä nostettu ase tuo suullisen varoituksen ja keltaisen kortin.", "Toistuvasta rikkeestä samalla rataosuudella (tai samalla Compak®-radalla) seuraa punainen kortti, ja kiekko merkitään taulukon mukaan: yksittäiskiekossa nolla, laukauksesta lähtevässä kaksoiskiekossa nolla ja No Bird, yhtäaikaisessa tai rafale-kaksoiskiekossa nolla ja nolla. Samaa asteikkoa sovelletaan ilmoitettuun No Birdiin ampumiseen ja Sporting™-lajissa kiekkojen välisen viidentoista sekunnin ylittämiseen. Compak® Sporting -lajissa raja on kymmenen sekuntia kiekon pyytämiseen.", "Myös valmentamisesta kilpailun aikana rangaistaan: ampuja saa keltaisen kortin, toistuvista rikkeistä seuraa lisää seuraamuksia, ja tuomari lähettää valmentaneen henkilön pois ampuma-alueelta. Tulkille tämä on sääntökirjan tärkein kortti.", "Toistuvista rikkeistä, määräysten noudattamatta jättämisestä tai tuomariin vaikuttamisen yrityksistä jury voi vähentää yhden kiekon, kokonaisen 25 kiekon kierroksen tai sulkea ampujan kilpailusta. Aseen heittäminen, solvaaminen tai väkivalta sekä tahallinen ampuminen eläviin eläimiin voivat johtaa välittömään kilpailusta sulkemiseen. FITASC kirjaa kilpailusta sulkemisen viideksi vuodeksi, eikä osallistumismaksua palauteta. Käännä ”warning”, ”yellow card” ja ”red card” kirjaimellisesti, rauhallisesti ja heti."], "key_points": ["Ensimmäinen rike: varoitus ja keltainen kortti", "Toistuminen samalla rataosuudella tai Compak®-radalla: punainen kortti + kiekko taulukon mukaan", "Valmentaminen kilpailussa: keltainen kortti ampujalle, valmentaja poistetaan", "Juryn asteikko: yksi kiekko, yksi kierros tai kilpailusta sulkeminen", "Kilpailusta sulkeminen: kirjataan 5 vuodeksi, ei palautusta"], "terms": ["yellow-card", "red-card", "penalty", "ready-position", "firing-time", "jury", "conduct"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch13-acceptance", "label": "13 · Acceptance of rules; first breach = warning"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch12-shooting-nobird", "label": "12 · Shooting at a declared No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch13-jury-penalties", "label": "13 · Jury penalty scale"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "sporting", "id": "ch13-immediate-expulsion", "label": "13 · Immediate expulsion"}, {"book": "sporting", "id": "ch13-expulsion-record", "label": "13 · Expulsion record and lifetime ban"}, {"book": "sporting", "id": "ch13-no-refund", "label": "13 · No refund after expulsion"}, {"book": "compak", "id": "ch23-yellow-card", "label": "23 · Accepting the rules; first a yellow card"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch23-exclusion-record", "label": "23 · Exclusions: record, repeat, no refund"}], "coach_says": [{"en": "Warning — your stock was above the line.", "meaning": "Sporting™: ase oli liian korkealla ennen kiekon ilmestymistä; seuraavalla kerralla tällä rataosuudella se maksaa kiekon.", "say": "Varoitus – tukkisi oli viivan yläpuolella."}, {"en": "That’s a yellow card.", "meaning": "Virallinen ensimmäinen varoitus; se kirjataan.", "say": "Se on keltainen kortti."}, {"en": "Red card — the target is zero.", "meaning": "Toistuva rike: kiekko merkitään ohilaukaukseksi.", "say": "Punainen kortti – kiekko on nolla."}, {"en": "You’re over time.", "meaning": "Ampuja käytti sallittua enemmän aikaa (15 s Sporting™-lajissa, 10 s kiekon pyytämiseen Compak®-lajissa).", "say": "Aika ylittyi."}, {"en": "Sir, please leave the shooting area.", "meaning": "Tuomari poistaa jonkun, esimerkiksi valmentamisesta kiinni jääneen henkilön.", "say": "Poistukaa ampuma-alueelta, kiitos."}], "quiz": [{"q": "Sporting™: nostetusta aseesta saadun keltaisen kortin jälkeen ampuja nostaa aseen taas liian aikaisin samalla rataosuudella yksittäiskiekossa. Mikä on tulos?", "options": ["Uusi varoitus", "Punainen kortti ja kiekko on nolla", "No Bird", "Välitön kilpailusta sulkeminen"], "answer": 1, "why": "Ensimmäisen varoituksen jälkeen uusi rike samalla rataosuudella tuo punaisen kortin; yksittäiskiekossa kiekko on nolla."}, {"q": "Tuomari näkee valmentajan neuvovan ampujaa kilpailun aikana. Mitä säännöt sanovat?", "options": ["Ei mitään, valmentaminen on sallittua ampumapaikkojen välillä", "Valmentaja saa punaisen kortin", "Ampuja saa keltaisen kortin ja valmentaja poistetaan ampuma-alueelta", "Kierros mitätöidään"], "answer": 2, "why": "Molemmat sääntökirjat antavat kilpailijalle keltaisen kortin, ja tuomari lähettää valmentaneen henkilön pois ampuma-alueelta."}, {"q": "Mitä näistä jury EI voi määrätä rangaistusasteikon mukaan?", "options": ["Yhden kiekon menetyksen", "25 kiekon kierroksen menetyksen", "Kilpailusta sulkemisen", "Tuomarille maksettavan rahasakon"], "answer": 3, "why": "Juryn asteikko on kiekon menetys, kierroksen menetys tai kilpailusta sulkeminen; tuomarille maksettavaa sakkoa ei ole."}]}, {"id": "referee-appeals", "minutes": 5, "title": "Protestit, vakuusmaksut ja jury", "body": ["Protesti on tehtävä heti paikan päällä. Ampuja nostaa kätensä ja sanoo ”Protest!” tai ”Appeal!” ampumapaikalla ennen kuin pyytää seuraavaa kiekkoa (Compak® Sporting -lajissa ennen kuin seuraava ampuja pyytää kiekkoa). Tuomari keskeyttää ammunnan ja kuuntelee perustelun. Pyytämällä seuraavaa kiekkoa ampuja hyväksyy edellisen ratkaisun, joten tulkkina sinun on oltava tässä nopea.", "Jos tuomari on varma, ratkaisu vahvistetaan ja siitä tulee lopullinen. Epävarmana tuomari voi kysyä toiselta tuomarilta, heittäjältä tai erän ampujilta pelkästään neuvoa ja ratkaisee sitten yksin. Ampujat eivät saa koskaan mennä ampuma-alueelle eivätkä nostaa kiekkoa tarkistaakseen sen, ja luonnollisen esteen takana tai takarajan ulkopuolella rikkoutunut kiekko on tuomarin ratkaistava.", "Joitakin ratkaisuja ei voi koskaan viedä juryyn: oliko kiekko osuma vai ohi, No Bird ja oliko lentorata oikea. Muista ratkaisuista voi valittaa juryyn kirjallisesti vakuusmaksua vastaan: Parcours de Chasse – Sporting™ -lajissa se on 40 % osallistumismaksusta; Compak®-lajissa kyseisenä päivänä voimassa oleva summa, ja vain saman päivän tapahtumista. Jos vetoomus menestyy, vakuusmaksu palautetaan.", "Lopullisen ratkaisun jälkeen ampujan on jatkettava viidentoista sekunnin kuluessa Sporting™-lajissa ja kymmenen sekunnin kuluessa Compak®-lajissa; muuten kyse on määräysten noudattamatta jättämisestä. Väittelyn jatkaminen, tuomarin näyttävä haastaminen tai muiden henkilöiden avoin ratkaisun arvostelu katsotaan yritykseksi vaikuttaa tuomariin. Sinun tehtäväsi on kääntää protesti ja vastaus tarkasti, ei ajaa asiaa."], "key_points": ["Protestoi heti, ampumapaikalla, käsi ylhäällä: ”Protest!” / ”Appeal!”", "Seuraavan kiekon pyytäminen = edellisen ratkaisun hyväksyminen", "Ei koskaan valituskelpoisia: osuma/ohi, No Bird, oikea lentorata", "Kirjallinen vetoomus juryyn vakuusmaksua vastaan (Sporting™: 40 % osallistumismaksusta)", "Jatka 15 s (Sporting™) tai 10 s (Compak®) kuluessa; väittelyn jatkaminen = tuomariin vaikuttaminen"], "terms": ["protest", "appeal", "jury", "referee", "entry-fee", "no-bird", "trajectory"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "sporting", "id": "ch9-consultation", "label": "9 · Referee in doubt: consultation"}, {"book": "sporting", "id": "ch9-jury-appeal", "label": "9 · What can go to the jury and the 40% deposit"}, {"book": "sporting", "id": "ch9-deposit-outcome", "label": "9 · Outcome of a jury appeal"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch15-appeal-jury", "label": "15 · Appeal jury"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}, {"book": "compak", "id": "ch19-consultation", "label": "19 · Referee in doubt: who may be consulted"}, {"book": "compak", "id": "ch4-complaint-limits", "label": "4 · What you cannot complain about"}, {"book": "compak", "id": "ch4-complaint-procedure", "label": "4 · How to lodge a complaint and the deposit"}, {"book": "compak", "id": "ch21-refusal-to-comply", "label": "21 · Refusal to comply: 10 seconds to resume"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Protest! The target was broken before I fired.", "meaning": "Ampuja kiistää ratkaisun muodollisesti ja kertoo syyn (tässä: heitettiin rikkinäinen kiekko).", "say": "Protesti! Kiekko oli rikki ennen kuin ammuin."}, {"en": "I’m certain — the decision stands.", "meaning": "Tuomari vahvistaa; ratkaisu on lopullinen.", "say": "Olen varma – ratkaisu pysyy."}, {"en": "Did anyone see a piece come off?", "meaning": "Tuomari on epävarma ja kysyy erältä vain neuvoa; tuomari ratkaisee silti itse.", "say": "Näkikö kukaan palan irtoavan?"}, {"en": "You can take it to the jury in writing, with the deposit.", "meaning": "Tästä ratkaisusta voi valittaa; tarvitaan kirjallinen vetoomus ja vakuusmaksu.", "say": "Voit viedä asian juryyn kirjallisesti vakuusmaksun kanssa."}, {"en": "Please carry on shooting.", "meaning": "Ratkaisu on lopullinen; jatka nyt, tai siitä tulee määräysten noudattamatta jättäminen.", "say": "Jatka ampumista, kiitos."}], "quiz": [{"q": "Ampujasi uskoo, että nollaksi merkitty kiekko oli osuma, mutta hän on jo pyytänyt seuraavaa kiekkoa. Voiko hän vielä protestoida ratkaisusta?", "options": ["Kyllä, kierroksen lopussa", "Kyllä, kirjallisesti juryyn", "Ei: seuraavan kiekon pyytäminen tarkoittaa edellisen ratkaisun hyväksymistä", "Kyllä, jos erä on samaa mieltä"], "answer": 2, "why": "Pyytämällä seuraavaa kiekkoa ampuja hyväksyy edellisen ratkaisun, eikä osuma/ohi-ratkaisuja muutenkaan viedä juryyn."}, {"q": "Mistä ratkaisusta VOI valittaa juryyn?", "options": ["Oliko kiekko osuma vai ohi", "No Birdistä", "Oliko lentorata oikea", "Muusta tuomarin ratkaisusta, kuten myöhästymisrangaistuksesta"], "answer": 3, "why": "Osuma/ohi-, No Bird- ja lentorataratkaisut ovat lopullisia; muista tuomarin ratkaisuista voi valittaa juryyn kirjallisesti vakuusmaksua vastaan."}, {"q": "Kuinka suuri on Parcours de Chasse – Sporting™ -lajissa juryyn tehtävän kirjallisen vetoomuksen vakuusmaksu?", "options": ["40 % osallistumismaksusta", "Koko osallistumismaksu", "Kiinteät 50 euroa", "Vakuusmaksua ei tarvita"], "answer": 0, "why": "Sporting™-säännöt määräävät vakuusmaksuksi 40 % osallistumismaksusta; se palautetaan, jos jury on samaa mieltä ampujan kanssa."}]}, {"id": "referee-categories", "minutes": 5, "title": "Sarjat: Junior, Lady, Men, Senior, Veteran, Master", "body": ["Avoimen tuloslistan lisäksi, jossa kaikki kilpailevat yhdessä, FITASCin kilpailuissa ampujat sijoitetaan iän ja sukupuolen mukaisiin sarjoihin. 1. tammikuuta 2027 alkaen Parcours de Chasse – Sporting™- ja Compak® Sporting -lajien kansainvälisessä taulukossa on kuusi sarjaa: Junior (13–20), Lady (naiset, 13 vuodesta), Men (miehet, 21–55), Senior (56–65), Veteran (66–72) ja Master (73 vuodesta, miehet ja naiset). Sitä aiempia kilpailuja varten tarkista silloin voimassa oleva taulukko FITASCin verkkosivuilta.", "Ratkaisevaa on syntymävuosi, ei syntymäpäivä. Ampuja siirtyy uuteen sarjaan sen vuoden 1. tammikuuta, jona hän täyttää kyseisen iän. Kaudella 2027 tämä tarkoittaa: Junior syntynyt 2007–2014, Men syntynyt 1972–2006, Senior 1962–1971, Veteran 1955–1961, Master syntynyt ennen vuotta 1955. Rajat siirtyvät vuodella joka kausi.", "Tulkin suurin ansa on ”Senior”. Arkienglannissa se voi kuulostaa ”aikuiselta”, mutta FITASCissa Senior tarkoittaa 56–65-vuotiaiden ikäsarjaa; pääasiallinen aikuisten sarja on Men. Älä käännä sitä sanalla ”aikuiset”. Myös ”Master” on ansa: FITASCin 73 vuodesta alkava ikäsarja ei liity mitenkään NSCA:n ”Master class” -luokkaan, joka on taitotaso.", "Joukkueilla on omat sääntönsä: yleensä kolme ampujaa, mutta Sporting™-lajin Men-joukkueessa on neljä. Men-joukkueeseen sijoitetun juniorin tai Lady-joukkueeseen sijoitetun junioritytön on ilmoittauduttava myös henkilökohtaisesti kyseiseen sarjaan. Kansalliset liitot ja seurat voivat käyttää omia sarjojaan, joten tarkista aina kilpailun ohjelma, ja muista uusintakierroksissa, että sarjoilla on omat kolme parastaan."], "key_points": ["Kuusi FITASCin sarjaa vuodesta 2027: Junior, Lady, Men, Senior, Veteran, Master", "Syntymävuosi ratkaisee; uusi sarja alkaa 1. tammikuuta", "Senior = 56–65, ei ”aikuiset”; pääasiallinen aikuisten sarja on Men", "FITASCin Master (73+) ≠ NSCA:n Master class", "Joukkueissa 3; Sporting™-lajin Men-joukkue = 4; kansalliset ohjelmat voivat erota"], "terms": ["category", "veteran", "team", "shoot-off", "entry"], "sources": [{"title": "FITASC — Categories", "url": "https://www.fitasc.com/competitions/categories"}], "sim": null, "rule_refs": [{"book": "categories", "id": "junior", "label": "Junior"}, {"book": "categories", "id": "lady", "label": "Lady"}, {"book": "categories", "id": "men", "label": "Men"}, {"book": "categories", "id": "senior", "label": "Senior"}, {"book": "categories", "id": "veteran", "label": "Veteran"}, {"book": "categories", "id": "master", "label": "Master"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}], "coach_says": [{"en": "Which category are you shooting in?", "meaning": "Kysytään ilmoittautumisessa: Junior, Lady, Men, Senior, Veteran vai Master.", "say": "Missä sarjassa ammut?"}, {"en": "He’s a Senior now.", "meaning": "Hän kuuluu tällä kaudella 56–65-vuotiaiden sarjaan.", "say": "Hän on nyt Senior-sarjassa."}, {"en": "She won the Lady category and was fourth overall.", "meaning": "Ensimmäinen naisten joukossa, neljäs avoimessa tuloslistassa.", "say": "Hän voitti Lady-sarjan ja oli kokonaiskilpailussa neljäs."}, {"en": "There’s a shoot-off for Veteran bronze.", "meaning": "Kaksi tai useampi Veteran-sarjan ampuja on tasapisteissä sarjansa kolmannesta sijasta.", "say": "Veteran-sarjan pronssista ammutaan uusinta."}], "quiz": [{"q": "Vuonna 1971 syntynyt ampuja osallistuu FITASCin kilpailuun vuonna 2027. Mikä sarja?", "options": ["Men", "Senior", "Veteran", "Master"], "answer": 1, "why": "Hän täyttää 56 vuonna 2027, joten hän on Senior-sarjassa 1. tammikuuta alkaen syntymäpäivästään riippumatta."}, {"q": "Miten sinun pitäisi kääntää FITASCin sarja ”Senior” asiakkaalle?", "options": ["”Aikuiset”", "”Kokeneet ampujat”", "”Huippuluokka”", "”56–65-vuotiaiden ikäsarja”"], "answer": 3, "why": "FITASCissa Senior on 56–65-vuotiaiden ikäsarja; pääasiallinen aikuisten sarja on Men."}, {"q": "Montako ampujaa on Parcours de Chasse – Sporting™ -lajin Men-joukkueessa?", "options": ["Neljä", "Kolme", "Kuusi", "Viisi"], "answer": 0, "why": "Joukkueissa on yleensä kolme ampujaa, mutta Sporting™-lajin Men-joukkueessa on neljä."}]}]}, {"id": "etiquette", "icon": "shield", "title": "Turvallisuus ja etiketti", "intro": "Ampumaradalla turvallisuus menee kaiken kääntämisen edelle, ja hyvät tavat pitävät erän rauhallisena ja keskittyneenä. Tässä tehtävässä näet, miten aseita käsitellään, miten ampumapaikan lähellä ja erässä käyttäydytään ja mitä kaikkien, myös sinun, on pidettävä yllä.", "lessons": [{"id": "etiquette-gun-safety", "minutes": 5, "title": "Aseturvallisuus: auki, tyhjä, piiput turvalliseen suuntaan", "body": ["Jokaista asetta pidetään vaarallisena, myös tyhjänä. Ampumapaikan ulkopuolella sitä kannetaan avattuna: päällekkäispiippuinen haulikko taitettuna kyynärvarren päälle, puoliautomaattihaulikko lukko auki, piiput suoraan ylös tai suoraan alas. Kantohihnat eivät ole sallittuja. Kun asetta ei käytetä, se seisoo pystyssä asetelineessä. Kukaan ei koske toisen ampujan aseeseen ilman lupaa.", "Patruunat laitetaan aseeseen vain ampumapaikalla, piiput suunnattuina ampuma-alueelle, ja vain kun tuomari tai ohjaaja sen sallii. Puoliautomaattiin saa ladata enintään kaksi patruunaa. Ennen kuin ampuja kääntyy ampumapaikalla ympäri, hän avaa aseen ja poistaa kaikki patruunat, ammutut ja ampumattomat. Näytekiekkojen aikana ja jokaisen keskeytyksen ajan aseet pidetään avattuina.", "Jos ase ei laukea, ampuja pysyy paikallaan ase suunnattuna ampuma-alueelle eikä avaa asetta tai koske varmistimeen ennen kuin tuomari on tarkastanut sen. Tämä on yhtä aikaa turvallisuussääntö ja pisteytyssääntö: liian aikainen avaaminen maksaa kiekon. Aseen nostaminen ja heilauttaminen kuvitellun kiekon mukana ampumapaikan ulkopuolella tai toisen ampuessa ei myöskään ole sallittua, ja aseita koeammutaan vain koeampumapaikalla, ei koskaan kilpailun ampumapaikalla.", "Kun joku huutaa ”Stop!” tai ”Cease fire!”, kaikki lopettavat heti ja avaavat aseensa. Älä käännä tätä kokonaiseksi lauseeksi: toista ”Stop!” kovaa vieraidesi kielellä ja tarkista, että heidän aseensa ovat auki. Jos vieras kääntyy sinua kohti ase kädessä kysyäkseen jotakin, ohjaa ensin eleellä piiput alas ja käännä vasta sitten."], "key_points": ["Ampumapaikan ulkopuolella: ase auki, tyhjä, piiput ylös tai alas, ei kantohihnoja", "Lataa vain ampumapaikalla, ampuma-alueelle päin, luvan kanssa; puoliautomaatissa enintään 2", "Avaa ja tyhjennä ennen kääntymistä; aseet auki näytekiekkojen ja keskeytysten aikana", "Laukeamattoman patruunan jälkeen: pysy paikallasi, älä avaa, odota tuomaria", "”Stop!” toistetaan, ei selitetä"], "terms": ["safety", "gun-handling", "muzzle", "gun-rack", "loading", "malfunction", "mock-shooting", "gun-test", "cease-fire", "semi-automatic"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "sporting", "id": "ch7-touching-sharing", "label": "7 · Other shooters' guns; sharing a gun"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "sporting", "id": "ch3-testing-guns", "label": "3 · No test shots on the stand"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-open-gun", "label": "21 · Keep the gun open: turning round, target viewing, interruptions"}, {"book": "compak", "id": "ch11-testing-guns", "label": "11 · Where to test your gun"}], "coach_says": [{"en": "Guns open and empty between stands, please.", "meaning": "Seuraavalle ampumapaikalle kävellessä ase on taitettuna eikä siinä ole patruunoita.", "say": "Aseet auki ja tyhjinä ampumapaikkojen välillä, kiitos."}, {"en": "Break your gun and show me it’s clear.", "meaning": "Avaa ase (älä riko sitä!), jotta näen, että patruunapesät ovat tyhjät.", "say": "Taita ase ja näytä, että se on tyhjä."}, {"en": "Don’t load until you’re on the stand and I say so.", "meaning": "Aseessa ei ole patruunoita kävellessä eikä odottaessa.", "say": "Älä lataa ennen kuin olet ampumapaikalla ja minä annan luvan."}, {"en": "Muzzles down when you turn round.", "meaning": "Älä koskaan anna piippujen osoittaa ihmisiä, ei edes avatulla aseella.", "say": "Piiput alas, kun käännyt."}, {"en": "Stop! Stop! Guns open!", "meaning": "Hätäpysäytys: lopeta ampuminen, avaa ase, odota.", "say": "Stop! Stop! Aseet auki!"}], "quiz": [{"q": "Miten puoliautomaattihaulikkoa kannetaan ampumapaikkojen välillä?", "options": ["Suljettuna, varmistin päällä", "Lukko auki, piippu suoraan ylös tai alas", "Kantohihnassa olalla", "Yhdellä patruunalla ladattuna"], "answer": 1, "why": "Aseita kannetaan avattuina, puoliautomaatit lukko auki, piiput suoraan ylös tai alas; kantohihnat eivät ole sallittuja."}, {"q": "Ase naksahtaa mutta ei laukea. Mitä ampujan on tehtävä?", "options": ["Avattava se heti ja katsottava", "Käännyttävä näyttämään sitä valmentajalle", "Pysyttävä paikallaan ase ampuma-alueelle päin, avaamatta sitä tai koskematta varmistimeen, kunnes tuomari tarkastaa sen", "Laitettava varmistin päälle ja pyydettävä uudelleen"], "answer": 2, "why": "Molemmat sääntökirjat edellyttävät, että ampuja pysyy paikallaan, kunnes tuomari tarkastaa aseen; avaaminen tai varmistimeen koskeminen ensin merkitään nollaksi."}, {"q": "Joku huutaa ”Cease fire!”. Mikä on tulkin ensimmäinen tehtävä?", "options": ["Toistaa ”Stop!” kovaa ja tarkistaa, että vieraat avaavat aseensa", "Selittää, miksi ammunta keskeytettiin", "Kysyä valmentajalta, mitä tapahtui", "Odottaa, kunnes vieras kysyy"], "answer": 0, "why": "Hätäpysäytys toistetaan heti; selitysten aika on vasta, kun jokainen ase on auki."}]}, {"id": "etiquette-on-the-stand", "minutes": 5, "title": "Ampumapaikan ympärillä: hiljaisuus, etäisyys, liikkumattomuus", "body": ["Ampumapaikalla oleva ampuja tarvitsee täydellistä keskittymistä latauksesta siihen asti, kun hän avaa aseen viimeisen laukauksen jälkeen. Säännöt sijoittavat odotuspaikat lähelle ampumapaikkaa, mutta niistä ei saa häiritä ampujaa. Käytännössä tämä tarkoittaa: hiljaisia ääniä tai ei lainkaan puhetta, ei äkillisiä liikkeitä ampujan näkökentässä, aseet auki ja puhelimet äänettömällä taskussa. Säännöt eivät mainitse puhelimia, mutta jokainen rata odottaa tätä kohteliaisuutta.", "Pysy ampujan takana, älä koskaan ampumapaikan vieressä tai edessä. Compak® Sporting -lajissa ampumakulman rajoitin (Firing Angle Limiter) rajoittaa jokaisen ampujan aseen liikettä; Parcours de Chasse – Sporting™ -lajissa monien ratojen ampumapaikoilla on häkki. Kaikki muut odottavat sen takana, kaikkien mahdollisten piippulinjojen ulkopuolella. Compak®-lajissa odottava ampuja seisoo ampumapaikan 1 takana, ja ampunut ampuja odottaa häiritsemättä seuraavaa.", "Ampujan häiritsemisellä on sääntöseurauksia. Jos tuomari näkee, että ampujaa selvästi häirittiin, kiekko on No Bird (uusi kiekko) ja heitetään uudelleen. Tähtäysharjoittelu toisen erän jäsenen ampuessa ei ole sallittua. Vain se ampuja, jonka vuoro on, ampuu, ja vain omaan kiekkoonsa.", "Sinulle tämä oppitunti on käytännöllinen. Lopeta puhuminen, kun vieraasi astuu ampumapaikalle, vaikka kesken lauseen. Älä vastaa kysymyksiin, kun ase on suljettu. Puhu uudelleen vasta, kun ase on auki: kiekkojen välillä, kaksoiskiekkojen välillä tai ampumapaikan jälkeen. Väliin jäänyt neuvo maksaa vähemmän kuin äänesi pilaama kaksoiskiekko."], "key_points": ["Hiljaa, liikkumatta, aseet auki, puhelimet äänettömällä ampujan takana", "Seiso ampumapaikan, häkin tai rajoittimen takana, ei koskaan vieressä tai edessä", "Selvästi häiritty ampuja saa No Birdin", "Ei tähtäysharjoittelua toisen ampuessa", "Tulkki: puhu vain, kun ase on auki"], "terms": ["quiet-on-stand", "shooting-stand", "conduct", "no-bird", "mock-shooting", "rotation"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch8-own-turn-live-animals", "label": "8 · Shoot only in turn; not at others' targets or animals"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}], "coach_says": [{"en": "Quiet behind, please — she’s on.", "meaning": "Ampuja on ampumapaikalla; kaikki lopettavat puhumisen.", "say": "Hiljaa takana, kiitos – hän ampuu nyt."}, {"en": "Wait until he’s opened his gun.", "meaning": "Kukaan ei puhu eikä liiku, ennen kuin ampuja on valmis ja avannut aseen.", "say": "Odota, kunnes hän on avannut aseensa."}, {"en": "Stand right behind me so you can see what I see.", "meaning": "Harjoituksissa valmentaja haluaa sinut suoraan taakseen, aseen liikeradan ulkopuolelle.", "say": "Seiso suoraan takanani, niin näet saman kuin minä."}, {"en": "Keep out of his line, please.", "meaning": "Olet ampujan näkökentässä tai lähellä piippujen liikerataa; siirry taaksepäin.", "say": "Pysy pois hänen linjaltaan, kiitos."}], "quiz": [{"q": "Missä tulkki seisoo vieraan ampuessa?", "options": ["Ampujan vieressä nähdäkseen hänen kasvonsa", "Ampumapaikan edessä nähdäkseen kiekon", "Ampumapaikan takana, kaikkien piippulinjojen ulkopuolella", "Missä tahansa, missä tuomari ei näe"], "answer": 2, "why": "Kaikki odottavat ampumapaikan tai häkin takana; ampujan vieressä on vaarallisin paikka."}, {"q": "Äänekäs puhelu ampumapaikan takana häiritsee selvästi ampujaa laukaushetkellä. Mitä tuomari voi päättää?", "options": ["No Bird: kiekko heitetään uudelleen", "Nolla ampujalle", "Ei mitään, puhelimia ei mainita säännöissä", "Keltainen kortti ampujalle"], "answer": 0, "why": "Jos tuomari näkee, että ampujaa selvästi häirittiin, kiekko on No Bird."}, {"q": "Milloin on oikea hetki välittää valmentajan kommentti?", "options": ["Kun ampuja pyytää kiekkoa", "Kiekon pyytämisen ja laukauksen välissä", "Heti kun valmentaja lopettaa puhumisen", "Kun ase on auki: kiekkojen tai kaksoiskiekkojen välillä tai ampumapaikan jälkeen"], "answer": 3, "why": "Ampujan rutiinia ei saa keskeyttää; puhu vasta, kun ase on auki."}]}, {"id": "etiquette-squad", "minutes": 5, "title": "Käytöstavat erässä", "body": ["Erä on enintään kuuden arvalla valitun ampujan ryhmä, joka ampuu yhdessä. Täsmällisyys on ensimmäinen kohteliaisuus ja samalla sääntö. Parcours de Chasse – Sporting™ -lajissa puuttuvaa ampujaa kutsutaan kolme kertaa yhden minuutin aikana, ja ampumatta jääneet kiekot merkitään nolliksi. Compak® Sporting -lajissa ampuja, joka saapuu sen jälkeen, kun erän ensimmäinen ampuja on pyytänyt kiekkoa, saa kierrokselta 25 nollaa, ja ilmoittautuminen tuomarille etukäteen on pakollista.", "Järjestyksellä on merkitystä. Sporting™-lajissa ampumajärjestys kiertää jokaisella ampumapaikalla ja kaksoiskiekoissa; Compak®-lajissa ampujat siirtyvät jokaisen sarjan jälkeen yhden ampumapaikan oikealle. Kukaan ei astu ampumapaikalle ennen kuin edellinen ampuja on poistunut siltä. Kun ampuja kutsutaan, hän on heti valmis, ja hänellä on patruunoita koko kierrokselle.", "Tuomari ratkaisee yksin. Erän jäsenet eivät kommentoi, osuiko kiekkoon, ellei tuomari kysy heiltä. Ratkaisun avoin arvostelu, olipa se ampujien tai katsojien, katsotaan yritykseksi vaikuttaa tuomariin. Itsehillinnän menettäminen, esimerkiksi aseen heittäminen tai kenen tahansa solvaaminen, viedään juryn käsiteltäväksi ja voi johtaa kilpailusta sulkemiseen.", "Sääntöjen lisäksi on tapoja. Ampujat tervehtivät yleensä tuomaria ja erää alussa, sanovat hyvän ampumapaikan jälkeen ”good shot” tai ”well shot” (hyvä laukaus, hienosti ammuttu) ja ohilaukauksen jälkeen ”bad luck” (huono tuuri), mutta eivät koskaan kommentoi vieraan ampujan tekniikkaa. Kiitos heittäjälle ja tuomarille lopuksi, kättely ja rauhallisuus tulosten tullessa julki ovat tavallisia monilla radoilla. Käännä nämä kohteliaisuudet lämpimästi; niillä on merkitystä."], "key_points": ["Ole ajoissa ja ilmoittaudu tuomarille; myöhästyminen maksaa nollia", "Noudata ampumajärjestystä; astu paikalle vasta, kun se on vapaa", "Vain tuomari ratkaisee; ei kommentteja osumista", "Itsehillinnän menettäminen voi johtaa kilpailusta sulkemiseen", "Tavat: tervehdi, ”well shot”, kiitä heittäjää ja tuomaria"], "terms": ["squad", "rotation", "referee", "trapper", "conduct", "round"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-ready", "label": "9 · Be ready with a full round of equipment and ammunition"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch21-loss-of-control", "label": "21 · Loss of self-control"}], "coach_says": [{"en": "Number twelve — last call!", "meaning": "Tuomari kutsuu puuttuvaa ampujaa; jos hän ei tule, hänen kiekkonsa merkitään nolliksi.", "say": "Numero kaksitoista – viimeinen kutsu!"}, {"en": "You’re next — get ready.", "meaning": "Valmistaudu nyt: lasit, kuulosuojaimet, patruunat, mutta älä astu paikalle ennen kuin se on vapaa.", "say": "Olet seuraava – valmistaudu."}, {"en": "Well shot!", "meaning": "Vilpitön kehu hyvän kiekon tai ampumapaikan jälkeen.", "say": "Hienosti ammuttu!"}, {"en": "Bad luck.", "meaning": "Ystävällinen myötätunnon ilmaus ohilaukauksen jälkeen, ei arvostelua.", "say": "Huono tuuri."}, {"en": "Thanks, ref — thanks for pulling.", "meaning": "Tuomarin ja heittäjän kiittäminen kierroksen lopussa.", "say": "Kiitos, tuomari – kiitos heitoista."}], "quiz": [{"q": "Compak® Sporting, erissä ammunta: vieraasi saapuu sen jälkeen, kun hänen eränsä ensimmäinen ampuja on pyytänyt ensimmäistä kiekkoa. Mitä tapahtuu?", "options": ["Hän liittyy mukaan seuraavalla ampumapaikalla", "Hän saa kierrokselta 25 nollaa", "Hän ampuu viimeisenä ilman rangaistusta", "Kierros aloitetaan alusta"], "answer": 1, "why": "Compak®-lajin erissä ammuttaessa takaraja on erän ensimmäinen kiekon pyyntö; sen jälkeen myöhästynyt ampuja saa 25 nollaa (vetoomus juryyn on mahdollinen)."}, {"q": "Erätoveri sanoo kovaan ääneen tuomarille, että tämä on väärässä osumasta. Miten säännöt suhtautuvat tähän?", "options": ["Hyödyllisenä tietona", "Muodollisena protestina", "Yrityksenä vaikuttaa tuomariin", "Ei mitenkään"], "answer": 2, "why": "Kun muut arvostelevat ratkaisua avoimesti ilman tuomarin lupaa, se katsotaan vaikuttamisyritykseksi; vain asianomainen ampuja voi protestoida."}, {"q": "Miten ampumajärjestys toimii erässä Parcours de Chasse – Sporting™ -lajissa?", "options": ["Se kiertää jokaisella ampumapaikalla ja kaksoiskiekoissa", "Se on kiinteä koko päivän", "Paras ampuja aloittaa aina", "Tuomari valitsee vapaasti"], "answer": 0, "why": "Kuuden ampujan erät arvotaan, ja järjestys kiertää jokaisella ampumapaikalla sekä myös kaksoiskiekoissa."}]}, {"id": "etiquette-protection-and-dress", "minutes": 5, "title": "Kuulo, silmät ja pukeutuminen – myös sinun", "body": ["Kuulosuojaimet ovat pakolliset kaikille rataosuudella tai sen lähellä oleville: ampujille, tuomareille, henkilökunnalle ja katsojille. Parcours de Chasse – Sporting™ -lajissa ampumalasit ovat poikkeuksetta pakolliset ampujille, tuomareille, henkilökunnalle ja kaikille ampumapaikan lähellä oleville. Compak® Sporting -lajissa silmäsuojaussääntö mainitsee kilpailijat, tuomarit ja henkilökunnan. Ampuja, joka tulee ampumapaikalle ilman jompaakumpaa, katsotaan poissaolevaksi.", "Tämä koskee myös sinua. Seisoessasi ampumapaikan takana olet ”rataosuuden lähellä”. Aktiivikuulosuojaimet (elektroniset kuulosuojaimet) ovat tulkin paras työkalu: ne vaimentavat laukauksen mutta päästävät puheen läpi, joten kuulet valmentajan ja tuomarin. Kirkkaat tai sävytetyt ampumalasit suojaavat myös putoavilta kiekon sirpaleilta; lippalakki auttaa myös.", "Pukeutumissäännöt koskevat turvallisuutta ja kunnioitusta. Ei lyhyitä shortseja: vain pitkät bermudatyyppiset shortsit, jotka päättyvät enintään 5 cm polven yläpuolelle. Paidoissa on oltava vähintään lyhyet hihat ja kaulus tai pyöreä, T-paidan kaltainen pääntie; liivi paljaan rinnan päällä ei ole sallittu. Sandaalit on kielletty, ja Compak®-lajissa tämä koskee sekä harjoituksia että kilpailuja. Kilpailunumero pidetään selässä hartioiden ja vyötärön välissä kokonaan näkyvissä, taittamatta tai leikkaamatta.", "Ensimmäisestä pukeutumis- tai numerosääntöjen rikkeestä seuraa varoitus; jos asiaa ei korjata, seuraa rangaistuksia aina juryn päättämään kilpailusta sulkemiseen asti. Seremonioissa joukkueiden jäsenet pukeutuvat maajoukkueasuun tai siisteihin housuihin ja bleiseriin, ja kaikkien palkittujen on osallistuttava palkintojenjakoon. Pukeudu kuin rauhallinen ammattilainen: umpinaiset kengät, neutraalit vaatteet, ei mitään, mikä lepattaa tai kimaltaa ampujan silmiin."], "key_points": ["Kuulosuojaimet kaikille rataosuuden lähellä, myös katsojille ja tulkeille", "Lasit: Sporting™ – kaikki ampumapaikan lähellä; Compak® – kilpailijat, tuomarit, henkilökunta", "Ilman niitä ampuja katsotaan poissaolevaksi", "Bermudat enintään 5 cm polven yläpuolelle, hihat, ei paljasta rintaa liivin alla, ei sandaaleja", "Numero selässä kokonaan näkyvissä; ensimmäinen rike = varoitus"], "terms": ["hearing-protection", "electronic-ear-muffs", "earplugs", "safety-glasses", "dress-code", "competitor-number", "shooting-vest", "prize-giving"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "sporting", "id": "ch17-ceremonies", "label": "17 · Dress at the opening and closing ceremonies"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch7-ceremonies", "label": "7 · Dress for opening and closing ceremonies"}], "coach_says": [{"en": "Eyes and ears on before you leave the clubhouse.", "meaning": "Laita lasit ja kuulosuojaimet ennen kuin kävelet rataosuuksille.", "say": "Lasit ja kuulosuojaimet päähän ennen kuin lähdet klubitalolta."}, {"en": "Where are your ears?", "meaning": "”Ears” = kuulosuojaimet, ei itse korvat.", "say": "Missä kuulosuojaimesi ovat?"}, {"en": "You can’t shoot in sandals here.", "meaning": "Umpinaiset kengät vaaditaan turvallisuuden vuoksi.", "say": "Täällä ei voi ampua sandaaleissa."}, {"en": "Your number’s folded — it has to be fully visible.", "meaning": "Selässä olevan kilpailunumeron on oltava kokonainen ja näkyvissä; muuten seuraa varoitus.", "say": "Numerosi on taitettu – sen on oltava kokonaan näkyvissä."}], "quiz": [{"q": "Ampujasi kävelee ampumapaikalle ilman ampumalaseja. Miten säännöt kohtelevat häntä?", "options": ["Hän saa varoituksen ja saa ampua", "Hän saa ampua, jos valmentaja suostuu", "Hän menettää yhden kiekon", "Hänet katsotaan poissaolevaksi"], "answer": 3, "why": "Molemmissa lajeissa ampuja, jolla ei ole ampumapaikalla silmä- tai kuulosuojaimia, katsotaan poissaolevaksi."}, {"q": "Millaiset shortsit ovat sallittuja?", "options": ["Mitkä tahansa urheilushortsit", "Bermudatyyppiset shortsit, jotka päättyvät enintään 5 cm polven yläpuolelle", "Shortsit vain Compak®-lajissa", "Ei minkäänlaisia shortseja"], "answer": 1, "why": "Lyhyet shortsit on kielletty; pitkät bermudatyyppiset shortsit, jotka ovat enintään 5 cm polven yläpuolella, hyväksytään."}, {"q": "Miksi aktiivikuulosuojaimet ovat hyvä valinta tulkille?", "options": ["Ne vaimentavat laukauksen mutta päästävät puheen läpi", "Niitä ei vaadita tulkeilta", "Ne estävät kaiken äänen kokonaan", "Ne nauhoittavat valmentajan"], "answer": 0, "why": "Kuulosuojaimet ovat pakolliset rataosuuden lähellä, ja aktiivikuulosuojaimilla kuulet valmentajan ja tuomarin."}]}]}, {"id": "interpreter", "icon": "speech", "title": "Tulkki työssä", "intro": "Tässä kaikki oppimasi kokoontuu yhteen: mitä saat sanoa ja mitä et, missä seistä, sanat, jotka hämäävät kokeneitakin kielenammattilaisia, luvut ja yksiköt, brittiläinen ja amerikkalainen sanasto ja lopuksi kokonainen harjoitus ensimmäisestä ”huomenta” -tervehdyksestä loppukeskusteluun.", "lessons": [{"id": "interpreter-role", "minutes": 5, "title": "Roolisi: harjoitus vai kilpailu", "body": ["Harjoituksissa olet valmentajan ääni. Välitä jokainen ohje kokonaan, valmentajan järjestyksessä ja sävyssä: jämäkästi, kun on kyse turvallisuudesta, lämpimästi, kun on kyse kehusta. Älä pehmennä arvostelua, älä lisää perusteluja, joita valmentaja ei antanut, äläkä koskaan lisää omia tekniikkavinkkejäsi, vaikka tietäisit vastauksen. Jos et kuullut jotakin sanaa, kysy ennen kuin käännät.", "Kilpailu on eri asia. Kilpailijan valmentaminen kilpailun aikana on kielletty sekä Parcours de Chasse – Sporting™- että Compak® Sporting -lajissa: ampuja saa keltaisen kortin, toistuvista rikkeistä seuraa lisää seuraamuksia, ja tuomari poistaa valmentaneen henkilön ampuma-alueelta. Tuomari myös ratkaisee yksin: kukaan erässä ei kommentoi osumia, ja ratkaisun avoin arvostelu katsotaan yritykseksi vaikuttaa tuomariin.", "Nyt rehellinen osuus. FITASCin sääntökirjat eivät mainitse tulkkeja lainkaan. Säännöt eivät kerro, katsotaanko valmentajan neuvon välittäminen sanasta sanaan kilpailun aikana valmentamiseksi, eivätkä sitä, missä tulkki saa seistä. Se on FITASCille avoin kysymys, eikä sinun pidä esittää mitään vastausta virallisena.", "Kunnes FITASC vastaa, noudata turvallista käytäntöä. Kilpailussa tulkkaa vain viestintää tuomarin, juryn ja järjestäjän kanssa: kiekon pyynnöt, ratkaisut, varoitukset, protestit, ajat ja erät. Kerro ennen kilpailua tuomarille tai järjestäjälle, kuka olet, ja sovi, missä seisot. Jos valmentaja pyytää sinua välittämään neuvoja kilpailun aikana, kieltäydy kohteliaasti ja kerro miksi. Se suojaa ampujaasi keltaiselta kortilta."], "key_points": ["Harjoitus: valmentajan ääni – kokonaan, samalla sävyllä, ei mitään omaa", "Kilpailu: valmentaminen on kielletty (keltainen kortti, valmentaja poistetaan)", "Avoin kysymys FITASCille: sääntökirjat eivät mainitse tulkkeja", "Turvallinen käytäntö: kilpailussa tulkkaa vain tuomarin, juryn ja järjestäjän viestintää", "Esittäydy tuomarille ja sovi, missä seisot"], "terms": ["coach", "referee", "jury", "yellow-card", "conduct", "interpreter", "coaching"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Tell her she’s lifting her head on the second bird.", "meaning": "Harjoitus: välitä se kokonaan, kun ase on auki.", "say": "Kerro hänelle, että hän nostaa päänsä toisella kiekolla."}, {"en": "Quick — tell him to give the crosser more.", "meaning": "Kilpailu: tämä on valmentamista. Kieltäydy kohteliaasti; älä välitä sitä.", "say": "Nopeasti – sano hänelle, että antaa sivukiekolle lisää."}, {"en": "Who are you with?", "meaning": "Tuomari kysyy, miksi olet ampumapaikan lähellä; esittäydy ja kerro roolisi.", "say": "Kenen kanssa olet?"}, {"en": "Ask the referee if I can still change chokes.", "meaning": "Menettelyä koskeva kysymys tuomarille: saat tulkata sen.", "say": "Kysy tuomarilta, saanko vielä vaihtaa supistajia."}], "quiz": [{"q": "Kilpailukierroksen aikana valmentaja pyytää sinua sanomaan ampujalle ”more lead on the crosser”. Mitä teet?", "options": ["Kuiskaan sen nopeasti", "Käännän sen seuraavan kiekon jälkeen", "Kieltäydyn kohteliaasti: se olisi valmentamista, joka on kielletty", "Pyydän tuomaria välittämään sen"], "answer": 2, "why": "Valmentaminen kilpailun aikana on kielletty, ja ampuja saisi keltaisen kortin; säännöt eivät kerro, onko neuvojen välittäminen sallittua, joten pelaa varman päälle."}, {"q": "Mitä FITASCin sääntökirjat sanovat tulkeista?", "options": ["He saavat seistä ampumapaikalla", "He tarvitsevat tuomarin lisenssin", "Heidät rinnastetaan valmentajiin", "Ei mitään: se on avoin kysymys"], "answer": 3, "why": "Sääntökirjat eivät mainitse tulkkeja, joten heidän tarkka asemansa kilpailussa on FITASCille avoin kysymys."}, {"q": "Harjoituksissa valmentaja sanoo ”Not bad, but you stopped the gun.” Miten käännät?", "options": ["Kokonaan ja samalla sävyllä, molemmat osat", "Vain kehun, jotta vieras pysyy tyytyväisenä", "Vain virheen, ajan säästämiseksi", "Lisään oman vinkkini sen korjaamiseksi"], "answer": 0, "why": "Et pehmennä etkä paisuttele: koko viesti, valmentajan sävyssä, ilman mitään omaa."}]}, {"id": "interpreter-position", "minutes": 5, "title": "Missä seistä ja milloin puhua", "body": ["Harjoituksissa seiso suoraan ampujan takana valmentajan vieressä, ampumapaikan tai häkin takana ja kaikkien piippulinjojen ulkopuolella. Sieltä näet saman kuin valmentaja, kiekon ja piipunsuut yhtä aikaa, ja valmentaja voi puhua sinulle hiljaa. Ampujan vieressä on vaarallisin paikka; ampumapaikan edessä seisominen ei tule kysymykseen.", "Valitse tilanteeseen sopiva tulkkaustapa. Konsekutiivitulkkaus (valmentaja puhuu, pitää tauon, sinä puhut) sopii turvallisuusohjeistukseen, kävelyyn ampumapaikkojen välillä ja loppukeskusteluun. Kuiskaustulkkaus (chuchotage) antaa valmentajan jatkaa puhumista, kun kuiskaat ampujan korvaan takaa; se on väsyttävää, joten vuorottele näitä kahta. Sovi ”tauko, käännän” -merkistä, esimerkiksi nostetusta kämmenestä.", "Ajoitus on kaikki kaikessa. Ampujan rutiini kestää aseen sulkemisesta laukaukseen. Puhu vain, kun ase on auki: kiekkojen välillä, kaksoiskiekkojen välillä, ampumapaikan jälkeen. Kaksoiskiekkojen välillä toista valmentajan lyhyet vihjeet, ”more in front”, ”head down”, ”same again”, ja jätä pitkät selitykset myöhemmäksi. Muista kello: Parcours de Chasse – Sporting™ -lajissa ampujalla on enintään 15 sekuntia kiekkojen tai kaksoiskiekkojen välillä, ja Compak® Sporting -lajissa 10 sekuntia kiekon pyytämiseen. Sinun sanasi kuluttavat myös sitä aikaa.", "Kilpailussa odota siellä, missä erä odottaa, lähellä ampumapaikkaa mutta häiritsemättä koskaan ampujaa: selvästi häiritty ampuja saa No Birdin, eikä kukaan halua olla sen syy. Opettele valmentajan käsimerkit alussa ja käännä ne kerran vieraillesi; sen jälkeen he tarvitsevat sinua vähemmän, ja se on hyvä merkki."], "key_points": ["Harjoitus: suoraan ampujan takana, valmentajan vieressä, piippulinjan ulkopuolella", "Konsekutiivi ohjeistuksiin ja loppukeskusteluun; kuiskaus ampumapaikalla; vuorottele", "Puhu vain, kun ase on auki", "Lyhyet vihjeet kaksoiskiekkojen välillä; aikarajat 15 s (Sporting™) ja 10 s (Compak®)", "Kilpailu: odota erän kanssa, älä koskaan häiritse"], "terms": ["quiet-on-stand", "shooting-stand", "coach", "firing-time", "no-bird", "chuchotage", "consecutive-interpreting", "hand-signals"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Stand right behind me.", "meaning": "Valmentajan ja ampujan takana, aseen liikeradan ulkopuolella.", "say": "Seiso suoraan takanani."}, {"en": "Head on the stock — just whisper it to him, I’ll keep going.", "meaning": "Siirry kuiskaustulkkaukseen ja välitä vihje hiljaa; valmentaja ei pidä taukoa.", "say": "Pää tukille – kuiskaa se hänelle, minä jatkan."}, {"en": "When I do this — hands apart — it means more in front.", "meaning": "Valmentaja selittää käsimerkin; käännä se kerran koko ryhmälle.", "say": "Kun teen näin – kädet erilleen – se tarkoittaa enemmän eteen."}, {"en": "Wait — let him finish the pair.", "meaning": "Pidätä neuvo, kunnes ase on taas auki.", "say": "Odota – anna hänen ampua pari loppuun."}, {"en": "Sorry — did you say “under it” or “on it”?", "meaning": "Kysy takaisin kahdella kuulemallasi vaihtoehdolla; nopeampaa kuin ”toista, kiitos”.", "say": "Anteeksi – sanoitko ”under it” vai ”on it”?"}], "quiz": [{"q": "Missä sinun pitäisi seistä harjoituksen aikana Sporting™-ampumapaikalla?", "options": ["Ampujan vieressä, jotta näet silmät", "Ampujan takana valmentajan vieressä, piippulinjan ulkopuolella", "Häkin edessä kasvot ampujaan päin", "Heittimen vieressä"], "answer": 1, "why": "Takaa näet saman kuin valmentaja ja pysyt turvassa; vieressä tai edessä on vaarallista."}, {"q": "Mitä on chuchotage?", "options": ["Tulkkausta sen jälkeen, kun puhuja pitää tauon", "Sääntöjen kirjallista kääntämistä", "Käsimerkkien kääntämistä", "Kuiskattua simultaanitulkkausta kuulijan korvaan"], "answer": 3, "why": "Chuchotage on kuiskattua simultaanitulkkausta; konsekutiivi on tauko ja puhe -tapa."}, {"q": "Kuinka kauan Compak® Sporting -lajissa ampujalla on aikaa pyytää kiekkoa sen jälkeen, kun edellisen ampumapaikan kiekko on ammuttu?", "options": ["10 sekuntia", "15 sekuntia", "30 sekuntia", "Ei rajaa"], "answer": 0, "why": "Compak® antaa kiekon pyytämiseen enintään 10 sekuntia; Sporting™ sallii 15 sekuntia kiekkojen tai kaksoiskiekkojen välillä."}]}, {"id": "interpreter-false-friends", "minutes": 6, "title": "Harhaanjohtavat sanat ampumaradalla", "body": ["Pahin ansa on savu. Valmentajan ”Smoked it!” (tai ”inked it”, ”powdered it”) tarkoittaa täydellistä osumaa: kiekko katosi pilveen. Mutta säännöissä kiekko, josta irtoaa vain pölyä tai savua ilman näkyvää palaa, on nolla. ”Chip”, pieni näkyvä pala, on osuma. Käännä siis valmentajan ”smoked it” muotoon ”pölyksi!” tai ”täysosuma”, ja tuomarin ”only dust” muotoon ”vain pölyä – ohi”.", "Pisteytyssanat eivät ole kirjaimellisia. ”Dead” ja ”kill” tarkoittavat osumaa, eivät koskaan ”kuollut” tai ”tappo”. ”Lost” on ohilaukaus (ohi, nolla), ei ”kadonnut”. ”Dropped two” tarkoittaa kahta ohi mennyttä kiekkoa. ”Straight” sanonnassa ”25 straight” tarkoittaa virheetöntä sarjaa, ei ”suoraan”.", "Varuste- ja paikkasanat. ”Trap” on heitin eli kiekonheitinkone, ei ”ansa” (Trap on myös olympialaji). ”Stand” on yksi ampumapaikka, ei ”teline” eikä koko rata; ”peg” on merkitty ampumapaikka, ei ”tappi”; ”broken gun” on avattu ase. ”Pull!” on kiekon pyyntö, ”pull-away” ennakkomenetelmä, ”length of pull” tukin mitta. ”Card” on tuloskortti tai keltainen tai punainen kortti. ”On report” tarkoittaa laukauksen äänestä. ”Squad” on FITASCin enintään kuuden ampujan erä; ClayAwayssa se tarkoittaa myös matkan alaryhmää.", "Muut kielet tuovat lisää ansoja. Ranskan ”chandelle” on lähes pystysuora kiekko (englannin teal), ei englannin chandelle. Ranskan ”en battue” ja italian ”in battuta” tarkoittavat ajettua riistaa, eivät battue-kiekkoa; portugalin ”batida” on battue-kiekko, ”de batida” tarkoittaa ajettua. Osumasta ranskalainen tuomari sanoo ”Bon”, italialainen ”Buono”; heittäjä on ”pulleur” tai ”puller”. Italian säännöt käyttävät erästä eri sanoja: batteria Parcours de Chasse – Sporting™ -lajissa, squadra di tiro Compak®-lajissa."], "key_points": ["Valmentajan ”smoked it” = täydellinen osuma; sääntöjen ”vain pölyä tai savua” = nolla", "Dead / kill = osuma; lost / dropped = ohi; straight = virheetön sarja", "Trap = heitin; stand = yksi ampumapaikka; peg = merkitty paikka; broken gun = avattu ase", "Pull, card, report ja squad merkitsevät kukin useampaa asiaa", "Ranskan chandelle ja ”en battue” eroavat englannin sanoista"], "terms": ["one", "zero", "visible-piece", "trap", "shooting-stand", "squad", "call", "double-on-report", "pull-away", "length-of-pull", "yellow-card", "score-sheet", "battue", "teal", "false-friend", "peg", "smoked-it"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Smoked it!", "meaning": "Täydellinen osuma, kiekko muuttui pölyksi. Ei sääntöjen ”vain savua”.", "say": "Pölyksi!"}, {"en": "Only dust — zero.", "meaning": "Tuomari: näkyvää palaa ei irronnut, joten se on ohi.", "say": "Vain pölyä – ohi."}, {"en": "Just a chip, but it’s dead.", "meaning": "Pieni näkyvä pala irtosi: se lasketaan osumaksi.", "say": "Vain sirpale, mutta osuma."}, {"en": "Break your gun.", "meaning": "Avaa ase. Ei mitään tekemistä rikkomisen kanssa.", "say": "Taita ase."}, {"en": "Step into the peg.", "meaning": "Asetu merkitylle ampumapaikalle.", "say": "Astu ampumapaikalle."}, {"en": "The second one’s on report.", "meaning": "Toinen kiekko lähtee ensimmäisen laukauksesi äänestä.", "say": "Toinen lähtee laukauksesta."}], "quiz": [{"q": "Valmentaja huudahtaa laukauksen jälkeen ”Smoked it!”. Mitä tapahtui?", "options": ["Kiekosta irtosi vain savua: nolla", "Kiekko tuhoutui: täydellinen osuma", "Patruuna ei lauennut", "Kiekko oli pölykiekko"], "answer": 1, "why": "Valmentajien slangissa ”smoked it” on täydellinen osuma; säännöissä ”vain pölyä tai savua” on nolla – vastakkaiset merkitykset."}, {"q": "Paras suomennos tuomarin sanalle ”Lost.”?", "options": ["”Kadonnut”", "”Aikaa menetetty”", "”Ohi”", "”Kiekko katosi”"], "answer": 2, "why": "”Lost” on pisteytyssana ohilaukaukselle (nolla), ei jotakin kadonnutta."}, {"q": "Ranskalainen vieras sanoo rakastavansa ammuntaa ”en battue”. Mitä hän tarkoittaa?", "options": ["Ajettua riistaa (linnut ajetaan ampujien yli)", "Litteää battue-kiekkoa", "Parina heitettyä kiekkoa", "Rikkoutunutta kiekkoa"], "answer": 0, "why": "Ranskan ”en battue” (italiaksi ”in battuta”) tarkoittaa ajettua riistaa; battue-kiekko on eri asia."}]}, {"id": "interpreter-numbers-and-units", "minutes": 5, "title": "Luvut ja yksiköt: jalat, jaardit, kaliiperit, haulikoot", "body": ["Brittiläiset ja amerikkalaiset valmentajat mittaavat ennakon jaloissa: ”give it three feet”, ”a yard in front”, ”half a bird”, ”a barrel's width”. Tämä on mielikuva, ei mittaus. Käännä yksikkö sellaisenaan, ”kolme jalkaa”, äläkä muunna sitä kesken ohjeen: 0,9 m kuulostaa tarkalta ja muuttaa merkitystä. Selitä kerran ennen harjoitusta, että valmentajien jalat ovat vaikutelma, ja säilytä ”enemmän”, ”vähemmän”, ”tuplaa se” täsmälleen niin kuin sanottiin.", "Etäisyydet kiekkoihin ovat toinen asia. ”It's about thirty yards” voidaan antaa metreinä sanan ”noin” kanssa (”noin 27 metriä”), koska jaardi on hieman alle metrin. Suunnat annetaan usein kellotaulun mukaan: suoraan edessä on 12, joten ”pick it up at eleven o'clock” on hieman vasemmalla. Säilytä kello; älä muuta sitä asteiksi.", "Kaliiperi toimii takaperin. ”12-bore” tai ”12 gauge” ei ole 12 mm; mitä pienempi luku, sitä leveämpi piippu, joten kaliiperi 20 on kapeampi. Molemmat FITASCin sääntökirjat sallivat enintään kaliiperin 12 ja vähintään 66 cm:n (26 tuuman) piiput. Parcours de Chasse – Sporting™ -lajin liivin merkkiviiva on 25 cm, mitä brittiampujat saattavat kutsua vähän alle kymmeneksi tuumaksi.", "Patruunat: FITASC sallii enintään 28 g lyijyä, mikä on lähellä brittiampujien mainitsemaa ”one-ounce load” -latausta, ja haulikoon 2,0–2,5 mm. Haulinumerot eivät ole samat kaikissa maissa: nro 9 on lähes kaikkialla noin 2 mm, mutta muut numerot voivat erota hieman brittiläisessä, amerikkalaisessa ja mannermaisessa järjestelmässä. Kun sillä on merkitystä, kysy millimetrit. Supistajat voidaan ilmoittaa niminä, murtolukuina tai ”thou”-yksikköinä (tuuman tuhannesosina); käännä se järjestelmä, jota valmentaja käytti."], "key_points": ["Ennakko jaloissa on mielikuva: säilytä yksikkö, älä koskaan muunna kesken ohjeen", "Etäisyys kiekkoon: jaardit voi muuttaa muotoon ”noin … metriä”", "Kellotaulu suuntiin: 12 = suoraan edessä", "12 gauge ≠ 12 mm; FITASCin enimmäiskaliiperi 12, piiput ≥ 66 cm (26 tuumaa)", "28 g ≈ yksi unssi; haulit 2,0–2,5 mm; haulinumerot vaihtelevat maittain – kysy millimetrit"], "terms": ["lead", "gauge", "barrel-length", "shot-size", "load-weight", "choke", "cartridge", "clock-face"], "sources": [{"title": "Shotgun Life — Does barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}], "coach_says": [{"en": "Give it three feet.", "meaning": "Ennakkokuva, jota valmentaja haluaa; havaittu väli, ei mitattu etäisyys.", "say": "Anna sille kolme jalkaa."}, {"en": "Half that.", "meaning": "Käytä puolet edellisestä ennakosta.", "say": "Puolet siitä."}, {"en": "Pick it up at eleven o’clock.", "meaning": "Etsi kiekko hieman vasemmalta suoraan edestä.", "say": "Ota se kello yhdessätoista."}, {"en": "It’s about forty yards out.", "meaning": "Kiekko on noin 37 metrin päässä.", "say": "Se on noin neljänkymmenen jaardin päässä."}, {"en": "Put a nine in the bottom barrel.", "meaning": "Lataa nro 9:n haulipatruuna (noin 2 mm) alempaan piippuun, joka yleensä laukeaa ensin.", "say": "Laita ysi alapiippuun."}], "quiz": [{"q": "Valmentaja sanoo ”Give it four feet.” Mikä on paras tulkinta?", "options": ["”Ennakko – noin 1,22 metriä”", "”Ennakko – neljä jalkaa”", "”Ammu neljä metriä kauemmas”", "”Neljä kiekkoa eteenpäin”"], "answer": 1, "why": "Ennakko jaloissa on mielikuva; sen muuntaminen kesken ohjeen lisää näennäistä tarkkuutta ja muuttaa viestiä."}, {"q": "Mikä on suurin sallittu kaliiperi FITASCin Sporting™- ja Compak®-lajeissa?", "options": ["10", "16", "20", "12"], "answer": 3, "why": "Molemmat sääntökirjat sallivat enintään kaliiperin 12; pienempi kaliiperiluku tarkoittaa leveämpää piippua, joten 10 ei ole sallittu."}, {"q": "Brittiläinen vieras kysyy, ovatko hänen ”one-ounce”-patruunansa sallittuja FITASCin kilpailussa. Mitä tiedät?", "options": ["FITASCin raja on 28 g lyijyä (+2 %), mikä on noin yksi unssi", "FITASC sallii 36 g", "Mikä tahansa lataus on sallittu", "Vain 24 g on sallittu"], "answer": 0, "why": "Säännöt sallivat enintään 28 g lyijyä +2 %:n toleranssilla; yksi unssi on noin 28 g. Myös haulikoon (2,0–2,5 mm) on oltava sallittu."}]}, {"id": "interpreter-english-sporting-vs-fitasc", "minutes": 5, "title": "Brittiläiset ja amerikkalaiset sanat FITASCiin verrattuna", "body": ["Monet valmentajat, joiden kanssa työskentelet, ovat kasvaneet English Sportingin parissa, jota Englannissa hallinnoi CPSA, tai amerikkalaisen Sporting Clays -lajin parissa NSCA:n alaisuudessa. Sanat muistuttavat FITASCin sanoja, mutta niiden takana olevat säännöt eivät, ja suurin ero on aseen asento.", "English Sportingissa ja NSCA:ssa ampuja saa aloittaa ”gun up”, ase valmiiksi olalla, ennen kiekon pyytämistä. Parcours de Chasse – Sporting™ -lajissa se ei ole sallittua: tukki pysyy liivin merkkiviivan alapuolella, kunnes kiekko ilmestyy, ja jokainen kiekko ammutaan olalta. Compak® Sporting on siltä väliltä: aseen asento kiekkoa pyydettäessä on vapaa. Siksi ”pre-mount this one” on harjoituksessa harjoite, mutta FITASCin Sporting™-kilpailussa keltainen kortti. Käännä se, ja jos vieras on menossa kilpailemaan, kysy valmentajalta, mainitaanko sääntö.", "Kaksoiskiekoilla on eri nimiä. ”True pair” (englantilainen ja amerikkalainen) on FITASCin yhtäaikainen kaksoiskiekko. ”Report pair” on laukauksesta lähtevä kaksoiskiekko. ”Following pair” on FITASCin rafale. ”Show pair” on kiekkojen näyttäminen ennen ammuntaa. ”Peg” on ampumapaikka, ”station” on amerikkalainen sana ampumapaikalle, ja ”cage” on sen ympärillä oleva kehikko.", "Myös tuloksista puhutaan eri tavoin. ”HOA”, High Over All, on kokonaisvoittaja. Luokat kuten AA, A, B tai C ovat keskiarvoihin perustuvia kansallisia taitotasoja, eivät FITASCin ikäsarjoja eivätkä FITASCin vaikeusluokkia A, B ja C, jotka luokittelevat lentoratoja. Jopa FITASCin sisällä kaksoiskiekot eroavat: Sporting™-lajissa molemmat patruunat saa ampua kaksoiskiekon yhteen kiekkoon, Compak®-lajissa vain yhden patruunan kiekkoa kohden. Kysy aina itseltäsi, mitä sääntökirjaa puhuja tarkoittaa."], "key_points": ["Gun up: sallittu English Sportingissa ja NSCA:ssa, kielletty FITASCin Sporting™-lajissa, vapaa Compak®-lajissa", "True pair = yhtäaikainen; report pair = laukauksesta lähtevä; following pair = rafale", "Peg = ampumapaikka; station = ampumapaikka (USA); cage = suojakehikko", "HOA = kokonaisvoittaja; AA/A/B/C-luokat eivät ole FITASCin sarjoja eivätkä vaikeusluokkia", "Sporting™: molemmat laukaukset yhteen kiekkoon sallittu; Compak®: yksi kiekkoa kohden"], "terms": ["ready-position", "gun-mount", "simultaneous-double", "double-on-report", "rafale-double", "target-presentation", "shooting-stand", "english-sporting", "nsca", "cpsa", "gun-up", "true-pair", "peg", "cage", "hoa", "shooter-class"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "CPSA — English Sporting", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Pre-mount this one for now.", "meaning": "Harjoite: aloita ase valmiiksi olalla. Ei sallittu FITASCin Sporting™-kilpailussa.", "say": "Tämä toistaiseksi ase valmiiksi olalla."}, {"en": "It’s a true pair.", "meaning": "Molemmat kiekot lähtevät samaan aikaan (FITASC: yhtäaikainen kaksoiskiekko).", "say": "Se on yhtäaikainen pari."}, {"en": "Following pair off the left trap.", "meaning": "Kaksi kiekkoa samasta heittimestä peräkkäin (FITASC: rafale).", "say": "Peräkkäinen pari vasemmasta heittimestä."}, {"en": "Let’s see a show pair.", "meaning": "Heitä pari kerran, jotta kaikki näkevät sen ennen ammuntaa.", "say": "Katsotaan näytepari."}, {"en": "He’s AA class and won HOA last year.", "meaning": "Korkea kansallinen taitoluokka ja kilpailun kokonaisvoittaja.", "say": "Hän on AA-luokkaa ja voitti viime vuonna kokonaiskilpailun."}], "quiz": [{"q": "Brittiläinen valmentaja sanoo ”It's a true pair.” Mikä on FITASCin termi?", "options": ["Laukauksesta lähtevä kaksoiskiekko", "Rafale-kaksoiskiekko", "Yhtäaikainen kaksoiskiekko", "Oikea kaksoiskiekko"], "answer": 2, "why": "”True pair” on englantilainen ja amerikkalainen nimi kahdelle yhtä aikaa lähtevälle kiekolle, FITASCin yhtäaikaiselle kaksoiskiekolle."}, {"q": "Missä lajissa ”gun up” -aloitus EI ole sallittu?", "options": ["Parcours de Chasse – Sporting™ (FITASC)", "Compak® Sporting", "English Sporting (CPSA)", "Sporting Clays (NSCA)"], "answer": 0, "why": "FITASCin Sporting™ edellyttää, että tukki on liivin merkkiviivan alapuolella, kunnes kiekko ilmestyy; Compak® jättää aseen asennon vapaaksi."}, {"q": "Vieras lukee brittiläisistä tuloksista ”Class C”. Mikä se on?", "options": ["FITASCin ikäsarja", "Keskiarvoihin perustuva kansallinen taitotaso", "FITASCin vaikein lentorataluokka", "Patruunatyyppi"], "answer": 1, "why": "Brittiläisissä ja amerikkalaisissa tuloksissa luokat ovat taitotasoja; FITASC käyttää A/B/C-merkintää vain lentoratojen vaikeudesta, ja sillä on sen sijaan ikäsarjat."}]}, {"id": "interpreter-session-script", "minutes": 8, "title": "Kokonainen harjoitus vaihe vaiheelta", "body": ["Ennen harjoitusta tapaa valmentaja viideksi minuutiksi. Sovi taukomerkistä, kysy, mitä menetelmää valmentaja opettaa ja mitä sanoja hän käyttää ennakosta, ja opettele hänen käsimerkkinsä. Sitten ryhmä kokoontuu turvallisuusohjeistukseen: tulkkaa se konsekutiivisesti, lause lauseelta, jämäkästi ja kokonaan.", "Ensimmäisellä ampumapaikalla valmentaja aloittaa yleensä ilman patruunoita: silmän hallitsevuuden tarkistus, sitten ampuma-asento ja valmiusasento. FITASCin yhteydessä ase lähtee alhaalta, liivin merkkiviivan alapuolelta. Kuiskaa hänen korjauksensa takaa, kun hän asettelee jalkoja ja käsiä.", "Seuraavaksi luetaan kiekko. Valmentaja näyttää sen, kysyy, missä ampuja näkee sen ensimmäisen kerran selvästi, ja määrittää katsepisteen, aseen aloituskohdan ja osumapisteen. Pidä nämä kolme termiä samoina koko päivän, ”katsepiste”, ”aloituskohta”, ”osumapiste”, jotta vieras oppii ne.", "Nyt ammutaan. Kiekkojen välillä valmentaja antaa kahden–viiden sanan vihjeitä; sinä toistat ne, samanpituisina, samassa järjestyksessä, kun ase on auki. Kun ohilaukaus diagnosoidaan, ”behind”, ”over the top”, ”you stopped”, käännä diagnoosi ja korjaus yhdessä. Kehut käännetään samalla innolla.", "Sitten kaksoiskiekot: kumpi kiekko ensin, ”eyes first, then the gun”, toinen laukaus. Lopuksi loppukeskustelu, taas konsekutiivisesti, jossa valmentaja tiivistää kaksi tai kolme asiaa. Kirjoita ne muistiin molemmilla kielillä ja anna muistiinpano vieraalle. Alla on todellisen elämän ilmausketju siinä järjestyksessä, jossa kuulet ne."], "key_points": ["Ennen: taukomerkki, menetelmä, ennakon sanat, käsimerkit", "Turvallisuusohjeistus: konsekutiivisesti, jämäkästi, kokonaan", "Samat kolme termiä koko päivän: katsepiste, aloituskohta, osumapiste", "Vihjeet kiekkojen välillä: sama pituus, ase auki; diagnoosi + korjaus yhdessä", "Loppukeskustelu: kirjoita pääkohdat molemmilla kielillä"], "terms": ["coach", "safety", "eye-dominance", "master-eye", "stance", "ready-position", "gun-mount", "pick-up-point", "hold-point", "break-point", "lead", "maintained-lead", "pull-away", "head-lift", "stopping-the-gun", "follow-through", "double-on-report", "crosser", "rabbit", "choke"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "NSSA-NSCA — Foot position (Ask the instructor)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}], "coach_says": [{"en": "Morning, everyone. Before we load anything, a quick safety briefing.", "meaning": "Harjoituksen alku; tulkkaa ohjeistus konsekutiivisesti ja kokonaan.", "say": "Huomenta kaikille. Ennen kuin lataamme mitään, lyhyt turvallisuusohjeistus."}, {"en": "Guns stay open until you’re on the stand and I say “load”.", "meaning": "Ei suljettuja aseita ampumapaikan ulkopuolella; lataus vain valmentajan luvalla.", "say": "Aseet pysyvät auki, kunnes olette ampumapaikalla ja sanon ”lataa”."}, {"en": "Point at my nose, both eyes open. Now close your left eye.", "meaning": "Silmän hallitsevuuden tarkistus: jos sormi hyppää, oikea silmä ei ole hallitseva silmä.", "say": "Osoita nenääni, molemmat silmät auki. Sulje nyt vasen silmä."}, {"en": "Front foot pointing at the break point, weight forward.", "meaning": "Ampuma-asento: aseta jalat sen mukaan, missä kiekko rikotaan; nojaa hieman eteenpäin.", "say": "Etujalka osoittaa osumapisteeseen, paino eteen."}, {"en": "Gun down, stock under the line. Mount only when you see it.", "meaning": "FITASCin valmiusasento: ase nousee vasta, kun kiekko on ilmestynyt.", "say": "Ase alhaalla, tukki viivan alla. Nosta vasta, kun näet sen."}, {"en": "Watch this one. Where do you first see it clearly?", "meaning": "Valmentaja määrittää katsepistettä.", "say": "Katso tätä. Missä näet sen ensimmäisen kerran selvästi?"}, {"en": "Hold your muzzles about halfway back, just under the line.", "meaning": "Aloituskohta katsepisteen ja osumapisteen välissä, hieman kiekon radan alapuolella.", "say": "Pidä piipunsuut noin puolivälissä takaisin päin, juuri linjan alla."}, {"en": "Behind it. Give it more.", "meaning": "Laukaus meni kiekon taakse: lisää ennakkoa.", "say": "Takana. Anna lisää."}, {"en": "Call it three feet — that’s the picture you want.", "meaning": "Ennakkokuva, joka laukaushetkellä pitäisi nähdä; jalat vaikutelmana, säilytä yksikkö.", "say": "Sanotaan kolme jalkaa – se on kuva, jota haet."}, {"en": "Over the top. You lifted your head — stay in the gun.", "meaning": "Ohi yläkautta, koska poski irtosi tukista.", "say": "Yli. Nostit pään – pysy aseessa."}, {"en": "Smoked it! Same again.", "meaning": "Täydellinen osuma; toista täsmälleen se, mitä teit.", "say": "Pölyksi! Samoin uudestaan."}, {"en": "You stopped the gun. Keep it moving through the shot.", "meaning": "Ohi takaa, koska aseen liike pysähtyi; saatto.", "say": "Pysäytit aseen. Pidä se liikkeessä laukauksen läpi."}, {"en": "Next is a report pair: crosser first, then the rabbit.", "meaning": "Jäniskiekko lähtee sivukiekkoon ammutun laukauksen äänestä.", "say": "Seuraavaksi laukauksesta lähtevä pari: sivukiekko ensin, sitten jänis."}, {"en": "Eyes first, then the gun.", "meaning": "Toisessa kiekossa löydä se silmillä ennen kuin liikutat piipunsuita.", "say": "Ensin silmät, sitten ase."}, {"en": "Keep the muzzles under the rabbit.", "meaning": "Pysy matalalla vierivässä kiekossa, jotta pomppukin osuu hauliparveen.", "say": "Pidä piipunsuut jäniksen alla."}, {"en": "Change to quarter and half for this stand.", "meaning": "Vaihda 1/4- ja 1/2-supistajat (avoin, sitten hieman tiukempi).", "say": "Vaihda tälle paikalle neljännes ja puolikas."}, {"en": "Let’s call it a day. Three things for tomorrow: feet, head, follow-through.", "meaning": "Harjoituksen loppu; valmentaja tiivistää – kirjoita nämä muistiin vieraalle.", "say": "Lopetetaan tältä päivältä. Kolme asiaa huomiseksi: jalat, pää, saatto."}], "quiz": [{"q": "Milloin ja miten turvallisuusohjeistus tulkataan?", "options": ["Lyhyesti kuiskaustulkkauksena vieraiden ladatessa", "Alussa, konsekutiivisesti, lause lauseelta ja kokonaan", "Vain jos vieras pyytää", "Ensimmäisen ampumapaikan jälkeen"], "answer": 1, "why": "Turvallisuus tulee ensin, eikä sitä saa lyhentää; konsekutiivitulkkaus varmistaa, että jokainen sääntö menee perille."}, {"q": "Valmentaja sanoo ”Behind it. Give it more.” Mikä on paras lyhyt käännös kiekkojen välillä?", "options": ["”Olit vähän myöhässä, yritä uudelleen, ehkä vähän nopeammin”", "”Takana. Lisää ennakkoa.”", "”Ammu aikaisemmin”", "”Hyvä, samoin”"], "answer": 1, "why": "Peilaa valmentajaa: sama pituus, sama järjestys, diagnoosi ja korjaus, ei mitään lisättyä."}, {"q": "Miksi ”pick-up point”, ”hold point” ja ”break point” kannattaa pitää samoina suomenkielisinä sanoina koko päivän?", "options": ["Säännöt vaativat sitä", "Jotta valmentaja ymmärtäisi suomea", "Jotta vieras oppii kolme vakiintunutta käsitettä eikä sekoita niitä", "Sillä ei ole merkitystä"], "answer": 2, "why": "Johdonmukaiset termit rakentavat vieraalle selkeän kuvan ampumapaikasta; sanojen vaihtelu saa kolme käsitettä näyttämään kuudelta."}]}]}]};
